//@@ START - acq_exp
// Acquisition Expenses                                                                                             
// Column:ACQ_EXP
//========================================================
double FIA_LIAB_UDF::fia_liab_acq_exp(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(1,"acq_exp",t);
}



//^^^

#line 1 "acq_exp.FIA_LIAB.for"
if (t <= 0 || (t + elapsed_mths) != 1)
	return NO_AVG;
	
double adj_mult = exp_adj_mult;
double acq_exp_per_pol = 0.0;
double acq_exp_pct_prem = 0.0;

acq_exp_per_pol
= this->acq_exp_per_pol 
  * infl_cumul(t - 1) 
  * policies_b(t)
  * adj_mult;

acq_exp_pct_prem
= (this->acq_exp_pct_prem + acq_exp_allow_level_aig) // ZL 20251013 : added for Acquisition Expenses allowance
  * single_prem
  * adj_mult;

// AA 20220523
double acq_exp_cv = acq_exp_per_pol + acq_exp_pct_prem;

if ( gsia_reins_defn_aig == REINSURER ) 
{
	acq_exp_pct_prem *= quota_share_reinsured_aig;
	acq_exp_cv = acq_exp_per_pol + acq_exp_pct_prem;

	acq_exp_cv += gwl_acq_exp_allow_aig(t); 
}
else if ( gsia_reins_defn_aig == CEDANT )
{
	acq_exp_cv -= gwl_acq_exp_allow_aig(t);
}
// AA 20220523 END

return acq_exp_cv;

}


//@@ END

