// Administration Fee                                                                                             
// Column:ADMIN_FEE
//========================================================
double FIA_LIAB_UDF::fia_liab_admin_fee(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(6,"admin_fee",t);
}



//^^^

#line 1 "admin_fee.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/)//WTW - Gen2 - refined time guards
	return NO_AVG;

if (pol_mth(t) != 1) 
	return 0.0;
	
//return sum_over_funds("admin_fee", t, SUM_OVER_ALL);
//WTW - Gen2 Column Interface
double total = 0.0;

for (int i = 0; i < sm_fia_account.size(); i++)
	total += sm_fia_account[i]->admin_fee(t);

return total;

}


