//@@ START - ann_claims_gmwb
// Annuity Claims - GMWB                                                                                             
// Column:ANN_CLAIMS_GMWB
//========================================================
double FIA_LIAB_UDF::fia_liab_ann_claims_gmwb(int t) {
//^^^



//^^^

#line 1 "ann_claims_gmwb.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/)//WTW - Gen2 - refined time guards
	return NO_AVG;

if (!gmwb_flag)
	return 0.0;

// 20180930 MTC - Moved most of claim tail logic to ann_claims_gmwb_bef_maturity
// Check against maturity benefit amount

//20210630 STW: returns the "pure" claim part only, maturity benefit is not included in the claim
return max(ann_claims_gmwb_bef_maturity_aig(t) - maturity_benefits(t), 0);
// 20180930 MTC END

}


//@@ END

//@@ START - ann_claims_gmwb_bef_maturity_aig
// Annuity Claims - GMWB before check against maturity                                                                                             
// Column:ANN_CLAIMS_GMWB_BEF_MATURITY_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_ann_claims_gmwb_bef_maturity_aig(int t) {
//^^^



//^^^

#line 1 "ann_claims_gmwb_bef_maturity_aig.FIA_LIAB.for"
if (t <= commencement_period || t > final_period)//WTW - Gen2 - refined time guards
	return NO_AVG;

if (!gmwb_flag || withdrl_benefits_gross_excess_e_bef_aig(t) > SMALL_DOUBLE)
	return 0.0;

xol_gmwb_claim_crbg(t); // ZL 250430: force call for XOL GLB claims.

if (
	(
		(fund_val_b_bef(t) >= model_point_amount_threshold && fund_val_b(t) < model_point_amount_threshold) ||  // Check for claim trigger due to fees
		(fund_val_e_bef(t) >= model_point_amount_threshold && fund_val_fixed(t) < model_point_amount_threshold) // Check for claim trigger due to fund releases
	) 
	
	&& (gmwb_inf_bef(t) >= model_point_amount_threshold) 

   )
{
	double period_wdl_floor = 0.0; 
	double period_wdl = 0.0;
	double period_wdl_grossed_up = 0.0; 
	double disc_wdls = 0.0;
	double rem_gmwb_base = 0.0;
	double period_disc = 1.0;
	double wdl_period = 1.0;

	vector< vector <xstring> > debug_output;

	if (pfwd_freq == MONTHLY)
	{
	   wdl_period = 1.0;
	}
	else if (pfwd_freq == QUARTERLY)
	{
	   wdl_period = 3.0;
	}
	else // Annual withdrawal
	{
	   wdl_period = 12.0;
	}

	double proj_yr_mths_remaining = 12 - pol_mth(t);
	double proj_yr_wdls_remaining = trunc(proj_yr_mths_remaining / wdl_period) + 1;

	int policy_year_oloop							= xint(pol_yr(t));
	int gmwb_withdrawal_yr							= min(policy_year_oloop, xint(gmwb_exercise_yrs_aig(t)) + gmwb_req_yrs_wait + 1);  // 20200303 MTC - Confinement rider, dynamic exercise
	int gmwb_withdrawal_mth	= min(max(t, gmwb_req_yrs_wait * 12 + 1), (xint(gmwb_exercise_yrs_aig(t)) + gmwb_req_yrs_wait) * 12 + 1);		

	double mawp;
	double mawa;
	double pipp;
	double pip;
	int moe;

	double fund_val = fund_released_maturity(t);

	if (ann_benefits_partial_interest_credited_defn_aig == YES)
	{
		fund_val *= (1.0 + crediting_rate_partial_e_bef_aig(t));
	}

	if (ann_benefits_min_wdl_val_defn_aig == YES)
	{
		fund_val = max(fund_val, min_wdl_val_final_e_bef_maturity_aig(t));
	}

	mawp										= calc_mawp_pct_aig(t, gmwb_withdrawal_mth, gender_mp, NO_EXERCISE,GMWB_CLAIM); 
	mawa										= mawp * gmwb_inf_bef(t) * wdl_period; 
	pipp										= calc_pipp_pct_aig(t, gmwb_withdrawal_mth, gender_mp);
	pip											= pipp * gmwb_inf_bef(t) * wdl_period; 
	moe											= fund_val_exhaust_aig(t, fund_val, mawa);	

	period_wdl_floor = gmwb_mawa_floor_e_bef_aig(t) / 12.0 * wdl_period;
	
	period_wdl = max(period_wdl_floor, mawa / 12.0); 

	if(lad_type_aig == "AIG 2022 LAD" && t== maturity_benefits_period_aig)
	{
		//double cash_val_cv = 0.0;
		//cash_val_cv = cash_val_bef(t);

		moe = fund_val_exhaust_aig(t, fund_val, mawa, FALSE);//pass optional parameter FALSE for rounding to nearest month

	}
	
	period_wdl_grossed_up = gmwb_entitlement_remaining_e_bef_aig(t) / proj_yr_wdls_remaining;

	
	period_wdl *= surv_period(t);
	period_wdl_grossed_up *= surv_period(t);
	

	if(gmwb_claim_disc_rate_defn == FIXED_INPUT)
	{
		period_disc = pow(1.0 + gmwb_claim_disc_rate , 1.0 / 12.0 * wdl_period);
	}
	else if(alm_flag)
	{	
		if(disc_rate_port_yld_defn == AFTER_TAX)
		{
			period_disc = pow(1.0 + asset_yld_less_dflt_inv(t - 1) * (1.0 - tax_rate), 1.0 / 12.0 * wdl_period);
		}
		else
		{
			period_disc = pow(1.0 + asset_yld_less_dflt_inv(t - 1), 1.0 / 12.0 * wdl_period);
		}		
	}
    else if(gmwb_claim_disc_rate_defn == ASSET_YIELD)
	{
		if(disc_rate_port_yld_defn == AFTER_TAX)
		{
			period_disc = pow(1.0 + asset_yld_less_dflt_inv(t - 1) * (1.0 - tax_rate), 1.0 / 12.0 * wdl_period);
		}
		else
		{
			period_disc = pow(1.0 + asset_yld_less_dflt_inv(t - 1), 1.0 / 12.0 * wdl_period);
		}
	}
	else if(gmwb_claim_disc_rate_defn == AIG_DISCOUNT_CURVE)
	{
		period_disc = pow(1.0 + disc_rate_aig_curve_uel_aig(t), wdl_period);
	}
	else
	{
		throw FatalError("Unhandled GMWB discount type requested in ann_claims_gmwb!");
	}

	if (gmwb_defn == FINITE)
	{
		// 20180924 MTC - Moved this to inner scope to improve runtime
		disc_wdls = min(gmwb_inf(t), period_wdl - withdrl_benefits(t));//  add remaining max wdl not taken this period
		rem_gmwb_base = gmwb_inf(t) - disc_wdls;

		double rem_periods = 0.0;
		double rem_pfwd = 0.0;
		rem_periods = floor(rem_gmwb_base / period_wdl);
		rem_pfwd = rem_gmwb_base - rem_periods * period_wdl;
		disc_wdls += period_wdl 
					* (1.0 - pow(1.0 / period_disc, rem_periods)) / (period_disc - 1.0);
		disc_wdls += rem_pfwd * pow(1.0 / period_disc, rem_periods + 1);
	}
	else
	{ // if (gmwb_defn == LIFE)
		int max_period = (term_to_omega_age * 12) - elapsed_mths;
		double cumm_discount = 1.0; 

		disc_wdls = period_wdl_grossed_up - withdrl_benefits(t);

		int projection_year = int((t + elapsed_mths - 1) / 12.0 + 1); 

		int pol_yr = 0;
		double cumm_surv = 1.0;
		double surv_perc = 1.0; 

		for (int i = t + wdl_period; i <= max_period; i += wdl_period)
		{
			pol_yr = int((i + elapsed_mths - 1) / 12.0 + 1);

			double projection_wdl_cv;
				
			if(gmwb_mawp_pipp_split_aig == YES)
			{//before exhaust uses mawa, after uses pipp					
				if (i <= moe + t + elapsed_mths)							
				{						
					period_wdl = mawa / 12;						
				}						
				else							
				{						
					period_wdl = pip / 12;						
				}			
					
				period_wdl  *= surv_period(t);

			}						

			if ( pol_yr == projection_year )
			{
				projection_wdl_cv = period_wdl_grossed_up;
			}
			else
			{
				projection_wdl_cv = period_wdl;
			}

			if(!alm_flag && gmwb_claim_disc_rate_defn == AIG_DISCOUNT_CURVE)
			{
				//force call all discounting curves
				disc_rate_1(i);
				disc_rate_aig_curve_ic_uel_aig(i);
				disc_rate_aig_curve_no_uel_aig(i);
				period_disc = pow(1.0 + disc_rate_aig_curve_uel_aig(i), wdl_period); 
			}

			cumm_discount /= period_disc; 

			if (spousal_continuation_defn_aig == SPOUSAL_2019)
			{
				surv_perc = pow(1.0 - pv_gmwb_benefit_mort_rate_calc_spousal_2019_aig(t + wdl_period, i, max_period, 1.0), wdl_period);
			}
			else
			{
				surv_perc = pow(1.0 - dth_claim_rate_mthly_experience_aig(i), wdl_period);
			}

			cumm_surv *= surv_perc; 

			if(lad_type_aig == "AIG 2022 LAD" && t== maturity_benefits_period_aig && i <= moe + t + elapsed_mths)
			{
				disc_wdls += projection_wdl_cv * cumm_discount; 
			}
			else
			{
				disc_wdls += projection_wdl_cv * cumm_surv * cumm_discount;
			}

			if(gmwb_claim_print_debug_output_defn_aig == YES)
			{
				vector<xstring> debug_row = {
											 xstring(i),
											 xstring(period_disc),
											 xstring(cumm_discount),
											 xstring(surv_perc),
											 xstring(cumm_surv),
											 xstring(mawp),
											 xstring(gmwb_inf_bef(t)),
											 xstring(projection_wdl_cv * cumm_surv), 
											 xstring(disc_wdls)
										    };

				debug_output.push_back(debug_row);
			}
		}

		
		if(gmwb_claim_print_debug_output_defn_aig == YES)
		{
			gmwb_claim_print_debug_output_aig(debug_output);
		}
	}

	return disc_wdls;
}
else
{
	return 0.0;
}


}


