//@@ START - cash_val
// Cash Value                                                                                             
// Column:CASH_VAL
//========================================================
double FIA_LIAB_UDF::fia_liab_cash_val(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(51,"cash_val",t);
}



//^^^

#line 1 "cash_val.FIA_LIAB.for"
if (t < commencement_period || t > final_period/*maturity_period*/)//WTW - Gen2 - refined time guards
{
	return NO_AVG;
}
else
{
	double cash_value;
	if ( cash_surrender_value_defn_aig == FUND_VALUE )
	{
		//20180831 LZ - Added GMWB fee at surrender
        // 20220701 STW: include paritial strategy fee at surrender
		cash_value 
			= max(fund_val_fixed(t) - surr_chg_inf(t) - mva_amt_full_surr_cash_val_aig(t) - gmwb_chg_at_surr_aig(t) - gmab_chg_partial_e_aig(t) 
            - tier_strat_fee_at_surr_aig(t) - prem_bonus_recapture_e_aig(t), 0.); // DTL 20181105 : deducting bonus recapture

		// Floor cash value at MWV
		cash_value = max(cash_value, min_wdl_val_final_e_aig(t));
		// 20180707 END
		
		//20250609 ZL GROP for GMAB 
		if (gmab_ind_aig == 1 && gmab_type_crbg == AICO //20260324 AICO only
			&& t + elapsed_mths >= gmab_csv_grop_yr_aig * 12 && fund_val_fixed(t) > SMALL_DOUBLE) 
		{
			cash_value = max(cash_value, prem_cumul_proportional_wdl_aig(t));
		}

		//20210723 STW: Throw an error message if the input is set wrong
		if (state_var_rider_fee_chg_aig == ALLOW_DEDUCT)
		{
			throw FatalError("Non-X5 Products should not allow rider fee deduction in state_var_rider_fee_chg_aig, please double check the input.");
		}

	}
	// 20200603 DTL: NYIA
	else if ( cash_surrender_value_defn_aig == NYIA_CASH_VALUE )
	{
		double pfwd_entitlement_e_cv = pfwd_entitlement_remaining_e(t);
		double mav_e_cv              = min_accum_val_e_aig(t);

		pol_yr_lookup_gen2 = pol_yr(t);//WTW - Gen2 - surr_chg_pct cannot use time based lookup in an external formula - need to update all instances to use this working variable
		double mav_surr_val_cv	     = mav_e_cv - surr_chg_pct * (mav_e_cv - pfwd_entitlement_e_cv);

		double fund_val_e_cv         = fund_val_fixed(t);
		
		pol_yr_lookup_gen2 = pol_yr(t);//WTW - Gen2 - surr_chg_pct cannot use time based lookup in an external formula - need to update all instances to use this working variable		
		double fund_surr_val_cv      = fund_val_e_cv - surr_chg_pct * (fund_val_e_cv - pfwd_entitlement_e_cv);

		cash_value = max(mav_surr_val_cv, fund_surr_val_cv);

		//20210723 STW: Throw an error message if the input is set wrong
		if (state_var_rider_fee_chg_aig == ALLOW_DEDUCT)
		{
			throw FatalError("Non-X5 Products should not allow rider fee deduction in state_var_rider_fee_chg_aig, please double check the input.");
		}
	}
	// 20200603 DTL: NYIA
	else
	{	// DTL 20180925 : Added error branch
		throw FatalError("fia->cash_val : unhandled value for `cash_surrender_value_defn_aig`!");
	}

	// 20200228 MTC - Added GROP feature
	if ( grop_flag(t) == 1 )
	{
		cash_value = max(cash_value, grop_inf_aig(t));
	}
	// 20220311 JYL - Added SNFL Prospective Functionality
	if (ca_mva_cv_floor_aig == YES)
	{
		cash_value = max(cash_value , snfl_prospective_e_aig(t));
	}

	return cash_value;
}


}


