//@@ START - comm_chargeback
// Commission Chargeback                                                                                             
// Column:COMM_CHARGEBACK
//========================================================
double FIA_LIAB_UDF::fia_liab_comm_chargeback(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(63,"comm_chargeback",t);
}



//^^^

#line 1 "comm_chargeback.FIA_LIAB.for"
if (t <= start_period || t > final_period/*maturity_period*/ || t > comm_chargeback_period_mths_aig)//WTW - Gen2 - refined time guards
{
	return NO_AVG;
}
else
{
	double commission_base = comm_subject_to_chargeback(t) * comm_chargeback_pct_aig; // DTL 20181105 : make pct a table-driven value
	double recapture_pct = 1 - surv_period(t);	// DTL 20181105 : all decrements trigger recapture
	double recaptured_comm = commission_base * recapture_pct;

	//20240513 FA logic, ignoring annuitization for now
	if (fixed_annuity_ind_aig == YES)
	{
		recaptured_comm = comm_subject_to_chargeback(t) * comm_chgback_pct_dth_aig * dth_claim_rate_mthly(t)
					+ comm_subject_to_chargeback(t) * comm_chgback_pct_surr_aig * (1.0 - dth_claim_rate_mthly(t)) * lapse_rate_mthly(t);
	}

	return recaptured_comm;

}



}


//@@ END

