//========================================================
double FIA_LIAB_UDF::fia_liab_crediting_asset_yld_sprd_aig(int t) {
//^^^



//^^^

#line 1 "crediting_asset_yld_sprd_aig.FIA_LIAB.for"
/*! Pricing Spread
	==============
	@author ???
	@date ???
 
	This simple column sums `crediting_pri_sprd_aig` over all the subfunds.
 
	Related Inputs:
	---------------
	-# `crediting_pri_sprd_aig` - Sum of all fiaafund_liab_crediting_pri_sprd_aig() from each subfund.
	.
 
	@return Sum of `crediting_pri_sprd_aig` from each subfund.
*/

if (t <= commencement_period || t > final_period/*maturity_period*/)//WTW - Gen2 - refined time guards
	return NO_AVG;

//return sum_over_funds("crediting_pri_sprd_aig", t, SUM_OVER_ALL);
//WTW - Gen2 Column Interface
double total = 0.0;

for (size_t i = 0; i < sm_fia_account.size(); i++)
{
	if (fund_val_b_bef(t) > SMALL_DOUBLE)
	{
		// Weigh by current allocation
		total += sm_fia_account[i]->crediting_pri_sprd_aig(t) * (sm_fia_account[i]->fund_val_b_bef(t) / fund_val_b_bef(t));
	}
	else
	{
		// Weigh by initial allocation
		total += sm_fia_account[i]->crediting_pri_sprd_aig(t) * (sm_fia_account[i]->fund_val_split_prop);
	}
}

return total;

}


