//@@ START - dth_ben_inf
// Death Benefit In Force                                                                                             
// Column:DTH_BEN_INF
//========================================================
double FIA_LIAB_UDF::fia_liab_dth_ben_inf(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(106,"dth_ben_inf",t);
}



//^^^

#line 1 "dth_ben_inf.FIA_LIAB.for"
if (t < commencement_period || t > final_period/*maturity_period*/)//WTW - Gen2 - refined time guards
	return NO_AVG;

// Added partial interest crediting logic to death benefits.  MCHING 12-11-2021
double dth_ben;
double fund_val = fund_val_fixed(t);

if (dth_ben_partial_interest_credited_defn_aig == YES)
{
	fund_val *= (1.0 + crediting_rate_partial_e_bef_aig(t));
}

if (dth_ben_defn == FUND_VALUE)
{
	dth_ben = max(fund_val, contract_val(t));
}
else if (dth_ben_defn == CASH_VALUE) 
{
	dth_ben = cash_val(t);
}
else if (dth_ben_defn == MAX_FUND_AND_CASH_VALUES)
{
	dth_ben = max(fund_val, cash_val(t));
}
// Standard IA base product death benefit
else if (dth_ben_defn == MAX_FUND_VALUE_AND_MWV)
{
	dth_ben = max(max( 0 , fund_val - prem_bonus_recapture_e_aig(t) - gmab_chg_partial_e_aig(t)), min_wdl_val_final_e_aig(t));
}
else if (dth_ben_defn == NYIA_DEATH_BENEFIT)
{
	double mav_e_cv      = min_accum_val_e_aig(t);

	dth_ben              = max(mav_e_cv, fund_val);
}
else
{
	throw FatalError("Unhandled dth_ben_defn requested in dth_ben_inf!");
}
// END MCHING 12-11-2021

//20250609 ZL GROP for GMAB 
if (gmab_ind_aig == 1 && gmab_type_crbg == AICO //20260324 AICO only
	&& t + elapsed_mths >= gmab_csv_grop_yr_aig * 12 && fund_val > SMALL_DOUBLE) 
{
	dth_ben = max(dth_ben, prem_cumul_proportional_wdl_aig(t));
}

//20210723 STW: cap death benefit at a certain level due to state specific regulation
if (state_var_dth_bene_cap_aig == CAP)	
{
	dth_ben = min(dth_ben, dth_ben_cap_aig * cash_val(t));
}
return dth_ben;

}


//@@ END

