// GMWB claim start t                                                                                             
// Column:GMWB_CLAIM_START_DURATION_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_gmwb_claim_start_duration_aig(int t) {
//^^^



//^^^

#line 1 "gmwb_claim_start_duration_aig.FIA_LIAB.for"
// 20180930 MTC - Track GMWB claim starting t
if (t <= commencement_period || t > final_period/*maturity_period*/)//WTW - Gen2 - refined time guards
	return NO_AVG;

if (t == commencement_period + 1)
{
	// Initialize column to t_high
	return t_high;
}

if (
	(
		(fund_val_b_bef(t - 1) >= model_point_amount_threshold && fund_val_b(t - 1) < model_point_amount_threshold) ||  // Check for claim trigger due to fees
		(fund_val_e_bef(t - 1) >= model_point_amount_threshold && fund_val_fixed(t - 1) < model_point_amount_threshold) // Check for claim trigger due to fund releases
	) 
	
	&& (gmwb_inf_bef(t - 1) >= model_point_amount_threshold) 

   )
{
	return t - 1;
}
else
{
	return gmwb_claim_start_duration_aig(t - 1);
}


}


