//@@ START - gmwb_exercise_yrs_aig
// GMWB Exercise Years                                                                                             
// Column:GMWB_EXERCISE_YRS_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_gmwb_exercise_yrs_aig(int t) {
//^^^



//^^^

#line 1 "gmwb_exercise_yrs_aig.FIA_LIAB.for"
//20200303 MTC - Confinement rider, made GMWB exercise year dynamic
if (/*!gmwb_flag ||*/ t < commencement_period || t > final_period/*maturity_period*/)//WTW - Gen2 - refined time guards
	return NO_AVG;

if (!gmwb_flag)
	return NO_AVG;

if (t == commencement_period)
{
	return gmwb_exercise_yrs;
}

int gmwb_exercise_yr;

if (enhanced_income_flag_aig)
{
	if (xint(pol_mth(t)) == 1)
	{
		if (enhanced_income_gmwb_exercise_defn_aig == BEGIN_WITHDRAWALS_AT_CONFINEMENT)
		{
			StrEnum::EnumValue confinement_status			= enhanced_income_confinement_state_get_enum_aig(xint(enhanced_income_confinement_state_b_aig(t)));

			if (confinement_status == NONCONFINED)
			{
				gmwb_exercise_yr							= xint(gmwb_exercise_yrs_aig(t - 1));
			}
			else if (confinement_status == CONFINED)
			{
				if (xint(pol_yr(t)) > gmwb_req_yrs_wait)
				{
					gmwb_exercise_yr						= min(
																	 xint(pol_yr(t)) - gmwb_req_yrs_wait - 1,
																	 xint(gmwb_exercise_yrs_aig(t - 1))
																 );
				}
				else
				{
					gmwb_exercise_yr						= xint(gmwb_exercise_yrs_aig(t - 1));
				}
			}
			else
			{
				throw FatalError("Unhandled confinement_status requested in gmwb_exercise_yrs_aig!");
			}
		}
		else if (enhanced_income_gmwb_exercise_defn_aig == USE_GMWB_EXERCISE_YRS)
		{
			gmwb_exercise_yr								= gmwb_exercise_yrs;
		}
		else
		{
			throw FatalError("Unhandled enhanced_income_gmwb_exercise_defn_aig requested in gmwb_exercise_yrs_aig!");
		}
	}
	else
	{
		gmwb_exercise_yr									= xint(gmwb_exercise_yrs_aig(t - 1));
	}
}
else
{
	gmwb_exercise_yr										= gmwb_exercise_yrs;
}

return gmwb_exercise_yr;


}


