//@@ START - gmwb_income_base_e_aig
// GMWB Income Base, EOM                                                                                             
// Column:GMWB_INCOME_BASE_E_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_gmwb_income_base_e_aig(int t) {
//^^^



//^^^

#line 1 "gmwb_income_base_e_aig.FIA_LIAB.for"
// 20190326 MTC - GMWB benefit base refactor
if (/*!gmwb_flag ||*/ t <= commencement_period || t > maturity_period)//WTW - Gen2 - refined time guards
	return NO_AVG;

if (!gmwb_flag)
	return NO_AVG;

double gmwb_income_base = gmwb_income_base_e_bef_aig(t);

// Reduce base for survivorship
double survivorship = surv_period(t);
gmwb_income_base *= survivorship;

// 20190709 DTL (START): bump up income base for partial-term credit
//gmwb_income_base += gmwb_income_credit_at_wdl_e_aig(t);
// 20190709 DTL (END)

// Set lookup keys for gmwb_income_prem_base_reduction_method_aig
StrEnum::EnumValue income_phase_lookup_original = income_phase_lookup_aig; // DTL 20181112 : need to reset this lookup key before column function returns
set_income_phase_lookup_e_aig(t); // 20181023 MTC - Replaced with timing-specific function

temp_key_inc_phase_aig = income_phase_lookup_aig;//WTW - Gen2 - Mutating Lookup Term
if (gmwb_income_prem_base_reduction_method_aig == CONTRACT_PCT)
{
	// Prorata reduction
	double contract_val_before_wdls, contract_val_after_wdls, reduction_pct, withdrl;
	
	contract_val_before_wdls = fund_val_e_bef(t) * survivorship;

	withdrl = fund_released_withdrl(t);
	contract_val_after_wdls = contract_val_before_wdls - withdrl;

	if ( contract_val_before_wdls < SMALL_DOUBLE )
	{
		reduction_pct = 0.0;
	}
	else
	{
		reduction_pct = contract_val_after_wdls / contract_val_before_wdls;
	}

	gmwb_income_base *= reduction_pct;
}
else if (gmwb_income_prem_base_reduction_method_aig == NO_REDUCTION)
{
	// We use "no reduction" once GLB income begins, but no reduction
	// only applies up to 100% of MAWA.
	double reduction_pct = gmwb_income_base_reduction_fct_e_bef_aig(t);
	gmwb_income_base *= reduction_pct;
}
else
{
	throw FatalError("Unhandled gmwb_income_prem_base_reduction_method_aig requested in gmwb_income_base_e_aig!");
}

// Reset lookup key
income_phase_lookup_aig = income_phase_lookup_original; // DTL 20181112 : need to reset this lookup key before column function returns

// GMWB Income Base Cap bugfix.  MCHING 1-11-2022
if (gmwb_income_base_cap_defn_aig == YES)
{
	gmwb_income_base = min(gmwb_income_base, gmwb_income_base_cap_e_aig(t));
}

gmwb_income_base = max(0.0, gmwb_income_base);

return gmwb_income_base;

}


