//@@ START - gmwb_income_base_reduction_fct_e_bef_aig
// Income base reduction factor (for excess withdrawals):                                                                                             
// Column:GMWB_INCOME_BASE_REDUCTION_FCT_E_BEF_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_gmwb_income_base_reduction_fct_e_bef_aig(int t) {
//^^^



//^^^

#line 1 "gmwb_income_base_reduction_fct_e_bef_aig.FIA_LIAB.for"
if (/*!gmwb_flag ||*/ t < commencement_period || t > maturity_period)//WTW - Gen2 - refined time guards
	return 1.0;

if (!gmwb_flag)
	return 1.0;

double excess_wdl_cv = withdrl_benefits_gross_excess_e_bef_aig(t);

if (abs(excess_wdl_cv) < SMALL_DOUBLE)
{
	return 1.0;
}

double fund_val_e_bef_cv = fund_val_e_bef(t);
double mawa_remaining_e_bef_cv = gmwb_entitlement_remaining_e_bef_aig(t);
double base = max(0, fund_val_e_bef_cv - mawa_remaining_e_bef_cv);

if (abs(base) < SMALL_DOUBLE)
{
	return 0.0;
}


double reduction_fct = max(0, 1 - excess_wdl_cv / base);

return reduction_fct;

}


