//@@ START - gmwb_income_credit_base_e_aig
// GMWB Income Credit Base, EOM                                                                                             
// Column:GMWB_INCOME_CREDIT_BASE_E_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_gmwb_income_credit_base_e_aig(int t) {
//^^^



//^^^

#line 1 "gmwb_income_credit_base_e_aig.FIA_LIAB.for"
// 20190326 MTC - GMWB benefit base refactor
if (/*!gmwb_flag ||*/ t <= commencement_period || t > maturity_period)//WTW - Gen2 - refined time guards
	return NO_AVG;

if (!gmwb_flag)
	return NO_AVG;

double gmwb_income_credit_base = gmwb_income_credit_base_e_bef_aig(t);

// 20190726 DTL (START): add midterm income credit here too
// Select Income Credit Base
/*temp_key_inc_phase_aig = income_phase_lookup_aig;//WTW - Gen2 - Mutating Lookup Term
if (gmwb_rollup_rate_type_aig == COMPOUND)
{
	double partial_credit = gmwb_income_credit_at_wdl_e_aig(t);
	gmwb_income_credit_base += partial_credit;
}*/
// 20190726 DTL (END): add midterm income credit here too

// Reduce base for survivorship
double survivorship = surv_period(t);
gmwb_income_credit_base *= survivorship;

// 20190808 DTL (START): reduce credit base for pre-income withdrawals
StrEnum::EnumValue income_phase_lookup_original = income_phase_lookup_aig;
set_income_phase_lookup_e_aig(t);

temp_key_inc_phase_aig = income_phase_lookup_aig;//WTW - Gen2 - Mutating Lookup Term
if (gmwb_income_prem_base_reduction_method_aig == CONTRACT_PCT)
{
	double contract_val_before_wdls, contract_val_after_wdls, reduction_pct, withdrl;
	
	contract_val_before_wdls = fund_val_e_bef(t) * survivorship;

	withdrl = fund_released_withdrl(t);
	contract_val_after_wdls = contract_val_before_wdls - withdrl;

	if ( contract_val_before_wdls < SMALL_DOUBLE )
	{
		reduction_pct = 0.0;
	}
	else
	{
		reduction_pct = contract_val_after_wdls / contract_val_before_wdls;
	}

	gmwb_income_credit_base *= reduction_pct;
}
else if (gmwb_income_prem_base_reduction_method_aig == NO_REDUCTION)
{
	// No reduction but...we do reduce the income base for excess withdrawals!
	double reduction_pct = gmwb_income_base_reduction_fct_e_bef_aig(t);
	gmwb_income_credit_base *= reduction_pct;
}
else
{
	throw FatalError("Unhandled gmwb_income_prem_base_reduction_method_aig requested in gmwb_income_credit_base_e_aig(t)!");
}

income_phase_lookup_aig = income_phase_lookup_original;
// 20190808 DTL (END)

return gmwb_income_credit_base;

}


