//@@ START - gmwb_income_credit_base_e_bef_aig
// GMWB Income Credit Base, EOM before claims                                                                                             
// Column:GMWB_INCOME_CREDIT_BASE_E_BEF_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_gmwb_income_credit_base_e_bef_aig(int t) {
//^^^



//^^^

#line 1 "gmwb_income_credit_base_e_bef_aig.FIA_LIAB.for"
// 20190326 MTC - GMWB benefit base refactor
if (/*!gmwb_flag ||*/ t <= commencement_period || t > maturity_period)//WTW - Gen2 - refined time guards
	return NO_AVG;

if (!gmwb_flag)
	return NO_AVG;

double gmwb_income_credit_base = 0.0;

// Apply step-up logic
if (t > commencement_period + 1)
{
	StrEnum::EnumValue income_phase_lookup_original = income_phase_lookup_aig;
	set_income_phase_lookup_b_bef_aig(t);

	temp_key_inc_phase_aig = income_phase_lookup_aig;//WTW - Gen2 - Mutating Lookup Term
	if (gmwb_rollup_rate_type_aig == COMPOUND)
	{
		gmwb_income_credit_base = gmwb_income_base_b_aig(t);
	}
	else if (gmwb_rollup_rate_type_aig == SIMPLE)
	{
		gmwb_income_credit_base = gmwb_income_credit_base_e_aig(t - 1);
	}
	else
	{
		throw FatalError("Unhandled gmwb_rollup_rate_type_aig requested in fia_liab->gmwb_income_credit_base_e_bef_aig!");
	}

	// Apply Highest Anniversary Value (HAV) when Income Base increases due to HAV
	// 20220701 STW: new flag for MAV
	if ( (income_phase_lookup_aig == NO_INCOME || income_phase_lookup_aig == PRE_INCOME) && xint(pol_mth(t)) == 1 
		&& gmwb_base_mav_aig == YES)
	{	
		double fund_val = fund_val_fixed(t - 1);
		double gmwb_income_base_aft_income_credit = gmwb_income_base_b_aig(t);

		if ( fund_val - gmwb_income_base_aft_income_credit  > SMALL_DOUBLE )
		{
			gmwb_income_credit_base = max(gmwb_income_credit_base, fund_val);
		}
	}

	// Reset lookup key
	income_phase_lookup_aig = income_phase_lookup_original;
}

// Add premium and bonuses
if (gmwb_prem_credit_pct_defn_aig == INCLUDE_IN_BASE)
{
	gmwb_income_credit_base += prem_paid(t) * (1.0 + prem_credit_pct_aig);
}
else if (gmwb_prem_credit_pct_defn_aig == EXCLUDE_FROM_BASE)
{
	gmwb_income_credit_base += prem_paid(t) * (1.0 + gmwb_prem_credit_aig);
}
else
{
	throw FatalError("Unhandled gmwb_prem_credit_pct_defn_aig requested in fia_liab->gmwb_income_base_b_aig!");
}

return gmwb_income_credit_base;

}


