//@@ START - gmwb_income_credit_e_bef_aig
// GMWB Income Credit, EOM before claims                                                                                             
// Column:GMWB_INCOME_CREDIT_E_BEF_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_gmwb_income_credit_e_bef_aig(int t) {
//^^^



//^^^

#line 1 "gmwb_income_credit_e_bef_aig.FIA_LIAB.for"
if (/*!gmwb_flag ||*/ t <= commencement_period || t > maturity_period)//WTW - Gen2 - refined time guards
	return NO_AVG;

if (!gmwb_flag)
	return NO_AVG;

double gmwb_income_credit;

StrEnum::EnumValue income_phase_lookup_original = income_phase_lookup_aig;
set_income_phase_lookup_b_bef_aig(t);

if (abs(withdrl_benefits_gross_excess_ind_e_aig(t - 1)) > SMALL_DOUBLE && gmwb_income_base_defn != X5)
{
	gmwb_income_credit = 0.0;
}
else 
{
	temp_key_inc_phase_aig = income_phase_lookup_aig;//WTW - Gen2 - Mutating Lookup Term
	StrEnum::EnumValue gmwb_net_credit_aig_local = fia->gmwb_net_credit_aig;//WTW - Gen2 - Mutating Lookup Term used in expression
	if ( 
		xint(pol_mth(t)) == 1						&& 
		pol_yr(t) <= gmwb_max_rollup_duration + 1	&&
		gmwb_net_credit_aig_local != ZERO //WTW - Gen2 - Mutating Lookup Term used in expression
	   )
	{
		double gmwb_income_credit_base = gmwb_income_credit_base_e_aig(t - 1);
		double gmwb_income_credit_rate;

		if (gmwb_prem_rollup_credit_type_aig == CONSTANT_RATE)
		{
			gmwb_income_credit_rate = gmwb_rollup_rate;
		}
		else if (gmwb_prem_rollup_credit_type_aig == INDEX_GROWTH)
		{
			gmwb_income_credit_rate = weighted_ending_strategy_return_gmwb_rollup_aig(t - 1);
		}
		else
		{
			throw FatalError("Unhandled gmwb_prem_rollup_credit_type_aig requested in fia_liab->gmwb_income_credit_e_bef_aig!");
		}

		temp_key_inc_phase_aig = income_phase_lookup_aig;//WTW - Gen2 - Mutating Lookup Term
		gmwb_income_credit_rate *= gmwb_credit_mult_aig;

		temp_key_inc_phase_aig = income_phase_lookup_aig;//WTW - Gen2 - Mutating Lookup Term
		if (gmwb_net_credit_aig == NET)
		{
			double mawp_rate = gmwb_max_annual_wdl_pct_aig(t - 1);
			double utilization_rate = gmwb_wdl_utilization_pct_aig(t - 1);

			gmwb_income_credit_rate -= mawp_rate * utilization_rate;

			gmwb_income_credit_rate = max(gmwb_income_credit_rate, 0.0);
		}

		gmwb_income_credit = gmwb_income_credit_base * gmwb_income_credit_rate;
	}
	else
	{
		gmwb_income_credit = 0.0;
	}
}
income_phase_lookup_aig = income_phase_lookup_original;

return gmwb_income_credit;

}


