//@@ START - gmwb_itm
// GMWB In The Money                                                                                             
// Column:GMWB_ITM
//========================================================
double FIA_LIAB_UDF::fia_liab_gmwb_itm(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(284,"gmwb_itm",t);
}



//^^^

#line 1 "gmwb_itm.FIA_LIAB.for"
// 20200303 MTC - Removed ALT_MODEL option, added error handling for itm_defn
if (/*!gmwb_flag ||*/ t < commencement_period || t > final_period/*maturity_period*/)//WTW - Gen2 - refined time guards
	return NO_AVG;

if (!gmwb_flag)
	return NO_AVG;

if (itm_defn == FUND_VALUE)
{	
	if (fund_val_e_bef(t) > model_point_amount_threshold)	
		return gmwb_inf_bef(t) / fund_val_e_bef(t) - 1.0; // 20190522 DTL : original USL logic...DO NOT floor with new auxillary income floor

	return NO_AVG;	
}
// 20190817 YHH
else if ( itm_defn == ALT_MODEL_WITH_DEATH_BENEFITS )
{
	// 20191108 MTC - Replace intrinsic value with CSV
	double cash_val_bef_cv		= cash_val_bef(t);
	double pv_benefit_itm_cv	= pv_benefit_itm_aig(t);

	double benefits_itm_cv;

	if (cash_val_bef_cv > SMALL_DOUBLE)
	{
		benefits_itm_cv			= pv_benefit_itm_cv / cash_val_bef_cv - 1.0;
	}
	else
	{
		// We should return infinity when no CSV left, not 1.0 - future improvement
		benefits_itm_cv			= 1.0;
	}

	return benefits_itm_cv;
	// 20191108 MTC END
}
// 20190817 YHH END
else if (itm_defn == ANNUITY_BENEFIT)
{
	double gmwb_itm_cv;
	if (fund_val_e_bef(t) < model_point_amount_threshold)
	{
		gmwb_itm_cv = 1.0;
	}
	else if ( surr_chg_period_aig == 0 || (gmwb_income_base_defn == NYIA_GLB_BASE && gmwb_nyia_itm_denominator_aig == CASH_VALUE)) // 20221201 SJ: add new switch for denominator for NYIA product
	{
		// DTL 20200401: add this new return value because it was in the IA team model;
		//               it was not explained to me
		gmwb_itm_cv = pv_benefit_itm_aig(t) / cash_val_bef(t) - 1.0;
	}
	else
	{
		gmwb_itm_cv = pv_benefit_itm_aig(t) / fund_val_e_bef(t) - 1.0;
	}

	return gmwb_itm_cv;
	//	return pv_gmwb_benefit_itm(t) / fund_val_e_bef(t) - 1.0;  MQ change to use AIG ITM.
}
else
{
	throw FatalError("Unhandled itm_defn requested in gmwb_itm!");
}

}


