//@@ START - gwl_make_whole_settlement_adj_aig
// GWL Make Whole Settlement Adj AIG                                                                                             
// Column:GWL_MAKE_WHOLE_SETTLEMENT_ADJ_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_gwl_make_whole_settlement_adj_aig(int t) {
//^^^



//^^^

#line 1 "gwl_make_whole_settlement_adj_aig.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/ || activate_index1_aig == NO || pol_mth(t) != 1)
{
	return NO_AVG;
}

double option_cost_delta = opt_budget_cost_index0_aig(t) - opt_budget_cost_index1_aig(t);

double quota_share_retained = 1 - quota_share_reinsured_aig;

double make_whole_settlement_adj = 0.0;

if ( option_cost_delta > allowable_threshold_deviation_aig )
{
	make_whole_settlement_adj = make_whole_settlement_adj_coef_greater_aig * (option_cost_delta - allowable_threshold_deviation_aig) * fund_val_b(t);

	/* AA 20220523 :fund value will be adjusted by quote_share_reinsured / retained in prem_paid col
					for make_whole formula to be correct, depending on gsia_reins_defn_aig, 
					make_whole needs to be adjusted accordingly to always show the reinsurer's (AIG's) POV */
	if ( gsia_reins_defn_aig == CEDANT )
	{
		make_whole_settlement_adj *= (quota_share_reinsured_aig / quota_share_retained);
	}
}

else if (option_cost_delta >= -max_downward_deviation_aig 
		&& option_cost_delta < -allowable_threshold_deviation_aig)
{
	make_whole_settlement_adj = make_whole_settlement_adj_coef_lower_aig * (option_cost_delta + allowable_threshold_deviation_aig) * fund_val_b(t);

	// AA 20220523
	if ( gsia_reins_defn_aig == REINSURER )
	{
		make_whole_settlement_adj *= (quota_share_retained / quota_share_reinsured_aig);
	}
}

else if (option_cost_delta < -max_downward_deviation_aig)
{
	make_whole_settlement_adj = make_whole_settlement_adj_coef_lower_aig * (-max_downward_deviation_aig + allowable_threshold_deviation_aig) * fund_val_b(t);

	// AA 20220523
	if ( gsia_reins_defn_aig == REINSURER )
	{
		make_whole_settlement_adj *= (quota_share_retained / quota_share_reinsured_aig);
	}
}

return make_whole_settlement_adj;


}


