//@@ START - infl_cumul
// Inflation Cumulative                                                                                             
// Column:INFL_CUMUL
//========================================================
double FIA_LIAB_UDF::fia_liab_infl_cumul(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(330,"infl_cumul",t);
}



//^^^

#line 1 "infl_cumul.FIA_LIAB.for"
if (t < start_period || t > final_period)
	return NO_AVG;

if ((pricing_flag || nb_flag) && t == start_period
	&& valn_period == 0)
	return 1.0;

if (t <= infl_start_period)
	return 1.0;

if (t == start_period && infl_start_period < start_period)
{
	double init_infl_cumul = 1.0;

	for (int i = infl_start_period + 1; i <= 0; i++)
	{
		// 20181022 MTC - Allow for constant inflation rate
		double infl_rate= 0.0;

		if (infl_rate_defn_aig == SCENARIO_FILE)
		{
			if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
				infl_rate = fia_rates->get_infl_rate(i, EFFECTIVE_ANNUAL);
			else
				infl_rate = rates->get_infl_rate(i, EFFECTIVE_ANNUAL);
		}
		else if (infl_rate_defn_aig == CONSTANT)
		{
			infl_rate = infl_rate_const_aig;
		}
		// 20220512 JYL - Add stochastic option for modeling inflation
		else if (infl_rate_defn_aig == STOCHASTIC)
		{	
			double treasury_rate = 0.0;
			if (gen2_defn == YES)
				treasury_rate = fia_rates->get_int_rate(i, "Govt", GET_YIELD_RATE, infl_treasury_yr_aig, 0, EFFECTIVE_ANNUAL, NO_SHIFT, 0);
			else
				treasury_rate = rates->get_int_rate(i, "Govt", GET_YIELD_RATE, infl_treasury_yr_aig, 0, EFFECTIVE_ANNUAL, NO_SHIFT, 0);
			infl_rate = infl_mult_aig * treasury_rate - infl_deduction_aig;
		}
		// 20220512 JYL END
		else
		{
			throw FatalError("Unhandled infl_rate_defn_aig requested in infl_cumul!");
		}
		// 20181022 MTC END

		init_infl_cumul *= pow((1.0 + infl_rate), (1.0 / 12.0));
	}

	return init_infl_cumul;
}

// 20181022 MTC - Allow for constant inflation rate
double infl_rate= 0.0;

if (infl_rate_defn_aig == SCENARIO_FILE)
{
	if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
		infl_rate = fia_rates->get_infl_rate(t, EFFECTIVE_ANNUAL);
	else
		infl_rate = rates->get_infl_rate(t, EFFECTIVE_ANNUAL);
}
else if (infl_rate_defn_aig == CONSTANT)
{
	infl_rate = infl_rate_const_aig;
}
// 20220512 JYL - Add stochastic option for modeling inflation
else if (infl_rate_defn_aig == STOCHASTIC)
{	
	double treasury_rate = 0.0;
	if (gen2_defn == YES)
		treasury_rate = fia_rates->get_int_rate(t, "Govt", GET_YIELD_RATE, infl_treasury_yr_aig, 0, EFFECTIVE_ANNUAL, NO_SHIFT, 0);
	else
		treasury_rate = rates->get_int_rate(t, "Govt", GET_YIELD_RATE, infl_treasury_yr_aig, 0, EFFECTIVE_ANNUAL, NO_SHIFT, 0);
	infl_rate = infl_mult_aig * treasury_rate - infl_deduction_aig;

	// 20240909 ZL - Update new recommendation to the Guardian Inflation Assumption
	if (gsia_reins_defn_aig == CEDANT)
	{
		if (gen2_defn == YES)
			treasury_rate = fia_rates->get_int_rate(t, "Govt", GET_YIELD_RATE, 1, 0, EFFECTIVE_ANNUAL, NO_SHIFT, 0);
		else
			treasury_rate = rates->get_int_rate(t, "Govt", GET_YIELD_RATE, 1, 0, EFFECTIVE_ANNUAL, NO_SHIFT, 0);

		double prev_infl_rate_mthly = infl_cumul(t - 1) / infl_cumul(t - 2) - 1;

		double prev_infl_rate = pow(1. + prev_infl_rate_mthly, 12.) - 1.;

		infl_rate = gwl_infl_mult1_aig * treasury_rate + gwl_infl_mult2_aig * prev_infl_rate + gwl_infl_addn_aig;
	}
}
// 20220512 JYL END
else
{
	throw FatalError("Unhandled infl_rate_defn_aig requested in infl_cumul!");
}
// 20181022 MTC END

return infl_cumul(t - 1)
       * pow((1.0 + infl_rate), (1.0 / 12.0));

}


