//@@ START - isl_2019_pv_gmwb_benefit_aig
// PV of GLB using Current Swap Rate:                                                                                             
// Column:ISL_2019_PV_GMWB_BENEFIT_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_isl_2019_pv_gmwb_benefit_aig(int t) {
//^^^



//^^^

#line 1 "isl_2019_pv_gmwb_benefit_aig.FIA_LIAB.for"
// 20200428 DTL
if (/*decrements_defn == NO ||*/ t <= commencement_period || t > final_period/*maturity_period*/ /*|| fund_val_b_bef(t) < SMALL_DOUBLE*/||lapse_dyn_isl_method_aig == "NA")//20220822 JYL: added condition to turn off column when lapse_dyn_isl_method_aig is NA
{
	return NO_AVG;
}

if (decrements_defn == NO || fund_val_b_bef(t) < SMALL_DOUBLE)
	return NO_AVG;

double glb_apv_cv;
double gmwb_inf_e_bef_cv = gmwb_inf_bef(t);

if (gmwb_inf_e_bef_cv < SMALL_DOUBLE)
{
	glb_apv_cv = 0.0;
}
else
{
	StrEnum::EnumValue discount_rate_methodology;

	double fund_val_e_bef_cv = fund_val_e_bef(t);
	double policy_year = pol_yr(t);

	StrEnum::EnumValue enhanced_income_benefit 
			= enhanced_income_benefit_exercise_get_enum_aig(xint(enhanced_income_benefit_exercise_flag_aig(t))); // 20200701 DTL

	// DTL 20200707: (START)
	const int MTHS_PER_YR	= 12;
	int first_wdl_mth		= min(max(t, gmwb_req_yrs_wait * MTHS_PER_YR + 1), (xint(gmwb_exercise_yrs_aig(t)) + gmwb_req_yrs_wait) * MTHS_PER_YR + 1);
	int gmwb_withdrl_year	= xint(pol_yr(first_wdl_mth));

	double mawp_rate;
	if (t <= first_wdl_mth)  // From issue until 1st withdrawal month
	{
		mawp_rate	= calc_mawp_pct_aig(t, first_wdl_mth, gender_mp, enhanced_income_benefit, NO_INCOME, true);  
	}
	else if (policy_year == gmwb_withdrl_year)  // From 1st withdrawal month to the end of 1st withdrawal year
	{
		mawp_rate	= calc_mawp_pct_aig(t, first_wdl_mth, gender_mp, enhanced_income_benefit, NO_INCOME, false);  
	}
	else  // Subsequent time periods
	{
		mawp_rate	= calc_mawp_pct_aig(t, first_wdl_mth, gender_mp, enhanced_income_benefit, GMWB_INCOME, false);  
	}
	// DTL 20200707: (END)

	double glb_base_e_bef_cv = gmwb_inf_bef(t);
	double mawa_cv = glb_base_e_bef_cv * mawp_rate;

	if (mawa_cv < SMALL_DOUBLE)
	{
		glb_apv_cv = 0.0;
	}
	else
	{
		discount_rate_methodology = USE_TEN_YEAR_SWAP_RATE;
		glb_apv_cv = pv_gmwb_benefit_itm_calc_aig(t, glb_base_e_bef_cv, discount_rate_methodology);  // 20200701 DTL
	}
}

return glb_apv_cv;

}


