//@@ START - lapse_dyn_add_myga_aig
// Excess Lapse Rate for renewable myga                                                                                             
// Column:LAPSE_DYN_ADD_MYGA_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_lapse_dyn_add_myga_aig(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(353,"lapse_dyn_add_myga_aig",t);
}



//^^^

#line 1 "lapse_dyn_add_myga_aig.FIA_LIAB.for"
//20240506 new column, excess lapse for renewable myga
if (t <= commencement_period || t > final_period || fixed_annuity_ind_aig == NO)
	return NO_AVG;

if (decrements_defn == NO)
	return NO_AVG;

if (myga_renewable_ind == NO || myga_current_term_aig(t) == 1)
{
	return 0.;
}

double crediting_rate = lapse_dyn_base_prod_crediting_rt_aig(t);
double new_money_rate = nmr_7yr_govt_plus_sprd_aig(t);
double mva_final_factor = mva_rate_full_surr_cash_val_bef_aig(t);
double m = lapse_dyn_base_prod_mult_floor_aig;
double e = lapse_dyn_exp_param_aig;
double mva_dyn_lapse_mult = lapse_dyn_mva_mult_aig;
double lapse_addition = 0.0;

double remaining_term = max((mva_current_term_aig(t) * 12 - myga_term_mth_elapsed_eom_aig(t)) / 12, 0.0);
	
if (crediting_rate - new_money_rate > SMALL_DOUBLE)
{
	lapse_addition = m * pow(new_money_rate - crediting_rate, e) - mva_dyn_lapse_mult * mva_final_factor;
}
else if (crediting_rate - new_money_rate < SMALL_DOUBLE)
{
	lapse_addition = max(0.0, max(remaining_term, m) * pow(new_money_rate - crediting_rate, e) - mva_dyn_lapse_mult * mva_final_factor);									
}

// Check against threshold
if (fabs(new_money_rate - crediting_rate) <= lapse_dyn_base_prod_threshold_aig)
{
	lapse_addition = 0.0;
}

return lapse_addition;



}


