//@@ START - lapse_dyn_base_prod_aig
// Base Product Dynamic Lapse Addition                                                                                             
// Column:LAPSE_DYN_BASE_PROD_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_lapse_dyn_base_prod_aig(int t) {
//^^^



//^^^

#line 1 "lapse_dyn_base_prod_aig.FIA_LIAB.for"
if (
	( decrements_defn == NO || t <= commencement_period || t > final_period/*maturity_period*/ || lapse_dyn_base_prod_defn_aig == NO || gmwb_flag) )
{
	return NO_AVG;
}

// Initialize
double excess_lapse_addition;

// 20190301 MTC - Add switch to disable base product dynamic lapse during CDSC period
if (
	( lapse_dyn_surr_chg_period_defn_aig == NO && pol_yr(t) >= lapse_shock_year_aig ) || //20240828 MQ shock yr chg
	( lapse_dyn_surr_chg_period_defn_aig == YES )
   )
{
	// 20240911 ZL: Updated FIA lapse recommendation for competitor rate
	double competitor_rate = nmr_7yr_govt_plus_sprd_aig(t);

	double crediting_rate = lapse_dyn_base_prod_crediting_rt_aig(t); // Use declared option cost as a proxy for crediting rate, since we can't look into the future
																	 // 20190301 MTC - Replaced with annualized amount
	double mva_final_factor = mva_rate_full_surr_cash_val_bef_aig(t);

	if (comp_lookup_aig_gen2(t) == 0 /*UNCOMPETITIVE*/)//WTW - Gen2 - performance; made lookup into column
	{
		// Calculate RT (Remaining Term)
		const double MONTHS_IN_YEAR = 12.0;
		double remaining_term = max(
									(surr_chg_period_aig * MONTHS_IN_YEAR - t) / MONTHS_IN_YEAR,
									0.0
								   );

		pol_yr_lookup_gen2 = pol_yr(t);//WTW - Gen2 - surr_chg_pct cannot use time based lookup in an external formula - need to update all instances to use this working variable
		double surr_chg_pct_local = surr_chg_pct;
		
		excess_lapse_addition = max(
									max(remaining_term, lapse_dyn_base_prod_mult_floor_aig) * (competitor_rate - crediting_rate) - surr_chg_pct_local/*surr_chg_pct*/ - mva_final_factor, 
									0.0
								   );
	}
	else if (comp_lookup_aig_gen2(t) == 1 /*COMPETITIVE*/)//WTW - Gen2 - performance; made lookup into column
	{
		excess_lapse_addition = lapse_dyn_base_prod_mult_floor_aig * (competitor_rate - crediting_rate) - mva_final_factor;
	}
	else
	{
		throw FatalError("Unhandled comp_lookup_aig requested in fia_liab->lapse_dyn_base_prod_aig!");
	}

	// Check against threshold
	if (fabs(competitor_rate - crediting_rate) <= lapse_dyn_base_prod_threshold_aig)
	{
		excess_lapse_addition = 0.0;
	}
}
else
{
	excess_lapse_addition = 0.0;
}
// 20190301 MTC END

return excess_lapse_addition;

}


