//@@ START - lapse_dyn_base_prod_crediting_rt_aig
// Base Product Dynamic Lapse crediting rate                                                                                             
// Column:LAPSE_DYN_BASE_PROD_CREDITING_RT_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_lapse_dyn_base_prod_crediting_rt_aig(int t) {
//^^^



//^^^

#line 1 "lapse_dyn_base_prod_crediting_rt_aig.FIA_LIAB.for"
/*
	Weighted sum refactor.  MCHING 9-3-2021
*/

if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return NO_AVG;	
}

//return weighted_sum_over_funds_e_bef_aig("lapse_dyn_base_prod_crediting_rt_aig", t);
//WTW - Gen2 - Column Interface
double total = 0.0;

for (size_t i = 0; i < sm_fia_account.size(); i++)
{
	if (fund_val_e_bef(t) > SMALL_DOUBLE)
	{
		// Weigh by current allocation
		total += sm_fia_account[i]->lapse_dyn_base_prod_crediting_rt_aig(t) * (sm_fia_account[i]->fund_val_e_bef(t) / fund_val_e_bef(t));
	}
	else
	{
		// Weigh by initial allocation
		total += sm_fia_account[i]->lapse_dyn_base_prod_crediting_rt_aig(t) * (sm_fia_account[i]->fund_val_split_prop);
	}
}
		
return total;

}


