//@@ START - lapse_dyn_fa_mult_aig
// Lapse Dyn FA Multiplier                                                                                             
// Column:LAPSE_DYN_FA_MULT_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_lapse_dyn_fa_mult_aig(int t) {
//^^^



//^^^

#line 1 "lapse_dyn_fa_mult_aig.FIA_LIAB.for"
// 20240821 ZL: new column to calculate the FA dynamic lapse multiplier
if (t <= commencement_period || t > final_period
	|| fixed_annuity_ind_aig == NO )
	return NO_AVG;

double dyn_lapse_multiple = 1.0;
double av_size_multiple = 1.0;
double sprd_multiple = 1.0;

if (policies_b(t) < SMALL_DOUBLE)
{
	return 0.0;
}

//The logic only applies to non-MYGA and 1-year renewable MYGA 
if((myga_renewable_ind == NO) ||
	(myga_renewable_ind == YES && myga_current_term_aig(t) == 1))
{
	pol_yr_lookup_gen2 = pol_yr(t);
	double surr_chg	= surr_chg_pct;
	double sc_or_mva_period = lapse_shock_year_aig - 1.; 
	double remaining_term = max((sc_or_mva_period * 12 - t) / 12, 0.0);

	//set up lookup parameters
	xstring pos_sprd_ind;
	double dyn_sprd, alpha, beta;

	if (shock_phase_lookup_aig_gen2(t) == 0 && lapse_dyn_addl_preshock_sprd_crbg == YES) // PRE_SHOCK;
	{
		dyn_sprd = lapse_dyn_base_prod_crediting_rt_aig(t) - nmr_7yr_govt_plus_sprd_aig(t)
						+ (surr_chg + mva_rate_full_surr_cash_val_bef_aig(t)) 
						/ max(1, remaining_term);
	}
	else //SHOCK and POST_SHOCK
	{
		dyn_sprd = lapse_dyn_base_prod_crediting_rt_aig(t) - nmr_7yr_govt_plus_sprd_aig(t);
	}

	if (dyn_sprd < SMALL_DOUBLE)
	{
		pos_sprd_ind = "No";
	}
	else
	{
		pos_sprd_ind = "Yes";
	}

	pos_sprd_ind_dyn_lapse_aig = pos_sprd_ind;
	alpha = fa_dyn_lapse_mult_alpha_aig;

	pos_sprd_ind_dyn_lapse_aig = pos_sprd_ind;
	beta = fa_dyn_lapse_mult_beta_aig;

	dyn_lapse_multiple = 1 - alpha * atan( beta * dyn_sprd);

	dyn_lapse_multiple = max(lapse_dyn_mult_floor_aig, dyn_lapse_multiple);

	//20250826 ZL: FA Dynamic Lapse Formula is updated to reflect a Size and Spread multiplier for 2025 unlocking
	if (lapse_dyn_shock_yr_defn_crbg == YES && shock_lapse_yr_ind_crbg(t) == 1)
	{
		av_size_crbg = fund_val_e_bef(t) / policies_b(t);
		av_size_multiple = fa_dyn_lapse_av_size_mult_crbg;

		dyn_sprd_crbg = dyn_sprd;
		sprd_multiple = fa_dyn_lapse_dyn_sprd_mult_crbg;
	}
}

return dyn_lapse_multiple * av_size_multiple * sprd_multiple;

}


