//@@ START - lapse_rate
// Lapse Rate                                                                                             
// Column:LAPSE_RATE
//========================================================
double FIA_LIAB_UDF::fia_liab_lapse_rate(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(367,"lapse_rate",t);
}



//^^^

#line 1 "lapse_rate.FIA_LIAB.for"
if (/*decrements_defn == NO ||*/ t <= commencement_period || t > final_period/*maturity_period*/)//WTW - Gen2 - move non-time guard below
	return NO_AVG;

if (decrements_defn == NO)
	return NO_AVG;


if (fund_val_b_bef(t) > SMALL_DOUBLE)
{
	double annual_lapse_rate = lapse_rate_base(t); 
	
	if(fixed_annuity_ind_aig == YES && pol_yr(t) > myga_init_term && myga_current_term_aig(t) > 1) //base lapse skew for renewable myga
	{
		if(myga_term_mth_elapsed_eom_aig(t) == 1) //free look period
		{
			annual_lapse_rate *= lapse_skew_fct1_aig;
		}
		else if(myga_term_mth_elapsed_eom_aig(t) <= 12)
		{
			annual_lapse_rate *= lapse_skew_fct2_aig;
		}
	}

	if (lapse_is_dynamic == YES)
	{
		annual_lapse_rate *= lapse_dyn_mult_aig(t);		//arctan for GLB, arctan for base product

		annual_lapse_rate += lapse_dyn_addn_aig(t);		//ISL2019 for GLB; rate driven lapse for renewable myga
	}

	double annual_lapse_rate_cap = lapse_rate_max;
	double annual_lapse_rate_floor = lapse_rate_min;

	if (fixed_annuity_ind_aig == NO && lapse_dyn_base_prod_defn_aig == YES && !gmwb_flag)  // <-- Non-GLB base product dynamic lapse adjustment
	{
		// Set base product lapse cap/floor
		annual_lapse_rate_cap = lapse_rate_base_prod_max_aig;
		annual_lapse_rate_floor = lapse_rate_base_prod_min_aig;
	}

	// 20250611 Unlocking 2025 shock lapse Caps/Floors
	if (!gmwb_flag && shock_lapse_yr_ind_crbg(t) == 1) 
	{
		annual_lapse_rate_cap = lapse_rate_shock_yr_max;
		annual_lapse_rate_floor = lapse_rate_shock_yr_min;
	}

	// Apply lapse cap and floor
	annual_lapse_rate = max(min(annual_lapse_rate, annual_lapse_rate_cap), annual_lapse_rate_floor);

	return annual_lapse_rate;
}
else
{
	return 0.0;
}




}


