//@@ START - lapse_skew_cumul_fct_fa_aig
// Cumul lapse skew factor                                                                                             
// Column:LAPSE_SKEW_CUMUL_FCT_FA_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_lapse_skew_cumul_fct_fa_aig(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(373,"lapse_skew_cumul_fct_fa_aig",t);
}



//^^^

#line 1 "lapse_skew_cumul_fct_fa_aig.FIA_LIAB.for"
//20240506 new column for FA lapse
if (t <= commencement_period || t > final_period || lapse_skew_method_crbg != FA_PROPHET)
	return NO_AVG;

if (decrements_defn == NO)
	return NO_AVG;

double cumul_factor_total = 0.;

if (shock_lapse_yr_ind_crbg(t) == 1)
{
	double skew_factor;

	double base_lapse = lapse_rate_base_fa_aig(t);

	for (int i = 1; i <= 12; i++)
	{	
		if (i <= shock_skew_mth_aig)
		{
			skew_factor = 1 / shock_skew_mth_aig * log(1 - shock_skew_pct_aig * base_lapse) / log(1 - base_lapse);
		}
		else
		{
			skew_factor = (1 / (12 - shock_skew_mth_aig)) * log( (1 - base_lapse) / (1 - shock_skew_pct_aig * base_lapse))
						/ log(1 - base_lapse);
		}

		cumul_factor_total += skew_factor;
	}
}
else
{
	cumul_factor_total = 1.0;
}

return cumul_factor_total;

}


