//@@ START - maint_exp_eom
// Maintenance Expenses End of Month                                                                                             
// Column:MAINT_EXP_EOM
//========================================================
double FIA_LIAB_UDF::fia_liab_maint_exp_eom(int t) {
//^^^



//^^^

#line 1 "maint_exp_eom.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return NO_AVG;
}

StrEnum::EnumValue covered_person_status_enum_tmp	= covered_person_status_aig;
double covered_person_status_code					= covered_person_status_col_e_bef_aig(t);
covered_person_status_aig							= //lookup key for `maint_exp_pct_fund_aig`!
	covered_person_status_get_enum_value_aig(covered_person_status_code);

double adj_mult = exp_adj_mult;
			
double maint_exp_per_pol
= (this->maint_exp_per_pol / 12.0) 
  * infl_cumul(t)
  * policies_b(t)
  * adj_mult;

if( fund_val_fixed(t) < model_point_amount_threshold)
maint_exp_per_pol
= (this->maint_exp_per_pol_payout / 12.0) 
  * infl_cumul(t)
  * policies_b(t)
  * adj_mult;

  temp_key_cov_person_status = covered_person_status_aig; //WTW - Gen2 - Mutating Lookup Term
  double _maint_exp_pct_fund_aig = this->maint_exp_pct_fund_aig;
  if (gmwb_flex_defn_aig == YES && abs(_maint_exp_pct_fund_aig) > SMALL_DOUBLE)
  {
	_maint_exp_pct_fund_aig = 0.0;
	
	if (gen2_defn == NO)
		makeRunLogYellow();	  //WTW - Gen2 - makeRunLogYellow() not supported

	if ( t == 1 )
	{
		xstring warning_msg = "fia_liab->maint_exp_eom(t): zeroing out `maint_exp_pct_fund_aig` input because flex is on!";
		log_screen << warning_msg << endl;
	}
  }

temp_key_cred_type_dyn_aig = crediting_type_dyn_aig; //WTW - Gen2  - Mutating Lookup Term
double maint_exp_pct_fund_local = this->maint_exp_pct_fund; //WTW - Gen2  - Mutating Lookup Term used in expression
double maint_exp_pct_fund_2_local_aig = this->maint_exp_pct_fund_2_aig; //20220301 AA

if (!isMainModel && alm_flag) //20231108 ZL: Zero out maint_exp_pct_fund_2_aig when performing STAT run
{
	maint_exp_pct_fund_2_local_aig = 0;
}

// AA 20220523 - Added guardian adjustments to expenses & reformatted code 
double strat_return_adj = (1.0 + weighted_strategy_return_aig(t - 1)) 
						/ (1.0 + weighted_ending_strategy_return_aig(t - 1)); 

double maint_exp_pct_fund = (maint_exp_pct_fund_local
							+ _maint_exp_pct_fund_aig // 20190228 HYH - changed to include IncomeFlex expense 
							+ maint_exp_pct_fund_2_local_aig // MCHING 12-11-2021 - Added another maintenance expense for Guardian. 
							+ this->maint_exp_pct_strategy_value_aig * strat_return_adj
							+ maint_exp_allow_level_aig) // // ZL 20251013 : Added for Maintenance Expenses Allowance AIG
							* adj_mult / 12.0;

if (maint_exp_fund_value_type == BOM_BEF)
{
	maint_exp_pct_fund *= fund_val_b_bef(t);
}
else
{
	maint_exp_pct_fund *= fund_val_b(t);
}

double maint_exp_eom_cv = maint_exp_per_pol + maint_exp_pct_fund;

if (gsia_reins_defn_aig == CEDANT)
{
	maint_exp_pct_fund /= (1 - quota_share_reinsured_aig); // 20220523 AA - adjust fund_val to show cedant's POV
	
	maint_exp_eom_cv = maint_exp_per_pol 
					+ maint_exp_pct_fund
					- gwl_maint_exp_allow_aig(t)
					- gwl_ceding_exp_allow_aig(t);

}
else if (gsia_reins_defn_aig == REINSURER)
{
	maint_exp_eom_cv += gwl_maint_exp_allow_aig(t) + gwl_ceding_exp_allow_aig(t);
}
// AA 20220523 END

covered_person_status_aig = covered_person_status_enum_tmp;

return maint_exp_eom_cv;

}


