//@@ START - maturity_benefits
// Maturity Benefits                                                                                             
// Column:MATURITY_BENEFITS
//========================================================
double FIA_LIAB_UDF::fia_liab_maturity_benefits(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(383,"maturity_benefits",t);
}



//^^^

#line 1 "maturity_benefits.FIA_LIAB.for"
/*if (t != maturity_period)*/ // 20180807 MTC - Force maturity benefits at end of projection
if (t != maturity_benefits_period_aig)
	return NO_AVG;

// 20180930 MTC - Check maturity benefit against claim tail amount; pay out the greater of the two
// 20190411 MTC - Added new logic to include MWV and MVA in maturity
double maturity_benefit;

double funds_cv = fund_val_e_bef_maturity_aig(t);

// Added partial interest crediting logic to annuitization benefits.  MWV was already here.  MCHING 12-11-2021
if (ann_benefits_partial_interest_credited_defn_aig == YES)
{
	funds_cv *= (1.0 + crediting_rate_partial_e_bef_aig(t));
}
// END MCHING 12-11-2021

if (fia->fund_val_defn_aig == EIV)
{
	double fund_val_e_bef_maturity_cv       = fund_val_e_bef_maturity_aig(t);
	double min_accum_val_e_bef_maturity_cv  = min_accum_val_e_bef_maturity_aig(t);
	funds_cv = max(fund_val_e_bef_maturity_cv, min_accum_val_e_bef_maturity_cv);
}

//20250505 Apply surr chg due to MYGA
double surr_chg = surr_chg_inf_fund_val_calc_aig(funds_cv,															
												prem_bonus_recapture_e_aig(t),
												pfwd_entitlement_remaining_e(t),
												0.0,  // No GMWB chg
                                                t);

maturity_benefit = max(funds_cv - surr_chg, min_wdl_val_final_e_bef_maturity_aig(t) );

//20210630 STW: always return maturity benefit
return maturity_benefit;
// 20180930 MTC END

}


