//========================================================
double FIA_LIAB_UDF::fia_liab_min_wdl_val_e_bef_maturity_aig(int t) {
//^^^



//^^^

#line 1 "min_wdl_val_e_bef_maturity_aig.FIA_LIAB.for"
// 20190411 MTC - Added MWV for maturity
if (t != maturity_benefits_period_aig)
{
	return NO_AVG;
}

// 20180815 MTC - Added switch to zero out MWV during claim phase
double final_mwv;  // DTL 20181105 : adding alternate MWV
if (fund_val_e_bef_maturity_aig(t) > SMALL_DOUBLE)
{
	// Calculate net withdrawal amount. In RAFM, net withdrawals == gross withdrawals because no excess withdrawals are assumed (so no MVA or surrender charges).
	// If excess withdrawals are taken, this needs to change.
	double net_withdrawal_amount = withdrl_benefits(t); // 20181023 MTC - Changed from pfwd_surr_fund_val to withdrl_benefits
	double mva					 = mva_amt_partial_wdl_aig(t);

	// Calculate the MWV by taking out the withdrawal from the before claim amount.  Assess the claim event by applying survivorship now.
	double minimum_withdrawal_value = max(min_wdl_val_e_bef_aig(t) * surv_period(t) - net_withdrawal_amount - mva, 0.0); // 20181023 MTC - Floor MWV at 0

	final_mwv = minimum_withdrawal_value;
}
else
{
	final_mwv = 0.0;
}

return final_mwv;

}


