//@@ START - mva_amt_full_surr_cash_val_aig
// MVA amount for full surrenders at the end of the month, current basis                                                                                             
// Column:MVA_AMT_FULL_SURR_CASH_VAL_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_mva_amt_full_surr_cash_val_aig(int t) {
//^^^



//^^^

#line 1 "mva_amt_full_surr_cash_val_aig.FIA_LIAB.for"
// 20180627 MTC - MVA
// 20181106 MTC - Refactor MVA and split final factor calculation from amount calculation
if (t < commencement_period || t > final_period/*maturity_period*/ || mva_defn_aig == NO) // 20181220 MTC - Added switch to turn off MVA
{
	return NO_AVG;
}

// Initialize
double mva_amt_full_surrender = 0.;
double contract_value = fund_val_fixed(t); 

// Do not calculate MVA if you are out of the surrender charge period or have no more AV
if (contract_value > SMALL_DOUBLE && mva_current_term_aig(t) > SMALL_DOUBLE) //20240509 MQ myga renewal
{
	// Initialize
	double premium_enhancement_recapture = prem_bonus_recapture_e_aig(t); // DTL 20181105 : adding premium bonus recapture
	double mva_base, free_withdrawal_amount;

	// 20181023 MTC - Apply MVA to Max Gross Withdrawal and Remaining Preferred Withdrawal
	if (surr_chg_defn == FUND_VALUE || surr_chg_defn == PREMIUM)
	{
		free_withdrawal_amount = pfwd_entitlement_remaining_e(t); // This should really be max(MAWA, 10% AV), but we're just doing 10% AV to match MoSes for now.
		mva_base = contract_value;
	}
	else
	{
		throw FatalError("Unhandled surr_chg_defn requested in fia_liab/mva_amt_full_surr_cash_val_aig!");
	}
	// 20181023 MTC END

	double mva_final_factor = mva_rate_full_surr_cash_val_aig(t);

	mva_amt_full_surrender = calc_mva_amt_full_surr_aig(mva_final_factor,
														mva_base,
														free_withdrawal_amount,
														premium_enhancement_recapture);
}

return mva_amt_full_surrender;

}


