//@@ START - mva_amt_partial_wdl_aig
// MVA for partial withdrawals:                                                                                             
// Column:MVA_AMT_PARTIAL_WDL_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_mva_amt_partial_wdl_aig(int t) {
//^^^



//^^^

#line 1 "mva_amt_partial_wdl_aig.FIA_LIAB.for"
if (t < commencement_period || t > final_period/*maturity_period*/ || mva_defn_aig == NO)
{
	return NO_AVG;
}

StrEnum::EnumValue income_phase_lookup_original = income_phase_lookup_aig;
set_income_phase_lookup_e_bef_aig(t); 

double mva_amt_partial_wdl = 0.0;
double contract_value = fund_val_e_bef(t);

if (contract_value > SMALL_DOUBLE && mva_current_term_aig(t) > SMALL_DOUBLE) //20240509 MQ myga renewal
{
	double premium_enhancement_recapture = prem_bonus_recapture_e_bef_aig(t);
	double mva_base = withdrl_benefits_gross_aig(t);
	double free_withdrawal_amount;

	if (surr_chg_defn == FUND_VALUE || surr_chg_defn == PREMIUM)
	{
		free_withdrawal_amount = pfwd_entitlement_remaining_e_bef(t);
	}
	else
	{
		throw FatalError("Unhandled `surr_chg_defn` requested in fia_liab->mva_amt_partial_wdl_aig!");
	}

	double mawa_benefit_remaining	= gmwb_entitlement_remaining_e_bef_aig(t);
	free_withdrawal_amount			= max(free_withdrawal_amount, mawa_benefit_remaining);

	double mva_final_factor = mva_rate_full_surr_cash_val_bef_aig(t);

	mva_amt_partial_wdl = calc_mva_amt_full_surr_aig(mva_final_factor,
													 mva_base,
													 free_withdrawal_amount,
													 premium_enhancement_recapture);
}

income_phase_lookup_aig = income_phase_lookup_original;

return mva_amt_partial_wdl;

}


