double FIA_LIAB_UDF::fia_liab_mva_rate_full_surr_cash_val_bef_maturity_aig(int t) {
//^^^



//^^^

#line 1 "mva_rate_full_surr_cash_val_bef_maturity_aig.FIA_LIAB.for"
// 20180627 MTC - MVA
// 20181105 MTC - Refactor MVA and split final factor calculation from amount calculation
// 20190411 MTC - Added MVA for maturity
if (t != maturity_benefits_period_aig || mva_defn_aig == NO) // 20181220 MTC - Added switch to turn off MVA
{
	return NO_AVG;
}

// Initialize
double contract_value = fund_val_e_bef_maturity_aig(t); 
double mva_final_factor = 0.0;

// Do not calculate MVA if you are out of the surrender charge period or have no more AV
if (contract_value > SMALL_DOUBLE && mva_current_term_aig(t) > SMALL_DOUBLE) //20240509 MQ myga renewal
{
	int N = mva_period_aig * 12 - t; // DTL 20200401 
	int mva_init_mth = commencement_period;

	//20240509 MQ MYGA renewal
	if(myga_renewable_ind == YES)
	{
		N = mva_current_term_aig(t) * 12 - myga_term_mth_elapsed_eom_aig(t); 
		mva_init_mth = t - myga_term_mth_elapsed_eom_aig(t);
	}

	double I = 0.0;
	double J = 0.0;

	if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
	{
		I = fia_rates->get_index_rate(mva_init_mth,
								"MVA",
								GET_GROWTH_RATE,
								EFFECTIVE_ANNUAL); // MoSes sets issue MVA to t=1. This is wrong because MVA represents the end of month value.
		J = fia_rates->get_index_rate(t,
								"MVA",
								GET_GROWTH_RATE,
								EFFECTIVE_ANNUAL);
	}
	else
	{
		I = rates->get_index_rate(mva_init_mth,
								"MVA",
								GET_GROWTH_RATE,
								EFFECTIVE_ANNUAL); // MoSes sets issue MVA to t=1. This is wrong because MVA represents the end of month value.
		J = rates->get_index_rate(t,
								"MVA",
								GET_GROWTH_RATE,
								EFFECTIVE_ANNUAL);
	}
	double minimum_withdrawal_value = min_wdl_val_e_bef_maturity_aig(t); // This varies on min_wdl_val_e_aig and min_wdl_val_e_bef_aig.
															// 20181220 MTC - Changed MWV to non-alternative MWV
	double withdrawal_charge = surr_chg_inf_bef_maturity_aig(t); // This varies on surr_chg_inf and surr_chg_inf_bef.
	double premium_enhancement_recapture = prem_bonus_recapture_e_aig(t); // DTL 20181105 : adding premium bonus recapture
	double remaining_pfwd = pfwd_entitlement_remaining_e(t);
	double mva_base;

	// 20181023 MTC - Apply MVA to Max Gross Withdrawal and Remaining Preferred Withdrawal
	// 20181205 MTC - Differentiated MVA calc by surr_chg_defn
	if (surr_chg_defn == FUND_VALUE || surr_chg_defn == PREMIUM)
	{
		mva_final_factor = calc_mva_rate_full_surr_default_aig(I,
															   J,
															   N,
															   contract_value,
															   minimum_withdrawal_value,
															   withdrawal_charge,
															   remaining_pfwd,
															   premium_enhancement_recapture);
	}
	else
	{
		throw FatalError("Unhandled surr_chg_defn requested in fia_liab/mva_rate_full_surr_cash_val_bef_maturity_aig!");
	}
	// 20181023 MTC END
	// 20181205 MTC END
}

return mva_final_factor;

}


