//@@ START - myga_current_term_aig
// current term length for myga                                                                                             
// Column:MYGA_CURRENT_TERM_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_myga_current_term_aig(int t) {
//^^^



//^^^

#line 1 "myga_current_term_aig.FIA_LIAB.for"
// MQIN 20240503: New column for Fixed annuity, keeping track of myga term
if (t <= commencement_period || t > final_period || fixed_annuity_ind_aig == NO)
{
	return NO_AVG;	
}

if (pol_yr(t) <= myga_init_term)
{
	return myga_init_term;
}

if (mod(myga_term_mth_elapsed_eom_aig(t - 1), myga_current_term_aig(t - 1) * 12 ) != 0)
{
	return myga_current_term_aig(t - 1);
}

if (myga_renewable_ind == NO || attained_age(t) + myga_renew_term > maturity_age)
{
	return 1;
}
else
{
	return myga_renew_term;
}




}


//@@ END

//@@ START - myga_term_mth_elapsed_eom_aig
// mths elapsed since beginning of the current myga term                                                                                             
// Column:MYGA_TERM_MTH_ELAPSED_EOM_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_myga_term_mth_elapsed_eom_aig(int t) {
//^^^



//^^^

#line 1 "myga_term_mth_elapsed_eom_aig.FIA_LIAB.for"
// MQIN 20240503: New column for Fixed annuity
if (t <= commencement_period || t > final_period || fixed_annuity_ind_aig == NO)
{
	return NO_AVG;
}
else
{
	if ( t == commencement_period + 1 ) 
	{
		return 1;
	}
	else
	{
		if ( mod(myga_term_mth_elapsed_eom_aig(t - 1), myga_current_term_aig(t - 1) * 12 ) == 0 )
		{
			return 1;
		}
		else
		{
			return myga_term_mth_elapsed_eom_aig(t - 1) + 1;
		}
	}
}



}


