//@@ START - new_money_rate_aig
// New Money Rate, End of Month                                                                                             
// Column:NEW_MONEY_RATE_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_new_money_rate_aig(int t) {
//^^^



//^^^

#line 1 "new_money_rate_aig.FIA_LIAB.for"
// 20181106 MTC - Added New Money Rate as a column
// 20190313 MTC - Refactored to use MRM GA Yield
if (t < commencement_period || t > final_period/*maturity_period*/)
	return NO_AVG;

double init_earn_rate = 0.0;

// Calculate Matrix Spread
if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
	init_earn_rate = fia_rates->get_misc_rate(commencement_period, crediting_nb_rate_id_aig, EFFECTIVE_ANNUAL);
else
	init_earn_rate = rates->get_misc_rate(commencement_period, crediting_nb_rate_id_aig, EFFECTIVE_ANNUAL);

double matrix_spread = crediting_ner_aig - init_earn_rate;

// Calculate Earned Rate
double earn_rate = 0.0;

// Calculate Matrix Spread
if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
	earn_rate = fia_rates->get_misc_rate(t, crediting_nb_rate_id_aig, EFFECTIVE_ANNUAL);
else
	earn_rate = rates->get_misc_rate(t, crediting_nb_rate_id_aig, EFFECTIVE_ANNUAL);

// Calculate New Money Rate
double new_money_rate = earn_rate + matrix_spread;

return new_money_rate;

}


