//@@ START - opt_budget
// Available Option Budget                                                                                             
// Column:OPT_BUDGET
//========================================================
double FIA_LIAB_UDF::fia_liab_opt_budget(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(439,"opt_budget",t);
}



//^^^

#line 1 "opt_budget.FIA_LIAB.for"
/*
	Weighted sum refactor.  MCHING 9-3-2021
*/

if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return NO_AVG;	
}

//return weighted_sum_over_funds_b_bef_aig("opt_budget_strategy_term_renewal_aig", t);
//WTW - Gen2 - Column Interface
double total = 0.0;

for (size_t i = 0; i < sm_fia_account.size(); i++)
{
	if (fund_val_b_bef(t) > SMALL_DOUBLE)
	{
		// Weigh by current allocation
		total += sm_fia_account[i]->opt_budget_strategy_term_renewal_aig(t) * (sm_fia_account[i]->fund_val_b_bef(t) / fund_val_b_bef(t));
	}
	else
	{
		// Weigh by initial allocation
		total += sm_fia_account[i]->opt_budget_strategy_term_renewal_aig(t) * (sm_fia_account[i]->fund_val_split_prop);
	}
}
		
return total;

}


