//@@ START - pfwd_entitlement
// Penalty Free Withdrawal Entitlement                                                                                             
// Column:PFWD_ENTITLEMENT
//========================================================
double FIA_LIAB_UDF::fia_liab_pfwd_entitlement(int t) {
//^^^



//^^^

#line 1 "pfwd_entitlement.FIA_LIAB.for"
if (t < commencement_period || t > final_period/*maturity_period*/)
	return NO_AVG;

if (t == commencement_period) 
	{
	if (elapsed_mths > 0 && (pfwd_use_aig(t) * pol_mth(t)) != 12.0) // ZHL 20230803: replacethe input pfwd_use to pfwd_use_aig(t) column to implement the Non-GMWB partial WD assumptions for 2023Q3 unlocking
		return pfwd_entitlement_remaining_e(t)
		       / (1.0 - (pfwd_use_aig(t) / 12.0 * pol_mth(t)));
	
	return 0.0;
	}

if (xint(pol_mth(t)) == 1)
	return pfwd_entitlement_remaining_e_bef(t)
	       * surv_period(t);

return pfwd_entitlement(t - 1)
       * surv_period(t);

}


//@@ END

//@@ START - pfwd_entitlement_remaining_e
// Penalty Free Withdrawal Entitlement Remaining End of Month                                                                                             
// Column:PFWD_ENTITLEMENT_REMAINING_E
//========================================================
double FIA_LIAB_UDF::fia_liab_pfwd_entitlement_remaining_e(int t) {
//^^^



//^^^

#line 1 "pfwd_entitlement_remaining_e.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return NO_AVG;
}

StrEnum::EnumValue income_phase_lookup_original = income_phase_lookup_aig;
set_income_phase_lookup_e_aig(t);

double pfwd_base, pfwd_entitlement_cv;
pol_yr_lookup_gen2 = pol_yr(t); //WTW - Gen2 - add working variable for lookups that vary by time for character input

if (pfwd_amt_avail_defn_aig == FUND_VALUE)//WTW - Gen2 - character input that varies by time
{
	double withdrls_taken_cv	= withdrl_benefits_gross_cumul_yr_e_aig(t);
	pol_yr_lookup_gen2 = pol_yr(t);//WTW - Gen2 - AtTime() not allowed - used in pfwd_pct_aig
	double pfwd_pct_local = pfwd_pct;//WTW - Gen2 - mutating lookup term used in expression
	pfwd_base					= max(0, fund_val_boy_b_aig(t) * pfwd_pct_local) * surv_period(t);//WTW - Gen2 - mutating lookup term used in expression
	pfwd_entitlement_cv			= max(0, pfwd_base - withdrls_taken_cv); 
}	
else
{
	pfwd_entitlement_cv		= max(0.0, pfwd_entitlement_remaining_e_bef(t) * surv_period(t) - withdrl_benefits_gross_aig(t));
}

double mawa_benefit_remaining	= gmwb_entitlement_remaining_e_aig(t);
pfwd_entitlement_cv				= max(pfwd_entitlement_cv, mawa_benefit_remaining);

income_phase_lookup_aig = income_phase_lookup_original;

return pfwd_entitlement_cv;




}


//@@ END

//@@ START - pfwd_entitlement_remaining_e_bef
// Penalty Free Withdrawal Entitlement Remaining Beginning of Month                                                                                             
// Column:PFWD_ENTITLEMENT_REMAINING_E_BEF
//========================================================
double FIA_LIAB_UDF::fia_liab_pfwd_entitlement_remaining_e_bef(int t) {
//^^^



//^^^

#line 1 "pfwd_entitlement_remaining_e_bef.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return NO_AVG;
}

StrEnum::EnumValue income_phase_lookup_original = income_phase_lookup_aig;
set_income_phase_lookup_e_bef_aig(t);

double pfwd_base, pfwd_entitlement_cv;
pol_yr_lookup_gen2 = pol_yr(t);//WTW - Gen2 - Mutating Lookup Term
if (pfwd_amt_avail_defn_aig == FUND_VALUE)
{
	double withdrls_taken_cv	= withdrl_benefits_gross_cumul_yr_e_bef_aig(t);
	pol_yr_lookup_gen2 = pol_yr(t);//WTW - Gen2 - AtTime() not allowed - used in pfwd_pct_aig
	double pfwd_pct_local = pfwd_pct;//WTW - Gen2 - mutating lookup term used in expression
	pfwd_base					= max(0, fund_val_boy_b_aig(t) * pfwd_pct_local);//WTW - Gen2 - mutating lookup term used in expression
	pfwd_entitlement_cv			= max(0, pfwd_base - withdrls_taken_cv); 
}	
else
{
	if (xint(pol_mth(t)) == 1)
	{
		double pfwd_base		= pfwd_base = prem_cumul_bef(t);
		pol_yr_lookup_gen2 = pol_yr(t);//WTW - Gen2 - AtTime() not allowed - used in pfwd_pct_aig
		pfwd_entitlement_cv		= max(0.0, pfwd_base * pfwd_pct);
	}
	else
	{
		pfwd_entitlement_cv		= pfwd_entitlement_remaining_e(t - 1);
	}
}

double mawa_benefit_remaining	= gmwb_entitlement_remaining_e_bef_aig(t);
pfwd_entitlement_cv				= max(pfwd_entitlement_cv, mawa_benefit_remaining);

income_phase_lookup_aig = income_phase_lookup_original;
	
return pfwd_entitlement_cv;




}


