//@@ START - pfwd_use_aig
// Penalty free withdrawal rate                                                                                             
// Column:PFWD_USE_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_pfwd_use_aig(int t) {
//^^^



//^^^

#line 1 "pfwd_use_aig.FIA_LIAB.for"
//ZHL 20230803: replacethe input pfwd_use to pfwd_use_aig(t) column to implement the Non-GMWB partial WD assumptions for 2023Q3 unlocking
if (t <= commencement_period || t > final_period/*maturity_period*/)
	return NO_AVG;

double pfwd_rate = 0.0;

//If it is gmwb and not taking preincome withdrl.
if( gmwb_flag && (preincome_exercise_yrs_aig == 999))
	return pfwd_rate;

double pfwd_use_q = pfwd_use_q_aig;
double pfwd_use_uq = pfwd_use_nq_aig;

double qualified_pct = non_gmwb_qualified_pct_aig;
double fct1 = non_gmwb_qualified_cal_fct1_aig;
double fct2 = non_gmwb_qualified_cal_fct2_aig;
double rmd_attained_age = rmd_attained_age_aig;
double addl_sc_shock_pfwd_use = addl_sc_shock_pfwd_use_aig;

pol_yr_lookup_gen2 = pol_yr(t);
double pfwd_pct_local = pfwd_pct;

//to udpate the Qualified component of the partial WD rate in case attained age is greater than or equal to RMD attained age.
if (pfwd_pct_local > SMALL_DOUBLE)
{
	if (attained_age(t) >= rmd_attained_age)
	{
	pfwd_use_q = fct1 * exp( fct2 * (attained_age(t) - rmd_attained_age + 1)) / pfwd_pct_local;
	}
	//Calculate the total partial withdrawal amount
	pfwd_rate = pfwd_use_q * qualified_pct + pfwd_use_uq * ( 1 - qualified_pct);
} 
else
{
	return pfwd_rate;
}

//apply an additional w/d rate in shock year
if(pol_yr(t) == lapse_shock_year_aig)  //20240828 MQ shock yr chg
{
	pfwd_rate += addl_sc_shock_pfwd_use; 
}

else if (myga_renewable_ind == YES && pol_yr(t) > myga_init_term && myga_current_term_aig(t) > 1)
{
	//Case 1: MVA term is the same as MYGA term, then first year after renewal is shock year
	//Case 2: MVA term is shorter than MYGA term, then first year after MVA is shock year
	//Assumes SC period is equal to MVA or 0	
	if ( (myga_renew_term == mva_period_renewal_aig && myga_term_mth_elapsed_eom_aig(t) <= 12) ||
		(myga_term_mth_elapsed_eom_aig(t) > mva_period_renewal_aig * 12 && myga_term_mth_elapsed_eom_aig(t) <= mva_period_renewal_aig * 12 + 12))
	{
		pfwd_rate += addl_sc_shock_pfwd_use;
	}
}

return pfwd_rate;

}


