//@@ START - policies_female_experience_aig
// End-Of-Month Policies In Force With Only Female Alive, Experience Mortality                                                                                             
// Column:POLICIES_FEMALE_EXPERIENCE_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_policies_female_experience_aig(int t) {
//^^^



//^^^

#line 1 "policies_female_experience_aig.FIA_LIAB.for"
/*!Female Population							
   =================							
   @author Michael Ching							
   @date 20180514							
							
   Referencing the <a href="http://library.soa.org/library/actuary/1967-79/ACT7803.pdf">Frasier Method</a>, we track the							
   population of female alive, male dead status policyholders by using the below algorithm:							
							
   \f[							
   female\,policies_{t} = joint\,policies_{t-1} * probability\,male\,dies\,and\,female\,survives_{t} + female\,policies_{t-1} * probability\,female\,survives_{t}							
   \f]							
							
   Written another way,							
							
   \f[							
   female\,policies_{t} = joint\,policies_{t-1} * (1 - female\,monthly\,death\,rate_{t}) * male\,monthly\,death\,rate_{t} + female\,policies_{t-1} * (1 - female\,monthly\,death\,rate_{t})							
   \f]									
							
   @note This is a recursive function.							
							
   @note This is only used for Joint gender policies.							
							
   Related Inputs:							
   ---------------							
   -# **MP** `gender` - This column will only produce values if `gender` is Joint.							
   .							
							
   @return Number of policies with female status (female alive, male dead) at the end of month t.							
*/							
							
// 20180504 MTC - Joint logic
// 20180915 MTC - Run Frasier for spousal continuation logic
// 20190913 MTC - Updated enum
if (t < commencement_period || t > maturity_period) //WTW - Gen2 - Timeguards
	return NO_AVG;

if (gender_mp != JOINT && spousal_continuation_defn_aig == NONE)
{
	return NO_AVG;		
}

double policies_female;
							
if (t == commencement_period)
{
	if (spousal_continuation_defn_aig == SPOUSAL_2019)
	{
		policies_female = init_policies_female_spousal_2019_calc_aig;
	}
	else
	{
		policies_female = init_policies_female_aig;
	}
} 							
else
{
	if (spousal_continuation_defn_aig == SPOUSAL_2019)
	{
		double policies_female_bom = policies_female_experience_aig(t - 1);
		double policies_joint_bom = policies_joint_experience_aig(t - 1);
		double spousal_continuation_election_rate;
		double fund_val_b_cv = fund_val_b(t);
		
		//20200521 STW START: external split adjustment
		if (gmwb_flex_defn_aig == YES && t + elapsed_mths == gmwb_exercise_yrs * 12 + 1)
		{
			if (gender_aft_act_aig == JOINT)
			{
				policies_joint_bom = policies_joint_experience_aig(t - 1) + policies_male_experience_aig(t - 1) +
										policies_female_experience_aig(t - 1);
				policies_female_bom = 0;
			}
			else if (gender_aft_act_aig == MALE)
			{
				policies_female_bom = 0;
				policies_joint_bom = 0;
			}
			else if (gender_aft_act_aig == FEMALE)
			{
				policies_female_bom = policies_joint_experience_aig(t - 1) + policies_male_experience_aig(t - 1) +
										policies_female_experience_aig(t - 1);
				policies_joint_bom = 0;
			}
			else
			{
				throw FatalError("Unsupported gender requested for gender_aft_act_aig in policies_female_experience_aig.");															
			}
		}
		//20200521 STW END

		if (fund_val_b_cv > SMALL_DOUBLE)  // DANGER ZONE
		{
			spousal_continuation_election_rate = spousal_continuation_election_rate_aig;
		}
		else
		{
			spousal_continuation_election_rate = 1.0;
		}

		policies_female = spousal_2019_proj_policies_female_aig(t, policies_joint_bom, policies_female_bom, spousal_continuation_election_rate);
	}
	else
	{
		// Initialize
		// 20190913 MTC - Use columns instead of external function
		double dth_claim_rate_mthly_male = dth_claim_rate_mthly_male_experience_aig(t);						
		double dth_claim_rate_mthly_female = dth_claim_rate_mthly_female_experience_aig(t);						
							
		policies_female = policies_joint_experience_aig(t - 1) * dth_claim_rate_mthly_male * (1.0 - dth_claim_rate_mthly_female)						
						  + policies_female_experience_aig(t - 1) * (1.0 - dth_claim_rate_mthly_female);
	}
}				

return policies_female;

}


//@@ END

//@@ START - policies_female_gmwb_aig
// End-Of-Month Policies In Force With Only Female Alive, GMWB Mortality                                                                                             
// Column:POLICIES_FEMALE_GMWB_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_policies_female_gmwb_aig(int t) {
//^^^



//^^^

#line 1 "policies_female_gmwb_aig.FIA_LIAB.for"
/*!Female Population							
   =================							
   @author Michael Ching							
   @date 20180514							
							
   Referencing the <a href="http://library.soa.org/library/actuary/1967-79/ACT7803.pdf">Frasier Method</a>, we track the							
   population of female alive, male dead status policyholders by using the below algorithm:							
							
   \f[							
   female\,policies_{t} = joint\,policies_{t-1} * probability\,male\,dies\,and\,female\,survives_{t} + female\,policies_{t-1} * probability\,female\,survives_{t}							
   \f]							
							
   Written another way,							
							
   \f[							
   female\,policies_{t} = joint\,policies_{t-1} * (1 - female\,monthly\,death\,rate_{t}) * male\,monthly\,death\,rate_{t} + female\,policies_{t-1} * (1 - female\,monthly\,death\,rate_{t})							
   \f]							
							
   Male and female death rates are calculated externally in dth_claim_rate_mthly_calc().							
							
   @note This is a recursive function.							
							
   @note This is only used for Joint gender policies.							
							
   Related Inputs:							
   ---------------							
   -# **MP** `gender` - This column will only produce values if `gender` is Joint.							
   .							
							
   @return Number of policies with female status (female alive, male dead) at the end of month t.							
*/							
							
// 20180504 MTC - Joint logic
// 20180910 MTC - Added another population tracker for GMWB mortality basis						
if (t < commencement_period || t > maturity_period) //WTW - Gen2 - Timeguards
	return NO_AVG;

if (gender_mp != JOINT)
{							
	return NO_AVG;						
}							
							
if (t == commencement_period)
{							
	return init_policies_female_aig;						
} 							
else
{							
	// Initialize						
	// 20191913 MTC - Use columns instead of external function
	double dth_claim_rate_mthly_male = dth_claim_rate_mthly_male_gmwb_aig(t);					
	double dth_claim_rate_mthly_female = dth_claim_rate_mthly_female_gmwb_aig(t);					
													
	double policies_female = policies_joint_gmwb_aig(t - 1) * dth_claim_rate_mthly_male * (1.0 - dth_claim_rate_mthly_female)						
							 + policies_female_gmwb_aig(t - 1) * (1.0 - dth_claim_rate_mthly_female);
							
	return policies_female;						
}							


}


