//@@ START - policies_male_experience_aig
// End-Of-Month Policies In Force With Only Male Alive, Experience Mortality                                                                                             
// Column:POLICIES_MALE_EXPERIENCE_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_policies_male_experience_aig(int t) {
//^^^



//^^^

#line 1 "policies_male_experience_aig.FIA_LIAB.for"
/*!Male Population					
   ===============					
   @author Michael Ching					
   @date 20180514					
					
   Referencing the <a href="http://library.soa.org/library/actuary/1967-79/ACT7803.pdf">Frasier Method</a>, we track the					
   population of male alive, female dead status policyholders by using the below algorithm:					
					
   \f[					
   male\,policies_{t} = joint\,policies_{t-1} * probability\,female\,dies\,and\,male\,survives_{t} + male\,policies_{t-1} * probability\,male\,survives_{t}					
   \f]					
					
   Written another way,					
					
   \f[					
   male\,policies_{t} = joint\,policies_{t-1} * (1 - male\,monthly\,death\,rate_{t}) * female\,monthly\,death\,rate_{t} + male\,policies_{t-1} * (1 - male\,monthly\,death\,rate_{t})					
   \f]							
					
   @note This is a recursive function.					
					
   @note This is only used for Joint gender policies.					
					
   Related Inputs:					
   ---------------					
   -# **MP** `gender` - This column will only produce values if `gender` is Joint.					
   .					
					
   @return Number of policies with male status (male alive, female dead) at the end of month t.					
*/					

// 20180504 MTC - Joint logic
// 20180915 MTC - Run Frasier for spousal continuation logic
// 20190913 MTC - Updated enum
if (t < commencement_period || t > maturity_period) //WTW - Gen2 - Timeguards
	return NO_AVG;

if (gender_mp != JOINT && spousal_continuation_defn_aig == NONE) 
{
	return NO_AVG;		
}

double policies_male;
					
if (t == commencement_period)
{
	if (spousal_continuation_defn_aig == SPOUSAL_2019)
	{
		policies_male = init_policies_male_spousal_2019_calc_aig;
	}
	else
	{
		policies_male = init_policies_male_aig;
	}
} 					
else
{
	if (spousal_continuation_defn_aig == SPOUSAL_2019)
	{
		double policies_male_bom = policies_male_experience_aig(t - 1);
		double policies_joint_bom = policies_joint_experience_aig(t - 1);
		double spousal_continuation_election_rate;
		double fund_val_b_cv = fund_val_b(t);

		//20200521 STW START: external split adjustment
		if (gmwb_flex_defn_aig == YES && t + elapsed_mths == gmwb_exercise_yrs * 12 + 1)
		{
			if (gender_aft_act_aig == JOINT)
			{
				policies_joint_bom = policies_joint_experience_aig(t - 1) + policies_male_experience_aig(t - 1) +
										policies_female_experience_aig(t - 1);
				policies_male_bom = 0;
			}
			else if (gender_aft_act_aig == MALE)
			{
				policies_male_bom = policies_joint_experience_aig(t - 1) + policies_male_experience_aig(t - 1) +
										policies_female_experience_aig(t - 1);
				policies_joint_bom = 0;
			}
			else if (gender_aft_act_aig == FEMALE)
			{
				policies_male_bom = 0;
				policies_joint_bom = 0;
			}
			else
			{
				throw FatalError("Unsupported gender requested for gender_aft_act_aig in policies_male_experience_aig.");															
			}
		}
		//20200521 STW END

		if (fund_val_b_cv > SMALL_DOUBLE)  // DANGER ZONE
		{
			spousal_continuation_election_rate = spousal_continuation_election_rate_aig;
		}
		else
		{
			spousal_continuation_election_rate = 1.0;
		}

		policies_male = spousal_2019_proj_policies_male_aig(t, policies_joint_bom, policies_male_bom, spousal_continuation_election_rate);
	}
	else
	{
		// Initialize						
		// 20190913 MTC - Use columns instead of external function
		double dth_claim_rate_mthly_male = dth_claim_rate_mthly_male_experience_aig(t);						
		double dth_claim_rate_mthly_female = dth_claim_rate_mthly_female_experience_aig(t);				
				
		policies_male = policies_joint_experience_aig(t - 1) * dth_claim_rate_mthly_female * (1.0 - dth_claim_rate_mthly_male)					
					    + policies_male_experience_aig(t - 1) * (1.0 - dth_claim_rate_mthly_male);
	}
}							

return policies_male;

}


//@@ END

