//@@ START - prem_bonus_recapture_base_reduction_fct_aig
// Premium bonus recapture base reduction factor:                                                                                             
// Column:PREM_BONUS_RECAPTURE_BASE_REDUCTION_FCT_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_prem_bonus_recapture_base_reduction_fct_aig(int t) {
//^^^



//^^^

#line 1 "prem_bonus_recapture_base_reduction_fct_aig.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return 0.0;
}

double fund_val_e_bef_cv = fund_val_e_bef(t) * surv_period(t);
if (fund_val_e_bef_cv < SMALL_DOUBLE)
{
	return 0.0;
}

double mawa_benefit_remaining		= gmwb_entitlement_remaining_e_bef_aig(t) * surv_period(t);
double pfwd_entitlement_e_bef_cv	= pfwd_entitlement_remaining_e_bef(t) * surv_period(t);
double pfwd_entitlement_cv			= max(pfwd_entitlement_e_bef_cv, mawa_benefit_remaining);
double gross_withdrl_cv				= withdrl_benefits_gross_aig(t);
double penalty_withdrl_cv			= max(0, gross_withdrl_cv - pfwd_entitlement_cv);

if (fund_val_e_bef_cv - pfwd_entitlement_cv < SMALL_DOUBLE) //ZHL 20240917: Add guardrail to prevent error
{
	return 0.0;
}

double reduction_fct				= penalty_withdrl_cv / (fund_val_e_bef_cv - pfwd_entitlement_cv); //// ZHL 20230727 : refactor the codes related to premium bonus recapture 

return reduction_fct;

}


