// Column:PREM_ISSUED
//========================================================
double FIA_LIAB_UDF::fia_liab_prem_issued(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(522,"prem_issued",t);
}



//^^^

#line 1 "prem_issued.FIA_LIAB.for"
if (elapsed_mths > 0 || t != commencement_period + 1)
	return NO_AVG;

// AA 20220523
double single_prem_cv = single_prem;

if (gsia_reins_defn_aig == REINSURER)
{
	single_prem_cv *= quota_share_reinsured_aig; 
}
else if (gsia_reins_defn_aig == CEDANT)
{
	single_prem_cv *= (1 - quota_share_reinsured_aig);
}
// AA 20220523 END

return single_prem_cv;

}


