//@@ START - proj_csv_for_interpolation_aig
// Proj Csv For Interpolation Aig                                                                                             
// Column:PROJ_CSV_FOR_INTERPOLATION_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_proj_csv_for_interpolation_aig(int t) {
//^^^



//^^^

#line 1 "proj_csv_for_interpolation_aig.FIA_LIAB.for"
// 20220407 STW: IA STAT change requested by model owner
if (t < commencement_period || t > final_period)
     return NO_AVG;

double csv_final, fund_val_cv;
int mths_to_eopy = 12 - pol_mth(t);

//20250326 MQ change.
//hedge_mkt_val_per_unit_notional represents option value until the end of the option term
//what we need here is the equivalent option value until the end of the year
double hedge_mkt_val_per_unit = fia->sm_fia_account[0]->hedge_mkt_val_per_unit_notional(t);
double option_term = fia->sm_fia_account[0]->strategy_term_mths_aig(t);
double mths_to_e_of_term = option_term - fia->sm_fia_account[0]->strategy_term_elapsed_mths_eom_aig(t);

if (secure_cap_ind_crbg == 1 && pol_yr(t) <= surr_chg_period_aig) //secure cap/gmab
{
	option_term = surr_chg_period_aig;
	mths_to_e_of_term = surr_chg_period_aig * 12 - t - elapsed_mths;
}

double crediting_rate_cv = 0.;
if (mths_to_e_of_term > SMALL_DOUBLE)
	crediting_rate_cv = pow(1. + hedge_mkt_val_per_unit, mths_to_eopy / mths_to_e_of_term) - 1.;

//20260715 MQ Progressive trigger option cost is annual
if (xint(fia->sm_fia_account[0]->prog_trigger_ind_crbg(t)) == 1) 
	crediting_rate_cv = hedge_mkt_val_per_unit;

valn_carvm_defn = fia->stat_carvm_defn;
valn_cash_settle_defn = fia->valn_rate_cash_settle_defn;
valn_int_guar_defn = fia->valn_rate_int_guar_defn;
valn_guar_dur = int_guar_dur;
valn_plan_type = fia->valn_rate_plan_type_elective_cash_val;
valn_issue_yr = issue_yr;
double valuation_rate = stat_carvm_int_rate;

pol_yr_lookup_gen2 = pol_yr(t);
double surr_chg_pct_cv = surr_chg_pct;

// Project CSV
double rf_rate;
if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
	rf_rate = fia_rates->get_misc_rate(t, "RiskFree", EFFECTIVE_ANNUAL); 
else
	rf_rate = rates->get_misc_rate(t, "RiskFree", EFFECTIVE_ANNUAL); 

crediting_rate_cv *= pow(1 + rf_rate, mths_to_eopy / 12.0);

pol_yr_lookup_gen2 = pol_yr(t);
double pfwd_pct_cv = pfwd_pct;

csv_final = (fund_val_fixed(t) - gmwb_chg_at_surr_aig(t)) * (1 + crediting_rate_cv) * (1 - surr_chg_pct_cv * (1 - pfwd_pct_cv));

// Discount to present
csv_final *= pow(1 + valuation_rate, - mths_to_eopy / 12.0);

return csv_final;

}


