//@@ START - seriatim_run_tgt
// Seriatim Run Target                                                                                             
// Column:SERIATIM_RUN_TGT
//========================================================
double FIA_LIAB_UDF::fia_liab_seriatim_run_tgt(int t) {
//^^^



//^^^

#line 1 "seriatim_run_tgt.FIA_LIAB.for"
if (isMainModel)
	return NO_AVG;	

if (!independent_flag)
	return 0.0;

// Determine the segment element for the model point
for (int seg_num = 0; seg_num < company->segments.size(); seg_num++)
	{ 
	if (seg_id == company->segments[seg_num]) // segments is the string list of business segments
		{
		this->seg = company->sm_seg[seg_num];
		break; // segment id matched
		}
	}

initialize(t); //call once, for time t==0

if (t != 0) 
	return 0.0;

// Create processing message information
static int loaded_proj_task_loop = -999;
static int counter = 0;

if (loaded_proj_task_loop != proj_task_loop_num)
	{
	counter = 0;
	loaded_proj_task_loop = proj_task_loop_num;
	}

counter++;

//reset variables and loop twice if PBA
if (reins_flag)
	seg->seriatim_reins_used = true;

int found_cohort = false;
int cohorts = 0;
int pba_loops = 1;

/* Multiple loops are needed only for PBA variable processing.*/
if (target_column.find("valn_tgt_pba_scen_amt") < string::npos)
	pba_loops = 2;

for (int pba_loop = 0; pba_loop < pba_loops; pba_loop++)
	{
	// reset values of fia_ann_pba submodel
	sm_fia_ann_pba[0]->resetValues();

	for (int time = 0; time <= last_proj_period; time++)
		{
		for (seriatim_map::iterator column_iter = seg->seriatim_totals.begin(); 
		     column_iter != seg->seriatim_totals.end(); column_iter++)
		    {
			if (!pba_loop && ((*column_iter).first).second == prod)
				{
				if (target_column.find("valn_tgt_pba_scen_amt") < string::npos)
					{
					pba_valn_flag = true;
					pba_scen_amt_valn_flag = true;
					}

				int colnum = Column(((*column_iter).first).first).Number();	
				if (colnum >= 0)
					{
					((*column_iter).second)[0][0][time] += Column(colnum).Value(time);
					}

				if (target_column.find("valn_tgt_pba_scen_amt") < string::npos)
					{
					pba_scen_amt_valn_flag = false;
					pba_valn_flag = false;
					}
				}
			else if (((*column_iter).first).second == prod_ann_pba)
				{
				int colnum = sm_fia_ann_pba[0]->Column(((*column_iter).first).first).Number();	
		
				if (colnum >= 0)
					{
					StrEnum::EnumValue pba_calc_defn = sm_fia_ann_pba[0]->res_cap_calc_defn;
					StrEnum::EnumValue pba_reins_defn = sm_fia_ann_pba[0]->reins_defn;
		
					// special handling for fia_ann_pba columns
					pba_valn_flag = true;
					pba_scen_amt_valn_flag = true;

					if (pba_loop == 0)
						{
						sm_fia_ann_pba[0]->reins_defn = GROSS;

						// Set working_res_def to Cash Value to retrieve the cash value into the fia_ann_pba submodel
						sm_fia_ann_pba[0]->working_res_defn = CASH_VALUE;
				
						((*column_iter).second)[0][0][time] += sm_fia_ann_pba[0]->Column(colnum).Value(time);
						}
		
					if (pba_loop == 1)
						{
						sm_fia_ann_pba[0]->reins_defn = NET;

						// Set working_res_def to Cash Value to retrieve the cash value into the fia_ann_pba submodel
						sm_fia_ann_pba[0]->working_res_defn = CASH_VALUE;
		
						((*column_iter).second)[0][1][time] += sm_fia_ann_pba[0]->Column(colnum).Value(time);
						}
		
					// restore pba definitions
					sm_fia_ann_pba[0]->res_cap_calc_defn = pba_calc_defn;
					sm_fia_ann_pba[0]->reins_defn = pba_reins_defn;	
		
					pba_scen_amt_valn_flag = false;
					pba_valn_flag = false;
					}
				}
			else if (!pba_loop && ((*column_iter).first).second == prod_sfas97rd)
				{
				int colnum = sm_fia_sfas97rd[0]->Column(((*column_iter).first).first).Number();	
				if (colnum >= 0)
					{
					xstring cohort;
					xstring mp_cohort_gross = sfas97rd_cohort_id_gross;
					xstring mp_cohort_ceded = sfas97rd_cohort_id_ceded;
					
					int rein_el = reins_flag;
					
					if (!found_cohort)
						{
						for (cohorts = 0; cohorts < seg->sm_sfas97rd.size() && !found_cohort; cohorts++)
							{
							cohort = seg->gaap_cohorts_sfas97rd[cohorts];
							
							xstring mp_cohort_map_id;
							if (rein_el /*reins_flag*/)
								mp_cohort_map_id = sfas97rd_cohort_id_ceded;
							else 	
								mp_cohort_map_id = sfas97rd_cohort_id_gross;
							
							if (mp_cohort_map_id == cohort)
								found_cohort = true;
							
							if (!found_cohort)
								found_cohort 
								= seg->sm_sfas97rd[cohorts][0]->setup_cohorts(issue_yr, plan_code, 
								   										   mp_cohort_map_id, cohort);
							
							if(found_cohort)
								{
								seg->sm_sfas97rd[cohorts][0]->cohort_first_issue_period
								= min(seg->sm_sfas97rd[cohorts][0]->cohort_first_issue_period,
								      -elapsed_mths);

								seg->sm_sfas97rd[cohorts][0]->cohort_last_issue_period
								= max(seg->sm_sfas97rd[cohorts][0]->cohort_last_issue_period,
								      -elapsed_mths);

								seg->sm_sfas97rd[cohorts][0]->cohort_max_maturity_period
								= max(seg->sm_sfas97rd[cohorts][0]->cohort_max_maturity_period,
								      maturity_period);
								
								if (rein_el /*reins_flag*/)
									sfas97rd_cohort_id_ceded = cohort;
								else	
									sfas97rd_cohort_id_gross = cohort;

								if (reins_flag)
									seg->sm_sfas97rd[cohorts][0]->cohort_reins_indicator = 1;
								}
							}

						--cohorts;

						if (!found_cohort)
							return 0.0;
						}	
					
					if (!gaap_flag && !valn_flag)
						return NO_AVG;
					
					for (int rein_el2 = 0; rein_el2 < sm_fia_sfas97rd.size(); rein_el2 ++)
						{
						((*column_iter).second)[cohorts][rein_el2][time] 
						  += sm_fia_sfas97rd[rein_el2]->Column(colnum).Value(time);
						}

					seg->sfas97rd_seriatim_cohort_used[cohorts] = true;
					}
				}
			}
		}
	}

finalize(t);

if (counter % 100 == 0)
	{
	// format number with commas
	stringstream s;
	class num_format: public numpunct<char> 
		{
		string do_grouping() const { return "\003";}
		char_type do_thousands_sep() const { return ','; }
		};
	s.imbue(locale(locale(), new num_format));
	s << counter;

	log_screen << ":: Completed " << s.str() << " FIA model points." << MSG_USER;
	}

return 1.0;

}


