double FIA_LIAB_UDF::fia_liab_snfl_prospective_e_aig(int t) {
//^^^



//^^^

#line 1 "snfl_prospective_e_aig.FIA_LIAB.for"
// Constructed new column for the SNFL Prospective calculation on fund_val_fixed. JILU 05-12-2022
if (t <= commencement_period || t > final_period)
	return NO_AVG;

// Return NO_AVG if ca_mva_cv_floor switch is off
if (ca_mva_cv_floor_aig == NO)
	return NO_AVG;

// Set appropriate maturity age for calculation
int maturity_age = max(snfl_maturity_age_aig , issue_age_mp + snfl_add_age_aig);

double guaranteed_interest_rate = 0.0;// JYL 20220629: rate should be annual

// Determine account type and assign guaranteed rate accordingly
temp_key_cred_type_dyn_aig = crediting_type_dyn_aig; 
StrEnum::EnumValue crediting_rate_defn_local = sm_fia_account[0]->crediting_rate_defn;
if ( crediting_rate_defn_local == FIXED_RATE )
{	
	pol_yr_lookup_gen2 = pol_yr(t);
	temp_key_cred_type_dyn_aig = crediting_type_dyn_aig;
	double crediting_rate_min_local = crediting_rate_min;
	guaranteed_interest_rate = crediting_rate_min_local;// JYL 20220629: rate should be annual
}
else
{	
	pol_yr_lookup_gen2 = pol_yr(t);
	temp_key_cred_type_dyn_aig = crediting_type_dyn_aig;
	double strategy_term_floor_aig_local = sm_fia_account[0]->strategy_term_floor_aig;
	guaranteed_interest_rate = strategy_term_floor_aig_local;// JYL 20220629: rate should be annual
}
	
// Calculate return values for column snfl_prospective_e_aig
double snfl_prospective_e_aig = 0.0;

snfl_prospective_e_aig = fund_val_fixed(t) * 
		pow((1.0 + guaranteed_interest_rate) / (1.0 + guaranteed_interest_rate + snfl_add_interest_rate_aig) , 
		max(0, (maturity_age - issue_age_mp - t / 12.0) ));// JYL 20220629: rate should be annual

// END JYL 20220621

return snfl_prospective_e_aig;


}


