//@@ START - stat_res_carvm
// Statutory CARVM Reserve                                                                                             
// Column:STAT_RES_CARVM
//========================================================
double FIA_LIAB_UDF::fia_liab_stat_res_carvm(int t) {
//^^^



//^^^

#line 1 "stat_res_carvm.FIA_LIAB.for"
if (t < commencement_period || t > final_period)
     return NO_AVG;

if (pricing_flag && t == start_period
    && valn_period == 0)
    return NO_AVG;

if (calc_carvm_defn == NO)
	return NO_AVG;

if (stat_res_defn == PERCENT_FUND_VALUE)
	return fund_val_fixed(t) * stat_res_pct;

if (stat_res_defn == PERCENT_CASH_VALUE)
	return cash_val(t) * stat_res_pct;

if (t == 0 && valn_period != 0)
	return init_stat_res_carvm;

if (t == 1)
	stat_res_carvm(t - 1); //force call for calculation order

// Determine if model point uses monthly sum cap crediting and use that in check for full CARVM calculation
// Will calculating CARVM monthly for monthly sum cap cases since index crediting is based on cumulative changes in the index
bool mthly_sum_cap_model_point = false;
for (int i = 0; i < sm_fia_account.size(); i++)
	{
	temp_key_cred_type_dyn_aig = crediting_type_dyn_aig; //WTW - Gen2  - Mutating Lookup Term
	if (sm_fia_account[i]->crediting_rate_defn == MONTHLY_SUM_CAP)
		{
		mthly_sum_cap_model_point = true;
		break;
		}
	}

//if ((t == 0 && valn_period == 0) || t + elapsed_mths == 1 || pol_mth(t) == 6 || pol_mth(t) == 12 || cal_mth(t) == 12
//	|| mthly_sum_cap_model_point)
if ((t == 0 && valn_period == 0) || t + elapsed_mths == 1 || mthly_sum_cap_model_point// || pol_mth(t) == 12)
  || /*sm_carvm_stat->*/stat_carvm_cont_defn == NO && pol_mth(t) == 1																					// changed by HYH 09/14/2021
  || /*sm_carvm_stat->*/stat_carvm_cont_defn == YES && (pol_mth(t) == 12 || gmwb_flag && t == 12 * (gmwb_req_yrs_wait + gmwb_exercise_yrs_aig(t)) + 1))	// changed by HYH 09/14/2021
	{
	if (t + elapsed_mths <= 0)
		return NO_AVG;

	if (/*sm_carvm_stat->*/res_period != t) //WTW - Gen2 - RebasedModelObjectCanOnlyBeCalledFromARebasingFormula
		/*sm_carvm_stat->*/res_period = t;

	double stat_res_carvm = 0.0;

	int carvm_annuitzn_tests_cnt = 1;
	vector <string> carvm_annuitzn_tests_input; 

	if (/*sm_carvm_stat->*/stat_carvm_calc_annuitzn_defn != NOT_APPLICABLE)//WTW - Gen2 - RebasedModelObjectCanOnlyBeCalledFromARebasingFormula
		{
		split_string_usl(/*sm_carvm_stat[0]->*/stat_carvm_annuitzn_tests.c_str(), carvm_annuitzn_tests_input, ",");//WTW - Gen2 - RebasedModelObjectCanOnlyBeCalledFromARebasingFormula//WTW - Gen2 - split_tring internal RAFM function
		carvm_annuitzn_tests_cnt = carvm_annuitzn_tests_input.size();
		}

	int gmwb_exercise_point_test_cnt = 1;
	vector <string> gmwb_exercise_points_input;

	// If GMWB is already exercised, we only project CARVM with 1 exercise point equal to 0
	// Else run tests specified plus one test of no GMWB exercise
	if (gmwb_flag && pol_yr(t) <= (gmwb_req_yrs_wait + xint(gmwb_exercise_yrs_aig(t))))  // 20200303 MTC - Confinement rider, dynamic exercise
		{
		split_string_usl(/*sm_carvm_stat[0]->*/stat_carvm_gmwb_exercise_points.c_str(), gmwb_exercise_points_input, ",");//WTW - Gen2 - RebasedModelObjectCanOnlyBeCalledFromARebasingFormula//WTW - Gen2 - split_tring internal RAFM function
		gmwb_exercise_point_test_cnt = gmwb_exercise_points_input.size() + 1;	
		}

	for (int i = 0; i < carvm_annuitzn_tests_cnt; i++)
		{
		if (/*sm_carvm_stat->*/stat_carvm_calc_annuitzn_defn != NOT_APPLICABLE)//WTW - Gen2 - RebasedModelObjectCanOnlyBeCalledFromARebasingFormula
			carvm_annuitzn_tests_number = atoi(xstring(carvm_annuitzn_tests_input[i]));

		for (int j = 0; j < gmwb_exercise_point_test_cnt; j++)
			{
			if (gmwb_flag && pol_yr(t) <= (gmwb_req_yrs_wait + xint(gmwb_exercise_yrs_aig(t))))  // 20200303 MTC - Confinement rider, dynamic exercise
				{
				if (j < gmwb_exercise_point_test_cnt - 1)
					gmwb_exercise_point = atoi(xstring(gmwb_exercise_points_input[j]));
				else // Test with no exercise of GMWB
					gmwb_exercise_point = 9999; // No exercise of GMWB
				}
			else
				gmwb_exercise_point = 0;

			for (int k = 0; k < sm_carvm_stat.size() ; k++)
				{
				//sm_carvm_stat[k]->resetValues();
				sm_carvm_stat[k]->rebaseModel(0);//WTW - Gen2 - resetValues() is not supported
				sm_carvm_stat[k]->set_hidden_variables(xint(t));  // DTL 20200121: TFS 86514
				if (sm_carvm_stat[k]->res_integrated(0) > stat_res_carvm)
					stat_res_carvm = sm_carvm_stat[k]->res_integrated(0);
				}	

			if (carvm_stat_detail_rpt_defn == YES && gen2_defn == NO)//WTW - Gen2 - writeModel() is an unsupported function
				write_reserves(t, "STAT", carvm_annuitzn_tests_number, gmwb_exercise_point);
			}
		}
	
	// 20220407 STW: IA STAT change requested by model owner
	if (carvm_res_floor_switch_aig == YES)
		return max(stat_res_carvm, carvm_res_floor_pct_aig * fund_val_fixed(t));

	return stat_res_carvm;
	}

//20230110 JYL: comment out following condition as it is redundant
//if (fabs(fund_val_fixed(t - 1)) < model_point_amount_threshold)
//	return 0.0;

//return stat_res_calc_interim("stat_res_carvm", t);
//WTW - Gen2 - Column Interface

//return stat_res_carvm(t - 1)
//	   * (fund_val_fixed(t) / fund_val_fixed(t - 1));	

// 20220201 LYF START: include projected CSV in interpolation

// 20230110 JYL: add condition to return zero when surv rate reaches 0
if(surv(t - 1) < model_point_amount_threshold || fund_val_fixed(t) < model_point_amount_threshold) // 20220315 added condition to set set reserve to 0 at the period of fund exhaustion
	return 0.0;

// changed by HYH 09/14/2021
// If GMWB is already exercised, we only interpolate CARVM based on the change in surv * (1 + option mkt val%)
// Else interpolate CARVM based on the change in (fund_val_fixed + hedge_mkt_val)
	
double stat_res_interpolated; 
double csv_final = proj_csv_for_interpolation_aig(t); 

if (gmwb_flag && pol_yr(t) > (gmwb_req_yrs_wait + xint(gmwb_exercise_yrs_aig(t))))  // after income starts
{
	//20210927 STW: formula change to include interest credit rate
	stat_res_interpolated =  stat_res_carvm(t - 1)
			* ((surv(t) * (1 + hedge_mkt_val(t) / fund_val_fixed(t)) * (1 + weighted_ending_strategy_return_aig(t))) 
			/ (surv(t - 1) * (1 + hedge_mkt_val(t - 1) / fund_val_fixed(t - 1))));
}
// end of changes by HYH 09/14/2021
else  // before income starts
{
	stat_res_interpolated =  stat_res_carvm(t - 1)
			* ((fund_val_fixed(t) + hedge_mkt_val(t)) / (fund_val_fixed(t - 1) + hedge_mkt_val(t - 1)));	// changed by HYH 09/14/2021
}
	
double stat_res_carvm = max(csv_final, stat_res_interpolated);
// 20220407 STW: IA STAT change requested by model owner
if (carvm_res_floor_switch_aig == YES)
{
	return max(stat_res_carvm, carvm_res_floor_pct_aig * fund_val_fixed(t));
}

return stat_res_carvm;
// 20220201 LYF End


}


