//@@ START - weighted_ending_strategy_return_aig
// Weighted Ending Strategy Return                                                                                             
// Column:WEIGHTED_ENDING_STRATEGY_RETURN_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_weighted_ending_strategy_return_aig(int t) {
//^^^



//^^^

#line 1 "weighted_ending_strategy_return_aig.FIA_LIAB.for"
/*
	Weighted sum refactor.  MCHING 9-3-2021
*/

if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return NO_AVG;	
}

//return weighted_sum_over_funds_e_bef_aig("crediting_rate", t);
//WTW - Gen2 - Column Interface
double total = 0.0;

for (size_t i = 0; i < sm_fia_account.size(); i++)
{
	if (fund_val_e_bef(t) > SMALL_DOUBLE)
	{
		// Weigh by current allocation
		total += sm_fia_account[i]->crediting_rate(t) * (sm_fia_account[i]->fund_val_e_bef(t) / fund_val_e_bef(t));
	}
	else
	{
		// Weigh by initial allocation
		total += sm_fia_account[i]->crediting_rate(t) * (sm_fia_account[i]->fund_val_split_prop);
	}
}
		
return total;

}


