//@@ START - withdrl_benefits
// Partial Withdrawal Benefit                                                                                             
// Column:WITHDRL_BENEFITS
//========================================================
double FIA_LIAB_UDF::fia_liab_withdrl_benefits(int t) {
//^^^
if ( isRebaseClone && sm_peer_model  && t <= rebase_period ){
	return rebase_value(711,"withdrl_benefits",t);
}



//^^^

#line 1 "withdrl_benefits.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return NO_AVG;
}

double gross_withdrl_cv = withdrl_benefits_gross_aig(t);
double mva_cv			= mva_amt_partial_wdl_aig(t);
double wdl_chg_cv		= withdrl_benefits_chg_aig(t);
double net_withdrl_cv	= max(0, gross_withdrl_cv - wdl_chg_cv - mva_cv);

return net_withdrl_cv;

}


//@@ END

//@@ START - withdrl_benefits_chg_aig
// Partial withdrawal charge:                                                                                             
// Column:WITHDRL_BENEFITS_CHG_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_withdrl_benefits_chg_aig(int t) {
//^^^



//^^^

#line 1 "withdrl_benefits_chg_aig.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return NO_AVG;
}

double pfwd_entitlement_e_bef_cv = pfwd_entitlement_remaining_e_bef(t) * surv_period(t);
double mawa_benefit_remaining	 = gmwb_entitlement_remaining_e_bef_aig(t) * surv_period(t);
pfwd_entitlement_e_bef_cv		 = max(pfwd_entitlement_e_bef_cv, mawa_benefit_remaining);

double gross_withdrl_e_bef_cv	 = withdrl_benefits_gross_aig(t);
double chg_base					 = max(0, gross_withdrl_e_bef_cv - pfwd_entitlement_e_bef_cv);
		
pol_yr_lookup_gen2 = pol_yr(t);//WTW - Gen2 - surr_chg_pct cannot use time based lookup in an external formula - need to update all instances to use this working variable
double wdl_chg					 = fia->surr_chg_pct * chg_base;

return wdl_chg;

}


//@@ END

//@@ START - withdrl_benefits_gross_aig
// Gross (of withdrawal charges) partial withdrawal:                                                                                             
// Column:WITHDRL_BENEFITS_GROSS_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_withdrl_benefits_gross_aig(int t) {
//^^^



//^^^

#line 1 "withdrl_benefits_gross_aig.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return NO_AVG;
}

double fund_released_withdrl_cv = fund_released_withdrl(t);

if (fund_val_defn_aig == EIV && fund_released_withdrl_cv > SMALL_DOUBLE)
{
	// For NYIA, reduction in fund value may or may not be equal to the withdrawal...

	double surv_period_cv    = surv_period(t);
	double fund_val_e_bef_cv = fund_val_e_bef(t);
	double fund_val_e_cv     = fund_val_e_bef_cv * surv_period_cv;
	double mav_e_bef_cv      = min_accum_val_e_bef_aig(t);
	double mav_e_cv          = mav_e_bef_cv * surv_period_cv;

	if (mav_e_bef_cv > fund_val_e_bef_cv)
	{
		double reduction_pct     = fia->pfwd_rate_mthly_min_accum_val_aig(t);
		fund_released_withdrl_cv = mav_e_cv * reduction_pct;
	}

	fund_released_withdrl_cv = min(fund_val_e_cv, fund_released_withdrl_cv);
}

double interest_earned_wdls = 0.0;
if (pfwd_partial_interest_credited_aig == YES)
{
	//interest_earned_wdls = strategy_interest_earnings_on_gross_wdl_aig(t);
	interest_earned_wdls   += withdrl_benefits_gross_regular_int_credit_e_bef_aig(t);
	interest_earned_wdls   += withdrl_benefits_gross_excess_int_credit_e_bef_aig(t);
	interest_earned_wdls   *= surv_period(t);
}


return fund_released_withdrl_cv + interest_earned_wdls;

}


