{
	return NO_AVG;
}

double excess_wdl_cv	= withdrl_benefits_gross_excess_e_bef_aig(t);
double credit_rate_cv	= crediting_rate_partial_e_bef_aig(t);  // Refactor to remove duplicate partial crediting rate. MCHING 1-11-2022
