//@@ START - withdrl_benefits_gross_regular_e_bef_aig
// Regular withdrawals (not excess):                                                                                             
// Column:WITHDRL_BENEFITS_GROSS_REGULAR_E_BEF_AIG
//========================================================
double FIA_LIAB_UDF::fia_liab_withdrl_benefits_gross_regular_e_bef_aig(int t) {
//^^^



//^^^

#line 1 "withdrl_benefits_gross_regular_e_bef_aig.FIA_LIAB.for"
if (t <= commencement_period || t > final_period/*maturity_period*/)
{
	return NO_AVG;
}

double regular_withdrl_cv = 0.0;

if (gmwb_flag && pol_yr(t) > gmwb_req_yrs_wait + xint(gmwb_exercise_yrs_aig(t)))
{
	double gross_withdrl_cv		= gmwb_max_wdl_amt_utilized(t) * (wdl_period_mths_aig / 12.0);

	if (gmwb_cohort_utilz_defn == YES)
	{
		//temp_key_iss_age = issue_age_mp; //WTW - Gen2 - Mutating Lookup Term
		gross_withdrl_cv *= gmwb_cohort_utilz_rate;
	}
	else
	{
		gross_withdrl_cv *= pfwd_rate_dynamic(t);
	}

	double pfwd_remaining_cv	= gmwb_entitlement_remaining_e_bef_aig(t);
	regular_withdrl_cv			= min(gross_withdrl_cv, pfwd_remaining_cv);
}
else if (pol_yr(t) > preincome_exercise_yrs_aig)
{
	if (mod(pol_mth(t) - 1, wdl_period_mths_aig) == 0.0) 
	{
		if (abs(surv_period(t)) > SMALL_DOUBLE)
		{
			// We want an `e_bef` value but `pfwd_entitlement` is an `e` value so we have to adjust it with survivorship
			regular_withdrl_cv = pfwd_entitlement(t) * pfwd_use_aig(t) * (wdl_period_mths_aig / 12.0) / surv_period(t); //ZHL 20230803: replacethe input pfwd_use to pfwd_use_aig(t) column to implement the Non-GMWB partial WD assumptions for 2023Q3 unlocking
		}
	}
}

double credit_rate_cv	= 0.0;
if (pfwd_partial_interest_credited_aig == YES)
{
	credit_rate_cv = (1 + weighted_strategy_return_aig(t)) / (1 + weighted_ending_strategy_return_aig(t)) - 1.0;
}
      
double fund_val_e_bef_cv   = fund_val_e_bef(t) * (1 + credit_rate_cv);

regular_withdrl_cv			= min(regular_withdrl_cv, fund_val_e_bef_cv);

return regular_withdrl_cv;

}


