#line 1 "calc_base_mawp_pct_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::calc_base_mawp_pct_aig(
	int gmwb_withdrl_mth, StrEnum::EnumValue enhanced_income_benefit, StrEnum::EnumValue gender_cv)
{
	int issue_age_cv = issue_age_calc_aig(gender_cv);
	StrEnum::EnumValue coverted_person_status_tmp = covered_person_status_aig;
	covered_person_status_aig = covered_person_status_calc_aig(gender_cv);

	// Store the global state
	int gmwb_withdrl_age_tmp			= gmwb_withdrl_age;

	int gmwb_withdrl_yr					= pol_yr(min(t_high,gmwb_withdrl_mth));//WTW - Gen2 - time guards
	gmwb_withdrl_age					= max(issue_age_cv + gmwb_withdrl_yr - 1, 0);
	
	double base_mawp = 0.0;//WTW - Gen2 - Mutating Lookup Term
	// 20200603 DTL: NYIA
	if ( gmwb_wdl_pct_tbl_style_aig == ISSUE_AGE_AND_DURATION )
	{
		gmwb_withdrl_age			= issue_age_cv;
		temp_key_cov_person_status	= covered_person_status_aig; //WTW - Gen2 - Mutating Lookup Term
		base_mawp			= gmwb_max_annual_wdl_pct;//WTW - Gen2 - Mutating Lookup Term
	}
	else if ( gmwb_wdl_pct_tbl_style_aig ==  AGE_AT_FIRST_WITHDRAWAL )
	{
		gmwb_withdrl_age			= max(issue_age_cv + gmwb_withdrl_yr - 1, 0);
		temp_key_cov_person_status	= covered_person_status_aig; //WTW - Gen2 - Mutating Lookup Term
		base_mawp			= gmwb_max_annual_wdl_pct;//WTW - Gen2 - Mutating Lookup Term
	}
	else
	{
		string err_msg = "`fia_liab->calc_mawp_pct_aig(...)`: unhandled value of `fia_liab->gmwb_wdl_pct_tbl_style_aig`";
		throw FatalError(xstring(err_msg));
	}
	// 20200603 DTL: NYIA

	// Get MAWP
	//double base_mawp							= gmwb_max_annual_wdl_pct;//WTW - Gen2 - Mutating Lookup Term - Moved up under if/else conditional

	// 20230313 SJ remove the code which return only base mawp for mawp/pipp split products
	//if(gmwb_mawp_pipp_split_aig == YES)
	//{
	//	return base_mawp;
	//}

	// 20200603 DTL: NYIA
	if ( gmwb_wdl_pct_tbl_style_aig == ISSUE_AGE_AND_DURATION )
	{
		int gmwb_max_annual_wdl_pol_yr_tmp = gmwb_max_annual_wdl_pol_yr_aig;
		gmwb_max_annual_wdl_pol_yr_aig     = gmwb_withdrl_yr;

		temp_key_cov_person_status = covered_person_status_aig; //WTW - Gen2 - Mutating Lookup Term
		base_mawp += gmwb_max_annual_wdl_addn_pct_aig;

		gmwb_max_annual_wdl_pol_yr_aig     = gmwb_max_annual_wdl_pol_yr_tmp;

		// 20221201 SJ: To allow the application of Reg 47 of NY for the Guardian product, add the option that uses a formulaic approach to solve for MAWP rate.
		int attained_age_cv = max(issue_age_cv + gmwb_withdrl_yr - 1, 0);		
		if (gmwb_mawp_reg_47_aig == YES && issue_age_cv >= gmwb_mawp_reg_47_min_issue_age_aig && attained_age_cv >= gmwb_mawp_reg_47_min_attained_age_aig)
		{
			base_mawp = calc_reg_47_mawp_pct_aig(issue_age_cv, covered_person_status_aig, gmwb_withdrl_yr);
		}
		// 20221201 SJ END
	}
	// 20200603 DTL: NYIA

	// Restore the global state
	gmwb_withdrl_age					= gmwb_withdrl_age_tmp;
	covered_person_status_aig			= coverted_person_status_tmp;

	if (enhanced_income_benefit == EXERCISE)
	{
		temp_key_cov_person_status	= covered_person_status_aig; // 20230313 SJ Split confinement multiplier by contract type (single/joint)
		base_mawp							*= enhanced_income_mawp_mult_aig;
	}
	else if (enhanced_income_benefit == NO_EXERCISE)
	{
		//pass
	}
	else
	{
		throw FatalError("Unhandled enhanced_income_benefit requested in calc_base_mawp_pct_aig!");  // 20200704 MTC - Updated error message
	}

	return base_mawp;
}



#line 1 "calc_gmwb_flex_aig.FIA_LIAB.for"                                                                                   
void FIA_LIAB::calc_gmwb_flex_aig(void)
{
	if (enhanced_income_defn_aig == YES)
	{
		if (gen2_defn == NO)
			makeRunLogYellow();	  //WTW - Gen2 - makeRunLogYellow() not supported
		
		log_screen << "Warning! "
				   << "  Confinement is running with GLB FLEX. " 
				   << "  Logic is possibly broken." 
				   << MSG_ERROR;	
	}

  	if (gender_aft_act_aig != gender_mp)
	{
		if(covered_person_status_aig == SINGLE)
		{
			covered_person_status_aig = JOINT;
			gender_mp = JOINT;
			issue_age_mp = issue_age_calc_aig(gender_mp);
			//age_1st_wdl = va->issue_age + va->gmwb_wait_period_aig;			
		}
		else if(covered_person_status_aig == JOINT)
		{
			covered_person_status_aig = SINGLE;		
			gender_mp = gender_aft_act_aig;
			issue_age_mp = issue_age_calc_aig(gender_mp);
			//age_1st_wdl = va->issue_age + va->gmwb_wait_period_aig;
		}
		else
		{
			throw FatalError("Unhandled covered_person_status_aig requested in proj_gmwb_base_bef_withdrl_one_period.");
		}
	}
  
  return;
}



#line 1 "calc_mawp_pct_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::calc_mawp_pct_aig(int t, int gmwb_withdrl_mth, StrEnum::EnumValue gender_cv, StrEnum::EnumValue enhanced_income_benefit, StrEnum::EnumValue income_phase, bool hypothetical_assessment )  // 20200704 MTC - Changed method signature
{
	double base_mawp = calc_base_mawp_pct_aig(gmwb_withdrl_mth, enhanced_income_benefit, gender_cv);

	// 20201016 STW return only base mawp for mawp/pipp split products
	if(gmwb_mawp_pipp_split_aig == YES || gmwb_withdrl_rate_indexing_defn_aig == NONE)
	{
		return base_mawp;
	}

	// 20200704 MTC - Updated logic for assessment mechanics
	double withdrl_rate_addn_cv;

	if (gmwb_withdrl_rate_indexing_assessment_defn_aig == YES)
	{
		// Recalculate withdrawal rate at every t
		withdrl_rate_addn_cv = gmwb_withdrl_rate_indexing_addn_calc_aig(t, income_phase, hypothetical_assessment);
	}
	else
	{
		// Lock withdrawal rate addition once income starts
		withdrl_rate_addn_cv = gmwb_withdrl_rate_indexing_addn_calc_aig(gmwb_withdrl_mth, income_phase, hypothetical_assessment);
	}
	
	double mawp = base_mawp + withdrl_rate_addn_cv;
	// 20200704 MTC END

	return mawp;
}



#line 1 "calc_mva_amt_full_surr_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::calc_mva_amt_full_surr_aig(double mva_final_factor, 
								  double mva_base,
								  double free_withdrawal_amount,
								  double premium_enhancement_recapture)
{
	// 20180627 MTC - MVA Mostly ported from mva_calculation in MoSes
	// 20181105 MTC - Split final factor calculation from amount calculation

	// Calculate MVA amount
	double full_surrender_mva_amount = max(0, mva_base - free_withdrawal_amount - premium_enhancement_recapture) * mva_final_factor;

	return full_surrender_mva_amount;
}



#line 1 "calc_mva_rate_full_surr_default_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::calc_mva_rate_full_surr_default_aig(double I, 
										   double J,
										   int N,
										   double contract_value,
										   double minimum_withdrawal_value,
										   double withdrawal_charge,
										   double remaining_pfwd,
										   double premium_enhancement_recapture)
{
	// 20180627 MTC - MVA Mostly ported from mva_calculation in MoSes

	// Calculate MVA factor
	double mva_factor = (J - I) * (N / 12.0);
	
	// Calculate MVA cap
	double mva_cap_percent = 1.0 - minimum_withdrawal_value / 
								   (contract_value - withdrawal_charge - premium_enhancement_recapture);

	//20250922 ZL new MVA cap formula
	if (mva_cap_change_2025_crbg == AFTER)
	{
		mva_cap_percent = max(0., (contract_value - withdrawal_charge - minimum_withdrawal_value)/ 
								   (contract_value - remaining_pfwd));
	}

	// Set MVA floor
	double mva_floor_percent = -mva_cap_percent;

	// Calculate MVA final factor
	double mva_final_factor = max(min(mva_factor, mva_cap_percent), mva_floor_percent);

	return mva_final_factor;
}



#line 1 "calc_pipp_pct_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::calc_pipp_pct_aig(int t, int gmwb_withdrl_mth, StrEnum::EnumValue gender_cv)
{  
	// 20201016 STW: new function for pipp rate
	int gmwb_withdrl_age_tmp						= gmwb_withdrl_age;
	StrEnum::EnumValue gender_tmp					= gender_mp;
	gender_mp										= gender_cv;
	double issue_age_cv								= issue_age_calc_aig(gender_cv);
	StrEnum::EnumValue covered_person_status_tmp	= covered_person_status_aig;
	covered_person_status_aig						= covered_person_status_calc_aig(gender_cv);

	int gmwb_withdrl_yr					= pol_yr(gmwb_withdrl_mth);
	//gmwb_withdrl_age					= max(issue_age_cv + gmwb_withdrl_yr - 1, 0); //WTW - Gen2 - Mutating Lookup Term - move by variable call

	double pipp;
	if(gmwb_pipp_stepup_ind_aig(t) == 0)
	{
		gmwb_withdrl_age				= max(issue_age_cv + gmwb_withdrl_yr - 1, 0); //WTW - Gen2 - Mutating Lookup Term
		temp_key_cov_person_status		= covered_person_status_aig; //WTW - Gen2 - Mutating Lookup Term
		pipp							= gmwb_pipp_pct_aig;
	}
	else //if(gmwb_pipp_stepup_period_aig == NO)
	{
		gmwb_withdrl_age				= max(issue_age_cv + gmwb_withdrl_yr - 1, 0); //WTW - Gen2 - Mutating Lookup Term
		temp_key_cov_person_status		= covered_person_status_aig; //WTW - Gen2 - Mutating Lookup Term
		pipp							= gmwb_pipp_stepup_pct_aig;
	}

	gmwb_withdrl_age					= gmwb_withdrl_age_tmp;
	gender_mp							= gender_tmp;
	covered_person_status_aig			= covered_person_status_tmp;
  
	return pipp;
}



#line 1 "calc_reg_47_mawp_pct_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::calc_reg_47_mawp_pct_aig(int issue_age, StrEnum::EnumValue covered_person_status, int gmwb_withdrl_yr)
{
	//20221201 SJ: To allow the application of Reg 47 of NY for the Guardian product, add the calculation that uses a formulaic approach to solve for MAWP rate.
	double mawp_rate;
	int attained_age = issue_age + gmwb_withdrl_yr - 1;
	int age_diff_on_limit = min(issue_age - gmwb_mawp_reg_47_min_issue_age_aig, attained_age - gmwb_mawp_reg_47_min_attained_age_aig);
	int look_back_5yr_factor;
	
	if (age_diff_on_limit % 5 == 0 || age_diff_on_limit < 5)
	{
		look_back_5yr_factor = ceil(age_diff_on_limit / 5.0) + 1;
	}
	else
	{
		look_back_5yr_factor = ceil(age_diff_on_limit / 5.0);
	}

	int fisrt_lookup_attained_age = attained_age - look_back_5yr_factor * 5; //Find out the age when recursive calculation starts. 
	int gmwb_max_annual_wdl_pol_yr_tmp = gmwb_max_annual_wdl_pol_yr_aig;

	for (int current_age = fisrt_lookup_attained_age; current_age <= attained_age; current_age = current_age + 5)
	{
		int current_issue_age = current_age - gmwb_withdrl_yr + 1;
		
		if (current_age < gmwb_mawp_reg_47_min_attained_age_aig || current_issue_age < gmwb_mawp_reg_47_min_issue_age_aig)
		{
			gmwb_withdrl_age					= current_issue_age;
			temp_key_cov_person_status			= covered_person_status; //WTW - Gen2 - Mutating Lookup Term
			mawp_rate							= gmwb_max_annual_wdl_pct;

			gmwb_max_annual_wdl_pol_yr_aig		= gmwb_withdrl_yr;
			temp_key_cov_person_status			= covered_person_status; //WTW - Gen2 - Mutating Lookup Term
			mawp_rate += gmwb_max_annual_wdl_addn_pct_aig;
		}
		else
		{			
			gmwb_max_annual_wdl_attained_age_aig	= current_age;
			double reg_47_slope						= gmwb_mawp_reg_47_slope_aig;			
			if (gmwb_withdrl_yr == 1)
			{
				mawp_rate = xround(ceil(xround((mawp_rate * (1 + reg_47_slope) * 2000), 5)) / 2000, 4); 
				//To replicate Excel Ceiling function, multiply by a number and divide by the same number after round and ceil.
			}
			else
			{
				mawp_rate = xround(ceil(xround((mawp_rate * (1 + reg_47_slope) * 10000), 5)) / 10000, 4);
			}
		}
	}
	
	gmwb_max_annual_wdl_pol_yr_aig     = gmwb_max_annual_wdl_pol_yr_tmp;

	return mawp_rate;
}



