#line 1 "enhanced_income_benefit_eligibility_check_aig.FIA_LIAB.for"                                                                                   
bool FIA_LIAB::enhanced_income_benefit_eligibility_check_aig(int policy_year, int enhanced_income_benefit_yrs, double fund_val)
{
	if (
		   enhanced_income_flag_aig &&
		   policy_year > enhanced_income_wait_period_aig &&
		   policy_year > gmwb_req_yrs_wait &&
		   enhanced_income_benefit_yrs < enhanced_income_max_cumul_benefit_yrs_aig &&
		   fund_val > SMALL_DOUBLE
	   )
	{
		return true;
	}

	return false;
}



#line 1 "enhanced_income_benefit_exercise_check_aig.FIA_LIAB.for"                                                                                   
StrEnum::EnumValue FIA_LIAB::enhanced_income_benefit_exercise_check_aig(int policy_year, int enhanced_income_benefit_yrs, double fund_val, 
	StrEnum::EnumValue confinement_status, StrEnum::EnumValue projection_type )//WTW - Gen2 - =AVERAGE_UTILIZATION
{
	if (confinement_status != CONFINED && confinement_status != NONCONFINED)
	{
		throw FatalError("Unhandled confinement_status requested in enhanced_income_benefit_eligibility_check_aig!");
	}

	StrEnum::EnumValue enhanced_income_benefit;

	if (enhanced_income_benefit_eligibility_check_aig(policy_year, enhanced_income_benefit_yrs, fund_val) && 
	    confinement_status == CONFINED)
	{
		if (projection_type == RANDOM_UTILIZATION)
		{
			double policy_mth = (policy_year - 1.0) * 12.0 + 1.0;
			double unif_rand = enhanced_income_utilization_rand_aig(policy_mth);
			if (unif_rand < enhanced_income_benefit_utilization_pct_aig)
			{
				enhanced_income_benefit = EXERCISE;
			}
			else
			{
				enhanced_income_benefit = NO_EXERCISE;
			}
		}
		else // average utilization
		{
			enhanced_income_benefit = EXERCISE;
		}
	}
	else
	{
		enhanced_income_benefit = NO_EXERCISE;
	}


	// 20220908 SJ - Fix the enhanced income benefit exercise to consider the gmwb exercise years.
	if (
		policy_year <= gmwb_req_yrs_wait + gmwb_exercise_yrs && 
		enhanced_income_gmwb_exercise_defn_aig == USE_GMWB_EXERCISE_YRS
		)  
	{
		enhanced_income_benefit = NO_EXERCISE;
	}
	// 20220908 SJ END
	
	return enhanced_income_benefit;
}



#line 1 "enhanced_income_benefit_exercise_get_enum_aig.FIA_LIAB.for"                                                                                   
