#line 1 "fund_val_exhaust_aig.FIA_LIAB.for"                                                                                   
int FIA_LIAB::fund_val_exhaust_aig(int t, double account_value, double gmwb_max_wthdrl_amt, bool calc_to_cal_yr_exhaust )//20220829 JYL optional parameter added for LAD option AIG 2022 LAD
{
	int months_to_exhaust = 0;
	double years_to_exhaust = 0.0;
	
	years_to_exhaust =  account_value / gmwb_max_wthdrl_amt;

	if (years_to_exhaust < SMALL_DOUBLE)
	{
		months_to_exhaust = 0;
	}
	else
	{
		months_to_exhaust = ceil(years_to_exhaust * 12.0) - 1;//JYL 20230510: MOE bug fix for when AV exhaust last month of year
	}

	if(calc_to_cal_yr_exhaust)//20220829 JYL only round to nearest calendar year if optional parameter is true
	{
		while ((months_to_exhaust + t) % 12 != 0)
		{
			months_to_exhaust += 1;
		}
	}

	return months_to_exhaust;
}



#line 1 "gen_uniform_rands_default_random_engine_aig.FIA_LIAB.for"                                                                                   
void FIA_LIAB::gen_uniform_rands_default_random_engine_aig(vector<vector<double>>& uniform_rands_arr)
{
	int seed = gen_uniform_rands_seed_aig(proj_task_loop_num, mp_id);

	std::default_random_engine generator (seed);
	std::uniform_real_distribution<double> distribution (0.0,1.0);

	double random_number;
	for (size_t stream = 0; stream < NUM_UNIFORM_STREAMS_AIG; stream++)
	{
		vector<double> uniform_rands;

		for (size_t i = 0; i < t_high; i++)
		{
			random_number = distribution(generator);
			uniform_rands.push_back(random_number);
		}

		uniform_rands_arr.push_back(uniform_rands);
	}
}



