void FIA_LIAB::gen_uniform_rands_rafm_random_engine_aig(vector< vector <double>>& uniform_rands_arr)
{
	int seed = gen_uniform_rands_seed_aig(proj_task_loop_num, mp_id);
	
	Uniform::RandomGenerator(HIGH_RES);
	Uniform::GeneratorSeed(HIGH_RES, seed);
	Uniform linear_congruential_uniform(0., 1.);
	
	double random_number;
	for (size_t stream = 0; stream < NUM_UNIFORM_STREAMS_AIG; stream++)
	{
		vector <double> uniform_rands;

		for (size_t i = 0; i < t_high; i++)
		{
			random_number = linear_congruential_uniform.next();
			uniform_rands.push_back(random_number);
		}

		uniform_rands_arr.push_back(uniform_rands);
	}
}



#line 1 "gen_uniform_rands_seed_aig.FIA_LIAB.for"                                                                                   
int FIA_LIAB::gen_uniform_rands_seed_aig(int scen_num, xstring mp_id)
{   
	int seed_value;
	seed_value = int(scen_num);

	for (int i = 1; i <= mp_id.length(); i++)
	{
		seed_value += int(mp_id[i - 1]) * (i + 128);
	}

	seed_value *= 1350000011;
	return seed_value;
}



