#line 1 "get_gmwb_wdl_random_init_utilization_level_aig.FIA_LIAB.for"                                                                                   
StrEnum::EnumValue FIA_LIAB::get_gmwb_wdl_random_init_utilization_level_aig(double random_uniform_draw)
{
	gmwb_wdl_utilization_level_aig = ABOVE_MAWA;
	double above_mawa_util_pct = gmwb_wdl_utilization_init_population_aig;

	gmwb_wdl_utilization_level_aig = MAWA;
	double level_mawa_util_pct = gmwb_wdl_utilization_init_population_aig;

	gmwb_wdl_utilization_level_aig = BELOW_MAWA;
	double below_mawa_util_pct = gmwb_wdl_utilization_init_population_aig;

	if ( fabs(below_mawa_util_pct + level_mawa_util_pct + above_mawa_util_pct - 1.0) > SMALL_DOUBLE )
	{
		string err_msg = "fia_liab->get_gmwb_wdl_default_init_utilization_level_aig(...): intial utilization probabilities do not add up!";
		throw FatalError(xstring(err_msg));
	}

	if (random_uniform_draw <= below_mawa_util_pct)
	{
		return BELOW_MAWA;
	}
	else if (random_uniform_draw <= below_mawa_util_pct + level_mawa_util_pct)
	{
		return MAWA;
	}
	else
	{
		return ABOVE_MAWA;
	}
}



#line 1 "get_gmwb_wdl_random_utilization_level_aig.FIA_LIAB.for"                                                                                   
StrEnum::EnumValue FIA_LIAB::get_gmwb_wdl_random_utilization_level_aig(
	StrEnum::EnumValue current_level,
	StrEnum::EnumValue transition_tbl_id,
	double random_uniform_draw)
{
	double to_below_util = get_gmwb_wdl_random_utilization_transition_prob_aig(current_level, BELOW_MAWA, transition_tbl_id);
	double to_level_util = get_gmwb_wdl_random_utilization_transition_prob_aig(current_level, MAWA, transition_tbl_id);
	double to_above_util = get_gmwb_wdl_random_utilization_transition_prob_aig(current_level, ABOVE_MAWA, transition_tbl_id);

	if ( fabs(to_below_util + to_level_util + to_above_util - 1.0) > SMALL_DOUBLE )
	{
		string err_msg = "fia_liab->get_gmwb_wdl_random_utilization_level_aig(...): transition probabilities do not add up!";
		throw FatalError(xstring(err_msg));
	}

	if (random_uniform_draw <= to_below_util)
	{
		return BELOW_MAWA;
	}
	else if (random_uniform_draw <= to_below_util + to_level_util)
	{
		return MAWA;
	}
	else
	{
		return ABOVE_MAWA;
	}
}



