		gmwb_wdl_utilization_tgt_level_aig  = tgt_level;//WTW - Gen2 - Mutating Lookup Terms
		get_gmwb_wdl_utilization_transition_prob_cv  = gmwb_wdl_utilization_secondary_transition_prob_aig;
