#line 1 "get_gmwb_wdl_utilization_level_aig.FIA_LIAB.for"                                                                                   
StrEnum::EnumValue FIA_LIAB::get_gmwb_wdl_utilization_level_aig(
	int t, double unif_rv_cv, StrEnum::EnumValue util_level_cv, double fund_val_e_bef_cv , double gmwb_inf_e_bef_cv )
{
	StrEnum::EnumValue new_util_level_cv;

	if (gmwb_inf_e_bef_cv < SMALL_DOUBLE)
	{
		new_util_level_cv = NONE;
	}
	else if (util_level_cv == NONE)
	{
		new_util_level_cv = get_gmwb_wdl_random_init_utilization_level_aig(unif_rv_cv);
	}
	else
	{
		StrEnum::EnumValue markov_matrix_tbl_id;

		double tbl_threshold = gmwb_wdl_utilization_transition_matrix_threshold_aig;
		if (fund_val_e_bef_cv > tbl_threshold * gmwb_inf_e_bef_cv)
		{
				markov_matrix_tbl_id = PRIMARY;
		}
		else
		{
			markov_matrix_tbl_id = SECONDARY;
		}

		new_util_level_cv = 
						get_gmwb_wdl_random_utilization_level_aig(util_level_cv, markov_matrix_tbl_id, unif_rv_cv);
	}

	return new_util_level_cv;
}



#line 1 "gmwb_claim_print_debug_output_aig.FIA_LIAB.for"                                                                                   
void FIA_LIAB::gmwb_claim_print_debug_output_aig(vector< vector <xstring> > debug_output)
{
	// Get scenario number
	xstring scen_id = xstring(proj_task_loop_num);

	// Gets column output file name
	xstring output_file_path = replaceWildcards(output_location());

	// Chop string off at the last "~"
	xstring output_file_name_prefix = xstring(output_file_path(0 , output_file_path.find_first_of("~")));

	// Generate file name
	xstring file_path = output_file_name_prefix + "_" + mp_id + "_" + scen_id + xstring("_GMWB_Claim.csv");

	// Open file
	ofstream output_file_stream;
	output_file_stream.open(file_path);

	// Print header
	output_file_stream << "i, period_disc, cumm_discount, gmwb_max_annual_wdl_pct, benefit_base, period_wdl, disc_wdls" << endl;

	// Print data
	for (int row = 0; row < debug_output.size(); row++)
	{
		vector <xstring> current_row = debug_output[row];

		for (int col = 0; col < current_row.size(); col++)
		{
			if (col != current_row.size() - 1)
			{
				// Terminator is comma
				output_file_stream << current_row[col] << ", ";
			}
			else
			{
				// Terminator is endl
				output_file_stream << current_row[col] << endl;
			}	
		}
	}

	output_file_stream.close();

	return;
}



