#line 1 "gmwb_withdrl_rate_indexing_addn_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::gmwb_withdrl_rate_indexing_addn_calc_aig(int t, StrEnum::EnumValue income_phase, bool hypothetical_assessment)
{
	// 20200704 MTC - Updated to calculate addition for any t and added max ref rate logic

	double reference_rate_cv;
	
	if (gmwb_withdrl_rate_indexing_assessment_defn_aig == NO)
	{
		reference_rate_cv = gmwb_withdrl_rate_indexing_ref_rate_aig(t);
	}
	else if (gmwb_withdrl_rate_indexing_assessment_defn_aig == YES)
	{
		if (hypothetical_assessment)
		{
			reference_rate_cv = max(
									   gmwb_withdrl_rate_indexing_assessment_max_ref_rate_e_bef_aig(t),
									   gmwb_withdrl_rate_indexing_ref_rate_aig(t)
								   );
		}
		else
		{
			reference_rate_cv = gmwb_withdrl_rate_indexing_assessment_max_ref_rate_e_bef_aig(t);
		}
	}
	else
	{
		throw FatalError("Unhandled gmwb_withdrl_rate_indexing_assessment_defn_aig requested in gmwb_withdrl_rate_indexing_addn_calc_aig!");
	}

	double part_rate = gmwb_withdrl_rate_indexing_part_rate_calc_aig(t, income_phase);  // 20200704 MTC - Made participation rate dynamic
	double cap_rate  = gmwb_withdrl_rate_indexing_cap_rate_aig;

	double reference_rate_at_issue_cv = gmwb_withdrl_rate_indexing_policy_issue_ref_rate_aig(t);

	double wdl_rate_addn = min(cap_rate, part_rate * max(0, reference_rate_cv - reference_rate_at_issue_cv));

	return wdl_rate_addn;
}



