#line 1 "irr_calc.FIA_LIAB.for"                                                                                   
double FIA_LIAB::irr_calc(int t, const xstring &roi_type)
{
int period = 0;
int adj_begin = 1;
int ind_chk = 0;
double adj_pv_prof_1 = 0;
double adj_pv_prof_2 = 0;
double prof = 0;
double pv_prof = 0;
double pv_factor = 0;
double yld_factor = 0;
double roi_guess = 0.1;
double low_pv = 0;
double high_pv = 0;
double tgt_cap = 0.0;
double* bk_prof_aft_tax_for_pv = NULL;
double* bk_prof_aft_tax_irr = NULL;
double* distrib_earnings = NULL;
double* distrib_earnings_irr  = NULL;
double* bef_tax_yld = NULL;
double* port_yld_aft_tax_irr = NULL;//WTW - Gen2 - conflicting name with model class column
double min_rate_mthly = -.318708; // Annual rate = -.99
double max_rate_mthly = .042086; // Annual rate = .64

bk_prof_aft_tax_for_pv = new double[final_period + 1];
bk_prof_aft_tax_irr = new double[final_period + 1];
distrib_earnings = new double[final_period + 1];
distrib_earnings_irr  = new double[final_period + 1];
bef_tax_yld = new double[final_period + 1];
port_yld_aft_tax_irr = new double[final_period + 1];//WTW - Gen2 - conflicting name with model class column

// force call disc_rate_port_yld_defn_val
disc_rate_port_yld_defn_val(start_period + 1);

// initialize arrays
for (int i = 0; i < final_period; i++)
	{
	bk_prof_aft_tax_for_pv[i] = 0.0;
	bk_prof_aft_tax_irr[i] = 0.0;
	distrib_earnings[i] = 0.0;
	distrib_earnings_irr [i] = 0.0;
	bef_tax_yld[i] = 0.0;
	port_yld_aft_tax_irr[i] = 0.0;//WTW - Gen2 - conflicting name with model class column
	}

// drive the calculations forward
tgt_cap = this->tgt_cap(0);

for (int tt = 1; tt <= final_period; tt++)
	{
	bk_prof_aft_tax_for_pv[tt] = this->bk_prof_aft_tax_for_pv(tt);
	bk_prof_aft_tax_irr[tt] = this->bk_prof_aft_tax_irr(tt);
	distrib_earnings[tt] = this->distrib_earnings(tt);
	distrib_earnings_irr [tt] = this->distrib_earnings_irr (tt);
	bef_tax_yld[tt] = this->bef_tax_yld(tt);
	port_yld_aft_tax_irr[tt] = this->port_yld_aft_tax(tt);//WTW - Gen2 - conflicting name with model class column

	if (roi_type == "Without Target Capital")
		{
		if (bk_prof_aft_tax_irr[tt] >= 0.0
		    && tt < last_proj_period)	
			adj_begin++;
		}
	else
		{	
		if (distrib_earnings_irr [tt] >= 0.0
		    && tt < last_proj_period)	
			adj_begin++;
		}
	}

if (adj_begin == final_period)
	return 0.0;

double low_roi = min_rate_mthly;
double high_roi = min_rate_mthly;
double last_roi_guess = min_rate_mthly;

for (period = final_period; period > 0; period--)
	{
	if (roi_type == "Without Target Capital")
		{
		if (period > adj_begin)
			prof = bk_prof_aft_tax_for_pv[period];
	
		else if (period == adj_begin)
			prof = bk_prof_aft_tax_irr[period]; 
	
		else
			prof = 0.0;
		}
	else 
		{
		if (period > adj_begin)
			prof = distrib_earnings[period];
	
		else if (period == adj_begin)
			prof = distrib_earnings_irr [period]; 
	
		else
			prof = 0.0;
		}

	if (adj_pv_prof_1 + prof >= 0
		&& disc_rate_port_yld_defn == BEFORE_TAX)
		yld_factor
		= 1.0 / pow(1.0 + max(bef_tax_yld[period], -.99),
		           (1.0 / 12.0));

	else
		yld_factor
		= 1.0 / pow(1.0 + max(port_yld_aft_tax_irr[period], -.99),//WTW - Gen2 - conflicting name with model class column
		           (1.0 / 12.0));

	if (adj_pv_prof_2 + prof >= 0)
		pv_factor 
		= 1.0 / (1.0 + roi_guess);

	else
		pv_factor
		= 1.0 / pow(1.0 + max(port_yld_aft_tax_irr[period], -.99),//WTW - Gen2 - conflicting name with model class column
		           (1.0 / 12.0));
		
	adj_pv_prof_1
	= (adj_pv_prof_1 + prof)
	  * yld_factor;			

	adj_pv_prof_2
	= (adj_pv_prof_2 + prof)
	  * pv_factor;
	  
	if (adj_pv_prof_2 > 0)
		ind_chk = 1;
		  
	} 
			
adj_pv_prof_2
-= max(tgt_cap, 0.0);			

if (adj_pv_prof_2 >= 0)
	{
	low_roi = roi_guess;
	low_pv = adj_pv_prof_2;
	}
else
	{			
	high_roi = roi_guess;
	high_pv = adj_pv_prof_2;
	}

last_roi_guess = roi_guess;
		
if (!ind_chk)
	roi_guess = last_roi_guess;

else if (ind_chk && low_roi > min_rate_mthly
		 && high_roi > min_rate_mthly)
	roi_guess = max(min_rate_mthly,
	                high_roi 
	                - high_pv
	                  * (high_roi - low_roi)
	                  / (high_pv - low_pv)); 				

else if (ind_chk && low_roi == min_rate_mthly)
	roi_guess = (low_roi + high_roi) / 2.0;

else if (ind_chk && high_roi == min_rate_mthly)
	roi_guess = low_roi + max(max_rate_mthly, low_roi);			
						
while (fabs(roi_guess - last_roi_guess) > .00001
		&& (low_pv - high_pv) > .0000001)
	{		
	pv_prof = 0.0;

	for (period = final_period; period >= adj_begin; period--)
		{
		if (roi_type == "Without Target Capital")
			{
			if (period > adj_begin)
				prof = bk_prof_aft_tax_for_pv[period];
		
			else if (period == adj_begin)
				prof = bk_prof_aft_tax_irr[period]; 
		
			else
				prof = 0.0;
			}
		else 
			{
			if (period > adj_begin)
				prof = distrib_earnings[period];
		
			else if (period == adj_begin)
				prof = distrib_earnings_irr [period]; 
		
			else
				prof = 0.0;
			}

		if (pv_prof + prof >= 0)
			pv_factor
			= 1.0 / (1.0 + roi_guess);

		else
			pv_factor
			= 1.0 / pow(1.0 + max(port_yld_aft_tax_irr[period], -.99), (1.0 / 12.0));//WTW - Gen2 - conflicting name with model class column			

		pv_prof
		= (pv_prof + prof) * pv_factor;		

		} 
	pv_prof
	-= max(tgt_cap, 0.0);

	if (1000000 * pv_prof > 0)
		{
		low_roi = roi_guess;
		low_pv = pv_prof;
		}
	else
		{	
		high_roi = roi_guess;
		high_pv = pv_prof;
		}

	last_roi_guess = roi_guess;
	
	if (low_roi > min_rate_mthly
	    && high_roi > min_rate_mthly
		&& (pow(1.0 + high_roi, 12.0) - pow(1.0 + low_roi, 12.0) < (0.1)))	
		roi_guess = max(min_rate_mthly,
		                high_roi 
		                - high_pv
		                  * (high_roi - low_roi)
		                  / (high_pv - low_pv)); 				

	else if (low_roi == min_rate_mthly
	         || (pow(1.0 + high_roi, 12.0) - pow(1.0 + low_roi, 12.0) > (0.1)))
		roi_guess = (low_roi + high_roi) / 2.0;

	else if (high_roi == min_rate_mthly)
		roi_guess = low_roi + max(max_rate_mthly, low_roi);			
	}

// delete arrays
delete [] bk_prof_aft_tax_for_pv;
delete [] bk_prof_aft_tax_irr;
delete [] distrib_earnings;
delete [] distrib_earnings_irr ;
delete [] bef_tax_yld;
delete [] port_yld_aft_tax_irr;//WTW - Gen2 - conflicting name with model class column

bk_prof_aft_tax_for_pv = NULL;
bk_prof_aft_tax_irr = NULL;
distrib_earnings = NULL;
distrib_earnings_irr  = NULL;
bef_tax_yld = NULL;
port_yld_aft_tax_irr = NULL;//WTW - Gen2 - conflicting name with model class column

if (ind_chk)
	return min(max(pow(1.0 + roi_guess, 12.0) - 1.0, -.9999), 99.9999);

return -.9999;
}



#line 1 "issue_age_calc_aig.FIA_LIAB.for"                                                                                   
int FIA_LIAB::issue_age_calc_aig(StrEnum::EnumValue gender_cv)		
{		
	int return_value;	
		
	if (gender_cv == JOINT) {	
		return_value = min(issue_age_male_aig, issue_age_female_aig);
	} else if (gender_cv == MALE) {	
		return_value = issue_age_male_aig;
	} else if (gender_cv == FEMALE) {	
		return_value = issue_age_female_aig;
	} else if (gender_cv == BLENDED) {	
		return_value = issue_age_male_aig;
	} else {	
		throw FatalError("Unhandled gender encountered during issue age set!");
	}	
		
	return return_value;	
}		




#line 1 "lapse_dyn_rate_add_isl_2019_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::lapse_dyn_rate_add_isl_2019_calc_aig(
	int t, double cash_val_e_bef_cv, double gmwb_inf_e_bef_cv, double glb_apv_cv, double glb_apv_at_issue_cv, double mva_pct )
{ // 20200428 DTL
	// 20190705 MTC - Added external function for ISL 2019
	// 20190812 MTC - Updated to perform at-issue ITM valuation every t, using at-issue interest rates
	if (gmwb_inf_e_bef_cv < SMALL_DOUBLE || glb_apv_at_issue_cv < SMALL_DOUBLE)
	{
		// If `gmwb_inf_e_bef` there isn't a GLB benefit for comparison
		// If `glb_apv_at_issue` is zero, it isn't clear how we would do a comparison
		return 0.0;
	}

	double additional_lapse = 0.0;
	const double SMALL_SURR_CHG_PCT = 0.000001; // 20190903 MTC - Surrender charge rate comparison
	pol_yr_lookup_gen2 = pol_yr(t);//WTW - Gen2 - surr_chg_pct cannot use time based lookup in an external formula
	double surr_chg_pct_local = surr_chg_pct;//WTW - Gen2 - Mutating Lookup Term used in expression
	
	if ( gmwb_ind && ( surr_chg_pct_local + SMALL_SURR_CHG_PCT < isl_2019_surr_chg_pct_threshold_aig ) ) // 20190903 MTC - Surrender charge rate comparison//WTW - Gen2 - Mutating Lookup Term used in expression
	{
		// Initialize
		const double INFTY = 999999999.0;

		double gmwb_itm_rate_denominator_at_issue = gmwb_inf_e_bef_cv;
		double isl_2019_pv_gmwb_benefit_itm_at_issue_cv_aig;
		if (gmwb_itm_rate_denominator_at_issue > SMALL_DOUBLE)
		{
			isl_2019_pv_gmwb_benefit_itm_at_issue_cv_aig = glb_apv_at_issue_cv / gmwb_itm_rate_denominator_at_issue;
		}
		else
		{
			isl_2019_pv_gmwb_benefit_itm_at_issue_cv_aig = INFTY;
		}
		
		// Calculate GMWB ITM rate now
		double gmwb_itm_rate_denominator = min(cash_val_e_bef_cv, gmwb_inf_e_bef_cv);

		double isl_2019_pv_gmwb_benefit_itm_cv_aig;
		if (gmwb_itm_rate_denominator > SMALL_DOUBLE)
		{
			isl_2019_pv_gmwb_benefit_itm_cv_aig = glb_apv_cv / gmwb_itm_rate_denominator;
		}
		else
		{
			isl_2019_pv_gmwb_benefit_itm_cv_aig = INFTY;
		}

		// Calculate tanh parameter x
		double x = (isl_2019_alpha_aig - (isl_2019_pv_gmwb_benefit_itm_cv_aig / isl_2019_pv_gmwb_benefit_itm_at_issue_cv_aig)) / // 20190809 MTC - ISL diagnostic printout
					isl_2019_beta_aig;

		// Calculate tanh(x)
		double tanh_x = tanh(x);

		// Calculate additional lapse
		additional_lapse = isl_2019_coefficient_aig * (1.0 + tanh_x) / isl_2019_divisor_aig - mva_pct;  // DTL 20200707
	}

	return additional_lapse;
}



#line 1 "lapse_rate_dyn.FIA_LIAB.for"                                                                                   
double FIA_LIAB::lapse_rate_dyn(int t) 
{
double threshold = 0.0;
double sc_ratio = 0.0;
double base = 0.0;
double exponent = 0.0;
double prev_cred = 0.0;
double non_equity_component = 0.0;
double equity_component = 0.0;

/**********************************
Fixed Component
**********************************/
int pol_yr = xint(this->pol_yr(t));
double mkt_rate = get_comp_rate(asset_yld_comp_rate_id, t);

threshold = lapse_dyn_thresh;

if (fabs(fund_val_e_bef(t)) <= model_point_amount_threshold)
	sc_ratio = 0.0;
else
	sc_ratio = 1.0 - cash_val_bef(t) / fund_val_e_bef(t);

base =  mkt_rate - opt_budget(t) - threshold;

if (base <= 0.0)
	return 0.0;

exponent = lapse_dyn_exp;

non_equity_component = (lapse_dyn_mult)
						* pow(base, exponent) 
						* (1.0- sc_ratio * lapse_dyn_scmult);

/**********************************
Equity Component
**********************************/
if (t - pol_mth(t) - commencement_period <= 0)
	equity_component = 0.0;
else
	{	
	prev_cred = credited_int(t - pol_mth(t)) / fund_val_b(t - pol_mth(t));
				
	equity_component = lapse_dyn_mult
						* (mkt_rate - prev_cred);
	}
	
return (non_equity_component + equity_component) / 100.0;	
}



#line 1 "mort_improve_mult_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::mort_improve_mult_aig(int att_age, StrEnum::EnumValue gender_local, int t) // 20180910 MTC - Ported code from VA model
{
	/*!Mortality Improvement Multiple
	   ==============================
	   @author Susan Cheung
	   @date 20180205

	   This column function calculates the mortality improvement multiple which follows "Q3 2016 RIS VA Mortality Assumption Recommendation" by Pricing Oversight page 3.
	   
	   \f[
	   Q_{x}(mort\_improve\_base\_date + n) =  Q_{x}(mort\_improve\_base\_date) * (1-G2_{x}) ^{n}
	   \f]
	   
	   Where:

	   -# \f$Q_{x}(mort\_improve\_base\_date)\f$ is the applicable recommended base mortality rate.
	   -# \f$G2_{x}\f$ is the mortality improvement factor from the Scale G2 improvement table for age x.
	   -# \f$n\f$ is the amount of time passed since `mort_improve_base_date_aig`, in years and partial years if applicable. \f$n\f$ is calculated in time_between_dates_calc_aig().

	   @param[in] t The current month.
	  	  
	   Related Inputs:
	   ---------------
	   -# **UI** `mort_improve_base_date_aig` - the mortality improvement base date, from the input variable.
	   -# **MP** `issue_date_mp` - the date the policy is issued, from model point.
	   -# **UI** `mort_improve_pct` - the mortality improvement percentage look up from the assumption table.
	  
	   @return cumulative mortality improvement.
	*/

	// 20180504 MTC
	/*if (t <= commencement_period || t > maturity_period)
		return NO_AVG;*/

	double n;
	double cumul_mort_improve;
	xstring start_date;
	xstring end_date;

	//Calculation of n = the amount of time passed since the mort_improve_base_date_aig
	start_date = mort_improve_base_date_aig;
	end_date = issue_date_mp;
 
	n = time_between_dates_calc_aig(start_date, end_date) + (elapsed_mths + t) / 12.;

	// Mortality improvement lookup keys are mort_attained_age and cal_yr_table_index
	mort_attained_age = att_age;   //WTW - Gen2 - Mutating Lookup Terms
	mort_gender = gender_local; //WTW - Gen2 - Mutating Lookup Terms
	cumul_mort_improve = pow ((1 - mort_improve_pct), n);

	return cumul_mort_improve;
}



#line 1 "pv_benefit_projection_mort_rates_calc_aig.FIA_LIAB.for"                                                                                   
void FIA_LIAB::pv_benefit_projection_mort_rates_calc_aig(const int& projection_month, const int& current_month, double& lxy, double& lx, double& ly, double& lxy_bar, double& dx, double& dy, double& dxy_bar)
{
	/*****************************************************************************
		* d      = DEATH CLAIMS RATE
		* x      = MALE ONLY STATUS
		* y      = FEMALE ONLY STATUS
		* xy     = JOINT STATUS
		* xy_bar = LAST SURVIVOR STATUS
	****************************************************************************/

	// 20191015 MTC - Refactored to handle death claim rates for 3 streams
	// 20191203 MTC - Refactored to remove unused param from method signature
	// 20200303 MTC - Confinement rider

	double qx, px, qy, py;

	double lxy_bar_bef = lxy_bar;  // 20191203 MTC - Bugfix to do last-to-die deaths instead of first-to-die, which assumes 100% spousal continuation election rate

	if ( current_month == projection_month )
	{
		qx = 0.0;
		px = 1.0;
		qy = 0.0;
		py = 1.0;
	}
	else
	{
		// 20200303 MTC - Confinement rider
		if (enhanced_income_flag_aig)
		{
			int policy_year									= xint(pol_yr(current_month));

			// Male mortality
			StrEnum::EnumValue confinement_status_male		= enhanced_income_confinement_state_get_enum_aig(xint(enhanced_income_confinement_state_male_b_aig(projection_month)));

			if (confinement_status_male == CONFINED)
			{
				int confinement_mth_male_oloop				= xint(enhanced_income_confinement_mth_male_e_aig(projection_month));
				int confinement_mth_male					= confinement_mth_male_oloop + current_month - projection_month;
				int confinement_age_male					= xint(attained_age_male_aig(projection_month - confinement_mth_male_oloop + 1));

				qx											= dth_claim_rate_mthly_calc(current_month, policy_year, CONFINEMENT, MALE, CONFINED, confinement_age_male, confinement_mth_male);
			}
			else if (confinement_status_male == NONCONFINED)
			{
				qx											= dth_claim_rate_mthly_male_confinement_non_confined_aig(current_month);
			}
			else
			{
				throw FatalError("Unhandled confinement_status_male requested in pv_benefit_projection_mort_rates_calc_aig!");
			}

			// Female mortality
			StrEnum::EnumValue confinement_status_female	= enhanced_income_confinement_state_get_enum_aig(xint(enhanced_income_confinement_state_female_b_aig(projection_month)));

			if (confinement_status_female == CONFINED)
			{
				int confinement_mth_female_oloop			= xint(enhanced_income_confinement_mth_female_e_aig(projection_month));
				int confinement_mth_female					= confinement_mth_female_oloop + current_month - projection_month;
				int confinement_age_female					= xint(attained_age_female_aig(projection_month - confinement_mth_female_oloop + 1));

				qy											= dth_claim_rate_mthly_calc(current_month, policy_year, CONFINEMENT, FEMALE, CONFINED, confinement_age_female, confinement_mth_female);
			}
			else if (confinement_status_female == NONCONFINED)
			{
				qy											= dth_claim_rate_mthly_female_confinement_non_confined_aig(current_month);
			}
			else
			{
				throw FatalError("Unhandled confinement_status_female requested in pv_benefit_projection_mort_rates_calc_aig!");
			}
		}
		else
		{
			qx = dth_claim_rate_mthly_male_experience_aig(current_month);  // 20200303 MTC - Refactored to remove duplicate death claim rate calc
			qy = dth_claim_rate_mthly_female_experience_aig(current_month);  // 20200303 MTC - Refactored to remove duplicate death claim rate calc
		}

		px = 1.0 - qx;
		py = 1.0 - qy;
		// 20200303 MTC END
	}

	// 20191015 MTC - Refactored to handle death claim rates for 3 streams
	dx		= lx * qx;
	dy		= ly * qy;
	// 20191015 MTC END

	lxy     *= px * py;
	lx      *= px;
	ly      *= py;
	lxy_bar  = lx + ly - lxy;

	dxy_bar	 = lxy_bar_bef - lxy_bar;  // 20191203 MTC - Bugfix to do last-to-die deaths instead of first-to-die, which assumes 100% spousal continuation election rate
}



#line 1 "pv_gmwb_benefit_disc_factor_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::pv_gmwb_benefit_disc_factor_calc_aig(int t, int i, StrEnum::EnumValue discount_rate_override) //WTW - Gen2 - =NONE
// 20190728 MTC - ITM iLoop refactor
{
	// Process discount factor methodology override
	StrEnum::EnumValue discount_rate_methodology;

	if (discount_rate_override == NONE)
	{
		discount_rate_methodology = lapse_dyn_rate_defn_aig;
	}
	else
	{
		discount_rate_methodology = discount_rate_override;
	}

	// Get discount factor
	double disc_factor;

	if (discount_rate_methodology == USE_FUTURE_FORWARD_RATES)
	{
		disc_factor = pv_gmwb_benefit_disc_factor_future_forward_calc_aig(t, i);
	}
	else if (discount_rate_methodology == USE_CURRENT_SPOT_RATES)
	{
		disc_factor = pv_gmwb_benefit_disc_factor_curr_spot_calc_aig(t, i);
	}
	else if (discount_rate_methodology == BOOTSTRAP_CURRENT_PERIOD_FORWARD_RATES)
	{
		disc_factor = pv_gmwb_benefit_disc_factor_curr_forward_calc_aig(t, i);
	}
	// 20200428 DTL
	else if (discount_rate_methodology == USE_TEN_YEAR_SWAP_RATE)
	{
		disc_factor = pv_gmwb_benefit_disc_factor_ten_year_swap_calc_aig(t, i);
	}
	else if (discount_rate_methodology == USE_TEN_YEAR_SWAP_RATE_AT_ISSUE)
	{
		disc_factor = pv_gmwb_benefit_disc_factor_ten_year_swap_at_issue_calc_aig(t, i); // 20190812 MTC - Added function to perform at-issue ITM valuation every t, using at-issue interest rates
	}
	// 20200428 DTL
	else
	{
		throw FatalError("Unhandled lapse_dyn_rate_defn_aig requested in pv_gmwb_benefit_disc_factor_calc_aig!");
	}

	return disc_factor;
}



#line 1 "pv_gmwb_benefit_disc_factor_curr_forward_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::pv_gmwb_benefit_disc_factor_curr_forward_calc_aig(int t, int i)
// 20190728 MTC - ITM iLoop refactor
{
	// Initialize
	const int TEN_YEARS = 120;
	static int flat_yld_curve_period;
	static cubic_spline_params_aig swap_curve_cubic_spline_params;
	static vector<double> swap_curve;

	// Calculate forward rate for this t if not already calculated
	if (i == t)
	{
		// Calculate max tenor
		int max_tenor = 0;

		if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
			max_tenor = *max_element(begin(fia_rates->swap_curve_tenors_aig), end(rates->swap_curve_tenors_aig));
		else
			max_tenor = *max_element(begin(rates->swap_curve_tenors_aig), end(rates->swap_curve_tenors_aig));
		
		if (max_tenor <= TEN_YEARS)
		{
			throw FatalError("10-year forward rate elected for GMWB ITM calculation, but max tenor is less than 10 years!");
		}

		// Calculate flat curve period
		flat_yld_curve_period = max_tenor - TEN_YEARS;

		// Initialize cubic spline params
		if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
			swap_curve = fia_rates->swap_curve_init_cubic_spline_params_aig(t, swap_curve_cubic_spline_params);
		else
			swap_curve = rates->swap_curve_init_cubic_spline_params_aig(t, swap_curve_cubic_spline_params);
	}

	// Calculate current and 10 year periods
	int current_spot_rate_period = min(i - t, flat_yld_curve_period);
	int ten_year_spot_rate_period = current_spot_rate_period + TEN_YEARS;

	// Get rates from swap curve
	double current_spot_rate = 0.0;
	double ten_year_spot_rate = 0.0;

	if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
		{
		current_spot_rate = fia_rates->cubic_spline_interpolation_aig(current_spot_rate_period, fia_rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params);
		ten_year_spot_rate = fia_rates->cubic_spline_interpolation_aig(ten_year_spot_rate_period, fia_rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params);
		}
	else
		{
		current_spot_rate = rates->cubic_spline_interpolation_aig(current_spot_rate_period, rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params);
		ten_year_spot_rate = rates->cubic_spline_interpolation_aig(ten_year_spot_rate_period, rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params);
		}

	// Convert rates to continuous
	current_spot_rate = log(1.0 + current_spot_rate);
	ten_year_spot_rate = log(1.0 + ten_year_spot_rate);

	// Calculate forward rate
	double forward_rate = (ten_year_spot_rate * ten_year_spot_rate_period - current_spot_rate * current_spot_rate_period) /
						  (ten_year_spot_rate_period - current_spot_rate_period);

	// Calculate discount factor for this i
	double disc_factor = exp(forward_rate * (t - i) / 12.0);

	return disc_factor;
}



#line 1 "pv_gmwb_benefit_disc_factor_curr_spot_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::pv_gmwb_benefit_disc_factor_curr_spot_calc_aig(int t, int i)
// 20190728 MTC - ITM iLoop refactor
{
	// Initialize statics for this t
	static cubic_spline_params_aig swap_curve_cubic_spline_params;
	static vector<double> swap_curve;

	// Initialize swap curve for this t if not already intialized
	if (i == t)
	{
		if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
			swap_curve = fia_rates->swap_curve_init_cubic_spline_params_aig(t, swap_curve_cubic_spline_params);
		else
			swap_curve = rates->swap_curve_init_cubic_spline_params_aig(t, swap_curve_cubic_spline_params);
	}

	// Get the continuous spot rate for this i
	int current_spot_rate_period = i - t;

	double spot_rate = 0.0;

	if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
		spot_rate = fia_rates->cubic_spline_interpolation_aig(current_spot_rate_period, fia_rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params);
	else
		spot_rate = rates->cubic_spline_interpolation_aig(current_spot_rate_period, rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params);
	
	spot_rate = log(1.0 + spot_rate);

	// Calculate discount factor for this i
	double disc_factor = exp(spot_rate * (t - i) / 12.0);

	//log_strm << mp_id << "," << t << "," << disc_factor << "\n";

	return disc_factor;
}



