#line 1 "pv_gmwb_benefit_disc_factor_ten_year_swap_at_issue_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::pv_gmwb_benefit_disc_factor_ten_year_swap_at_issue_calc_aig(int t, int i)
{ // 20200428 DTL

	// Initialize
	static double constant_disc_rate;
	static bool run_once = false;

	// Calculate constant discount rate at issue
	if (!run_once)
	{
		cubic_spline_params_aig swap_curve_cubic_spline_params;
		vector<double> swap_curve;
		
		if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
			swap_curve = fia_rates->swap_curve_init_cubic_spline_params_aig(commencement_period, swap_curve_cubic_spline_params);
		else
			swap_curve = rates->swap_curve_init_cubic_spline_params_aig(commencement_period, swap_curve_cubic_spline_params);

		// Perform cubic interpolation
		const int TEN_YEARS = 120;
		double spot_rate = 0.0;
		
		if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
			spot_rate = fia_rates->cubic_spline_interpolation_aig(TEN_YEARS, fia_rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params); // 20200701 DTL
		else
			spot_rate = rates->cubic_spline_interpolation_aig(TEN_YEARS, rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params); // 20200701 DTL

		// Convert to continuous rate
		constant_disc_rate = log(1.0 + spot_rate);

		// No need to run this again
		run_once = true;
	}

	// Calculate discount factor for this i
	double disc_factor = exp(constant_disc_rate * (t - i) / 12.0);

	return disc_factor;
}



