#line 1 "pv_gmwb_benefit_mort_rate_calc_spousal_2019_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::pv_gmwb_benefit_mort_rate_calc_spousal_2019_aig(int start_period, int i, int max_period, double spousal_continuation_election_rate)
{
	// 20190913 MTC - Added external function for Spousal 2019 inner loop mortality

	if (start_period > max_period || i > max_period || i < start_period)
	{
		throw FatalError("fia_liab->pv_gmwb_benefit_surv_rate_calc_spousal_2019_aig called with invalid start_period, i, or max_life!");
	}

	static map<int, double> mort_rates;
	double mort_rate;
	
	// Construct inner loop survivorship rate table
	if (i == start_period)
	{
		// Initialize
		mort_rates.erase(mort_rates.begin(), mort_rates.end());

		double policies_joint_bom, policies_joint_eom;
		double policies_male_bom, policies_male_eom;
		double policies_female_bom, policies_female_eom;
		double policies_last_survivor_bom, policies_last_survivor_eom;

		// Set initial policy counts by grabbing the outer loop state
		policies_joint_bom = policies_joint_experience_aig(start_period - 1);
		policies_male_bom = policies_male_experience_aig(start_period - 1);
		policies_female_bom = policies_female_experience_aig(start_period - 1);
		policies_last_survivor_bom = policies_last_survivor_experience_aig(start_period - 1);

		for (int j = i; j <= max_period; j++)
		{
			// Calculate EOM policy counts
			policies_joint_eom = spousal_2019_proj_policies_joint_aig(j, policies_joint_bom);
			policies_male_eom = spousal_2019_proj_policies_male_aig(j, policies_joint_bom, policies_male_bom, spousal_continuation_election_rate);
			policies_female_eom = spousal_2019_proj_policies_female_aig(j, policies_joint_bom, policies_female_bom, spousal_continuation_election_rate);
			policies_last_survivor_eom = spousal_2019_proj_policies_last_survivor_aig(policies_joint_eom, policies_male_eom, policies_female_eom);

			// Calculate period survivorship
			double mort_rate = spousal_2019_dth_claim_rate_calc_aig(policies_last_survivor_bom, policies_last_survivor_eom);
			mort_rates[j] = mort_rate;

			// Rollforward
			policies_joint_bom = policies_joint_eom;
			policies_male_bom = policies_male_eom;
			policies_female_bom = policies_female_eom;
			policies_last_survivor_bom = policies_last_survivor_eom;
		}
	}

	// Retrieve rate
	if (mort_rates.find(i) != mort_rates.end())
	{
		mort_rate = mort_rates[i];
	}
	else
	{
		xstring error_msg = "Requested Spousal Continuation 2019 mortality rate not available at time " + xstring(i) + "! " + 
							"Was fia_liab->pv_gmwb_benefit_mort_rate_calc_spousal_2019_aig initialized properly?";
		throw FatalError(error_msg);
	}

	return mort_rate;
}



#line 1 "pv_sfc_benefit_forward_rate_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::pv_sfc_benefit_forward_rate_calc_aig(int t, int i)
{
	// 20220701 STW: imported from bootstrap method in gmwb and made customed edit

	// Initialize
	const int ONE_YEAR = 12;
	static int flat_yld_curve_period;
	static cubic_spline_params_aig swap_curve_cubic_spline_params;
	static vector<double> swap_curve;

	// Calculate forward rate 
	if (i == t)
	{
		// Calculate max tenor
		int max_tenor;
		if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
			max_tenor = *max_element(begin(fia_rates->swap_curve_tenors_aig), end(fia_rates->swap_curve_tenors_aig));
		else 
			max_tenor = *max_element(begin(rates->swap_curve_tenors_aig), end(rates->swap_curve_tenors_aig));

		if (max_tenor <= ONE_YEAR)
		{
			throw FatalError("1-year forward rate elected for GMWB ITM calculation, but max tenor is less than 1 year!");
		}

		// Calculate flat curve period
		flat_yld_curve_period = max_tenor - ONE_YEAR;

		// Initialize cubic spline params
		if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
			swap_curve = fia_rates->swap_curve_init_cubic_spline_params_aig(t, swap_curve_cubic_spline_params);
		else 
			swap_curve = fia->rates->swap_curve_init_cubic_spline_params_aig(t, swap_curve_cubic_spline_params);

	}

	// Calculate current and 1 year periods
	int current_spot_rate_period = min(i - t, flat_yld_curve_period);
	int one_year_spot_rate_period = current_spot_rate_period + ONE_YEAR;

	// Get rates from swap curve
	double current_spot_rate;
	double one_year_spot_rate;
	if (gen2_defn == YES)//WTW - Gen2 - cannot define 'rates' pointer
	{
		current_spot_rate = fia_rates->cubic_spline_interpolation_aig(current_spot_rate_period, fia_rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params);
		one_year_spot_rate = fia_rates->cubic_spline_interpolation_aig(one_year_spot_rate_period, fia_rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params);
	}
	else 
	{
		current_spot_rate = rates->cubic_spline_interpolation_aig(current_spot_rate_period, rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params);
		one_year_spot_rate = rates->cubic_spline_interpolation_aig(one_year_spot_rate_period, rates->swap_curve_tenors_aig, swap_curve, swap_curve_cubic_spline_params);
	}

	// Convert rates to continuous
	current_spot_rate = log(1.0 + current_spot_rate);
	one_year_spot_rate = log(1.0 + one_year_spot_rate);

	// Calculate forward rate
	double forward_rate = (one_year_spot_rate * one_year_spot_rate_period - current_spot_rate * current_spot_rate_period) /
						  (one_year_spot_rate_period - current_spot_rate_period);

	// Calculate forward rate for this i
	double one_year_forward_rate = exp(forward_rate / 12.0) - 1;

	return one_year_forward_rate;
}



#line 1 "pv_sfc_benefit_itm_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::pv_sfc_benefit_itm_calc_aig(int t)
{
//20220701 STW: new function for sfc inner loop calculation
// set up local variables
double surv_period = 1.0;
double cumm_surv = 1.0;								
int actual_time = t + elapsed_mths;
double one_year_forward_rate;
double asset_annual_growth;
double asset_cumulative_growth = 1.0;
double separate_account_count=0;

double joint_cumm_surv = 1.0;	
double male_cumm_surv = 1.0;
double female_cumm_surv = 1.0;
double last_cumm_surv = 1.0;
double death_claims_male = 0.0;
double death_claims_female = 0.0;
double death_claims_last_cumm = 0.0;

// convert strategy fee to continuous
double strategy_fee_rate = weighted_eprs_cost_aig(t);
strategy_fee_rate = 1 - pow(1 - strategy_fee_rate / 360, 360);
strategy_fee_rate = -log( 1 - strategy_fee_rate );

// inner loop to calculate future mortality and growth rates
for (int i = actual_time; i <= surr_chg_period_aig * 12; i = i + 1)		
{
	pv_benefit_projection_mort_rates_calc_aig(actual_time, i, 
		joint_cumm_surv, male_cumm_surv, female_cumm_surv, last_cumm_surv,
		death_claims_male, death_claims_female, death_claims_last_cumm);

	cumm_surv *= last_cumm_surv;

	one_year_forward_rate = pv_sfc_benefit_forward_rate_calc_aig(actual_time, i);

	asset_annual_growth = 1 + one_year_forward_rate - strategy_fee_rate / 12;

	asset_cumulative_growth *= asset_annual_growth;

}

// calculate future benefit
double fund_val_future = fund_val_e_bef(t) * asset_cumulative_growth;
					 
double sfc_payout;
double net_prem = gross_sfc_ben_aig(t);

if( fund_val_future > net_prem )
{
	sfc_payout = 0;
}
else
{
	sfc_payout = net_prem - fund_val_future;
}

double sfc_benefit_future = (fund_val_future + sfc_payout) * cumm_surv;

return sfc_benefit_future;

}



