#line 1 "set_gmwb_mib_rollup_phase_lookup_e_bef_aig.FIA_LIAB.for"                                                                                   
void FIA_LIAB::set_gmwb_mib_rollup_phase_lookup_e_bef_aig(int t)
{
	// 20190729 MTC - ArcTan 2019
	int policy_year = pol_yr(t);

	if (policy_year <= gmwb_mib_rollup_max_yrs_aig)
	{
		gmwb_mib_rollup_phase_lookup_aig = PRE_MIB_ROLLUP_SHOCK_YEAR;
	}
	else if (policy_year == gmwb_mib_rollup_max_yrs_aig + 1)
	{
		gmwb_mib_rollup_phase_lookup_aig = MIB_ROLLUP_SHOCK_YEAR;
	}
	else
	{
		gmwb_mib_rollup_phase_lookup_aig = POST_MIB_ROLLUP_SHOCK_YEAR;
	}

	return;
}



#line 1 "set_income_phase_lookup_b_bef_aig.FIA_LIAB.for"                                                                                   
void FIA_LIAB::set_income_phase_lookup_b_bef_aig(int t)
{
	int duration = max(0, t - 1);

	const int MONTHS_PER_YEAR = 12;
	income_phase_lookup_aig = NO_INCOME;

	if (duration > (preincome_exercise_yrs_aig * MONTHS_PER_YEAR))
	{
		income_phase_lookup_aig = PRE_INCOME;
	}

	if (gmwb_flag && (duration > ((gmwb_req_yrs_wait + xint(gmwb_exercise_yrs_aig(t))) * MONTHS_PER_YEAR)))
																											
	{
		income_phase_lookup_aig = GMWB_INCOME;
	}

	if (gmwb_flag && (fund_val_b_bef(t) < model_point_amount_threshold))
	{
		income_phase_lookup_aig = GMWB_CLAIM;
	}
}



#line 1 "set_income_phase_lookup_e_aig.FIA_LIAB.for"                                                                                   
void FIA_LIAB::set_income_phase_lookup_e_aig(int t)
{
	// 20181023 MTC - Refactor income phase lookup. Now there's a hierarchy.

	// Initialize as no income
	const int MONTHS_PER_YEAR = 12;
	income_phase_lookup_aig = NO_INCOME;

	// Check for pre-income phase
	if (t > (preincome_exercise_yrs_aig * MONTHS_PER_YEAR)) // Period withdrawal has happened
	{
		income_phase_lookup_aig = PRE_INCOME;
	}

	// Check for income phase
	if (gmwb_flag && (t > ((gmwb_req_yrs_wait + xint(gmwb_exercise_yrs_aig(t))) * MONTHS_PER_YEAR))) // Period withdrawal has happened
																									 // 20200303 MTC - Confinement rider, dynamic exercise
	{
		income_phase_lookup_aig = GMWB_INCOME;
	}

	// Check for claim phase
	if (gmwb_flag && (fund_val_e_bef(t) < model_point_amount_threshold))
	{
		income_phase_lookup_aig = GMWB_CLAIM;
	}
}



