#line 1 "spousal_2019_dth_claim_rate_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::spousal_2019_dth_claim_rate_calc_aig(double policies_last_to_die_bom, double policies_last_to_die_eom)
{
	// 20190913 MTC - Added external function for Spousal 2019
	double mort_rate;

	if (policies_last_to_die_bom > SMALL_DOUBLE)
	{
		mort_rate = 1.0 - ( policies_last_to_die_eom / policies_last_to_die_bom );
	}
	else
	{
		mort_rate = 1.0;
	}

	return mort_rate;
}



#line 1 "spousal_2019_proj_policies_female_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::spousal_2019_proj_policies_female_aig(int t, double policies_joint_cv, double policies_female_cv, double spousal_continuation_election_rate_cv)
{
	// 20190913 MTC - Added external function for Spousal 2019
	double policies_female;

	if (gender_mp == FEMALE || gender_mp == JOINT)
	{
		double dth_claim_rate_mthly_male = dth_claim_rate_mthly_male_experience_aig(t);						
		double dth_claim_rate_mthly_female = dth_claim_rate_mthly_female_experience_aig(t);				
				
		policies_female = policies_joint_cv * dth_claim_rate_mthly_male * (1.0 - dth_claim_rate_mthly_female) * spousal_continuation_election_rate_cv
						  + policies_female_cv * (1.0 - dth_claim_rate_mthly_female);
	}
	else if (gender_mp == MALE)
	{
		policies_female = 0.0;
	}
	else
	{
		throw FatalError("Unhandled gender requested in fia_liab->spousal_2019_proj_policies_female_aig!");
	}			

	return policies_female;
}



#line 1 "spousal_2019_proj_policies_joint_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::spousal_2019_proj_policies_joint_aig(int t, double policies_joint_cv)
{
	// 20190913 MTC - Added external function for Spousal 2019
	double dth_claim_rate_mthly_male = dth_claim_rate_mthly_male_experience_aig(t);						
	double dth_claim_rate_mthly_female = dth_claim_rate_mthly_female_experience_aig(t);			

	double policies_joint = policies_joint_cv * (1.0 - dth_claim_rate_mthly_male) * (1.0 - dth_claim_rate_mthly_female);

	return policies_joint;
}



