#line 1 "spousal_2019_proj_policies_male_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::spousal_2019_proj_policies_male_aig(int t, double policies_joint_cv, double policies_male_cv, double spousal_continuation_election_rate_cv)
{
	// 20190913 MTC - Added external function for new Spousal 2019
	double policies_male;

	if (gender_mp == MALE || gender_mp == JOINT)
	{
		double dth_claim_rate_mthly_male = dth_claim_rate_mthly_male_experience_aig(t);						
		double dth_claim_rate_mthly_female = dth_claim_rate_mthly_female_experience_aig(t);				
				
		policies_male = policies_joint_cv * dth_claim_rate_mthly_female * (1.0 - dth_claim_rate_mthly_male) * spousal_continuation_election_rate_cv
						+ policies_male_cv * (1.0 - dth_claim_rate_mthly_male);
	}
	else if (gender_mp == FEMALE)
	{
		policies_male = 0.0;
	}
	else
	{
		throw FatalError("Unhandled gender requested in fia_liab->spousal_2019_proj_policies_male_aig!");
	}

	return policies_male;
}



