#line 1 "surr_chg_inf_fund_val_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::surr_chg_inf_fund_val_calc_aig(
    double fund_value,
    double prem_bonus_recapture,
    double pfwd_entitlement,
    double prorata_gmwb_chg,
    int t)//WTW - Gen2 - Added 't' for policy year lookup
{	
	// 20200228 MTC - Refactored surrender charge
    // Added GMWB charge. MCHING 12-11-2021

	double surr_chg_base = max(fund_value - prorata_gmwb_chg - prem_bonus_recapture - pfwd_entitlement, 0.0);
	
	pol_yr_lookup_gen2 = pol_yr(t);//WTW - Gen2 - surr_chg_pct cannot use time based lookup in an external formula - need to update all instances to use this working variable
	double surr_chg	= surr_chg_pct * surr_chg_base;

	//20240509 MQ surrender charge for renewable myga
	if(myga_renewable_ind == YES && pol_yr(t) > myga_init_term && myga_current_term_aig(t) > 1)
	{
		int shifted_pol_yr = mod(pol_yr(t) - myga_init_term, myga_renew_term);

		if (shifted_pol_yr < SMALL_DOUBLE)
		{
			shifted_pol_yr = myga_renew_term;
		}

		pol_yr_lookup_gen2	= shifted_pol_yr;
		double surr_chg_pc_local = surr_chg_pct_renewal_aig;

		surr_chg = surr_chg_pc_local * surr_chg_base;

		/*log_screen<<"t= "<<t
		<<" pol_yr(t)= "<<pol_yr(t)
		<<" shifted_pol_yr= "<<shifted_pol_yr
		<<" surr_chg_pc_local= "<<surr_chg_pc_local
		<<MSG_USER;*/
	}
	
	return surr_chg;
}



