#line 1 "term_to_omega_age_calc_aig.FIA_LIAB.for"                                                                                   
int FIA_LIAB::term_to_omega_age_calc_aig(StrEnum::EnumValue gender, StrEnum::EnumValue mort_basis)
{
	// 20200428 MTC - Set term_to_omega_age based on final mortality rate.  The seek logic is from WTW.

	int imax = commencement_period + (121 * 12);
	int imin = commencement_period + 1;
	int omega_age = 999;

	while (imax >= imin)
	{
		int imid = (imin + imax) / 2;
		int pol_yr = int((imid + elapsed_mths - 1) / 12 + 1);
		
		double mort_rate = dth_claim_rate_mthly_calc(imid, pol_yr, mort_basis, gender, NONCONFINED/*WTW - Gen2*/);

		if (mort_rate >= 1.0)
		{
			if (imin == imax)
			{
				omega_age = pol_yr - 1;
				break;
			}
			else
			{
				imax = imid;
			}
		}
		else
		{
			if (imin == imax)
			{
	 			break;
			}
			else
			{
				imin = imid + 1;
			}
		}
	}

	if (omega_age == 999)
	{
		omega_age = 121;

		// Unable to find Omega, produce an error msg and return 121
		xstring message;

		message = "Unable to calculate Term at inception to Omega Age. ";
		message += "Mortality rates must ascend to 1. ";
		message += "Plan Code: " + xstring(plan_code);
		message += ", Issue Age: " + xstring(issue_age_mp);
								
		log_screen << message << MSG_ERROR;
		
		if (gen2_defn == NO)
			makeRunLogYellow();	  //WTW - Gen2 - makeRunLogYellow() not supported
	}

	return omega_age;
}



#line 1 "time_between_dates_calc_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::time_between_dates_calc_aig(xstring start_date, xstring end_date) // 20180910 MTC - Ported from VA model
{
	/*!Time between two dates Function
	   ===============================
	   @author Susan Cheung
	   @date 20180205

	   This external function counts the number of days between the start date and the end date and converts the difference into year or partial year (assuming 360 days per year).
   
	   Step 1: Convert the start date into number of days

	   We assume 360 days per year and that is 30 days per month.		
	   	  
	   Step 2: Convert the end date into number of days.

	   Step 3: Take the difference between the two dates.

	   Step 4: Convert the time difference between the two dates into years. 

	   If the end date is an earlier date than the start date (i.e. the difference is negative), then an error message is thrown.
	   Otherwise, the difference will be converted into year or partial year.

	   @param[in] start_date The starting date.
	   @param[in] end_date The ending date.
	    
	   @return time difference in years.
	*/

	int start_date_days;
	int end_date_days;
	double time_difference;

	//Convert the start date into number of days.
	start_date_days = get_yr_from_date(start_date)*360 + get_mth_from_date(start_date)*30 + min(30, get_day_from_date(start_date));

	//Convert the end date into number of days.
	end_date_days = get_yr_from_date(end_date)*360 + get_mth_from_date(end_date)*30 + min(30, get_day_from_date(end_date));

	//Take the difference between the two dates.
	time_difference = end_date_days - start_date_days;

	if (time_difference <= 0)
	{
		throw FatalError("Requested start_date is greater than end_date in time_between_dates_calc_aig.");
	}

	//Convert the time difference between dates into years. (can be partial years)
	time_difference = time_difference/360.;

	return time_difference;
}



