#line 1 "weighted_sum_over_funds_b_aig.FIA_LIAB.for"                                                                                   
double FIA_LIAB::weighted_sum_over_funds_b_aig(const xstring &colname, int t)
{
	/*
		Weighted sum refactor.  MCHING 9-3-2021
	*/

	double total = 0.0;

	for (size_t i = 0; i < sm_fia_account.size(); i++)
	{
		if (fund_val_b(t) > SMALL_DOUBLE)
		{
			// Weigh by current allocation
			total += sm_fia_account[i]->Column(colname).Value(t) * (sm_fia_account[i]->fund_val_b(t) / fund_val_b(t));
		}
		else
		{
			// Weigh by initial allocation
			total += sm_fia_account[i]->Column(colname).Value(t) * (sm_fia_account[i]->fund_val_split_prop);
		}
	}
		
	return total;
}




